window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-hemato-hem-1"]={"block":"medcurso:medcurso-hemato-hem-1","label":"Medcurso · HEM 1","count":412,"questions":[{"id":"medcurso-hemato-hem-1-345463","number":"345463","sourceNumber":"345463","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente de 12 anos, previamente hígida, sem história de febre ou signos\ninflamatórios, comparece à consulta com queixas\nrelatadas pela mãe que incluem palidez, cansaço,\nalteração do humor, tontura, taquicardia, taquipneia leve, dificuldade no aprendizado. A primeira\nhipótese diagnóstica, nessas condições, é:","options":{"A":"Linfoma.","B":"Anemia carencial.","C":"Cardiopatia congênita.","D":"Hemorragia digestiva."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-345470","number":"345470","sourceNumber":"345470","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um paciente de 34 anos de idade procurou atendimento por quadro de astenia há cerca\nde dois meses. Ao exame físico: paciente\ndescorado ++/4; anictérico; hidratado e com fígado\npalpável (três polpas digitais abaixo do rebordo costal). Traube ocupado. Aos exames, Hb 8,5,\nleucócitos 3.300, plaquetas 80.000, VCM 100, HCM 34, RDW 15, DHL 725, bilirrubinas totais 2,\n\nTGO 20, TGP 18, B12 225 (VR 175) e ácido fólico 7 (VR 4). Com base nesse caso hipotético,\nassinale a alternativa que apresenta a conduta mais adequada:","options":{"A":"Convocar equipe da hematologia para biópsia de medula, devido à suspeita de leucemia\nmielóide aguda.","B":"Solicitar dosagem de ácido metilmalônico e homocisteína.","C":"Prescrever corticóide em dose elevada por se tratar de anemia hemolítica autoimune.","D":"Investigar sítio primário de neoplasia."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-345493","number":"345493","sourceNumber":"345493","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Diante de um paciente com anemia ferropriva, o único resultado de exame que NÃO\nesperamos encontrar é o de:","options":{"A":"Níveis aumentados de hepcidina.","B":"Hemoglobina abaixo de 11g/Dl.","C":"Zinco-protoporfirina eritrocitária livre elevada.","D":"Aumento dos receptores séricos de transferrina."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-291754","number":"291754","sourceNumber":"291754","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\nachado mais provável na análise do sangue periférico:","options":{"A":"Hemáceas em fragmentadas e presença de parasitas amastigotas.","B":"Hemáceas em foice e corpúsculos de Howell-Jolly.","C":"Hemáceas em alvo e corpúsculos de Heinz.","D":"Hemáceas hipocrômicas e anisocitose intensa."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-291755","number":"291755","sourceNumber":"291755","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\nexame padrão-ouro para o diagnóstico da principal hipótese diagnóstica:","options":{"A":"Biópsia de medula óssea.","B":"Mielograma.","C":"Eletroforese de hemoglobina.","D":"Biópsia hepática."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-291756","number":"291756","sourceNumber":"291756","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\ntratamento farmacológico mais adequado para a principal hipótese diagnóstica:","options":{"A":"Sulfato ferroso.","B":"Anfotericina B.","C":"Hidroxiureia.","D":"Complexo B e ácido fólico."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-283284","number":"283284","sourceNumber":"283284","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Quanto ao diagnóstico laboratorial das anemias, o encontro de hemoglobina de 9,0 g/dl,\nVCM diminuído < 80 fl e RDW elevado > 14,5 sugere anemia:","options":{"A":"Falciforme.","B":"Ferropriva.","C":"Aplásica.","D":"Megaloblástica."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-281116","number":"281116","sourceNumber":"281116","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação às anemias hipocrômicas e microcíticas:","options":{"A":"A causa mais comum é deficiência de vitamina B12.","B":"Devem ser tratadas com sulfato ferroso.","C":"Devem ser investigadas com mielograma.","D":"Os principais diagnósticos diferenciais são anemia ferropriva, talassemia e anemia de doença\ncrônica.","E":"Os reticulócitos geralmente estão aumentados por se tratar de anemia hiperproliferativa."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-281145","number":"281145","sourceNumber":"281145","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma criança de 5 anos é levada ao Pronto Socorro Pediátrico devido à início súbito de\nfebre e palidez cutâneo mucosa grave. Você coleta um hemograma que evidencia níveis muito\nbaixos de hemoglobina, caracterizando um quadro de Crise Aplásica. O agente viral mais envolvido\nnesses episódios, com potencial de letalidade, é:","options":{"A":"Eritrovírus B19.","B":"Herpes simples tipo 1.","C":"Epstein Bar.","D":"Citomegalovirus.","E":"Influenza A."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-251870","number":"251870","sourceNumber":"251870","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O diagnóstico de anemia hemolítica só pode ser realizado com exames\ncomplementares, entre os exames que devem ser\nrealizados, assinale a alternativa ERRADA:","options":{"A":"Hemograma completo, juntamente com índices de glóbulos vermelhos e contagem de plaquetas.\n\nComo os reticulócitos são células maiores, o volume corpuscular médio nestes pacientes pode ser\naumentado em níveis similares aos encontrados na anemia megaloblástica.","B":"Esfregaço de sangue periférico: pode demonstrar hemácias esferocíticas (como na anemia\nhemolítica autoimune ou esferocitose hereditária). Outras alterações na forma de eritrócitos\ntambém podem ser encontradas.","C":"Lactato desidrogenase (LDH): aumentada nas anemias hemolíticas.","D":"Teste de Coombs direto ou de antiglobulina direto: negativo nas anemias hemolíticas\nautoimunes."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-247174","number":"247174","sourceNumber":"247174","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente do sexo masculino, 56 anos, apresenta quadro de anemia. Queixa-se de\nfraqueza, tontura e sensação de formigamento\nnos pés. O hemograma revela hemoglobina de\n10g/dL, normalidade e hipersegmentação de neutrófilos. Apresenta história de internação hospitalar\nprévia devido a trauma abdominal, tendo sido submetido a laparotomia exploradora e ressecção\ncirúrgica de íleo terminal. Não apresenta, respectivamente, a hipótese diagnóstica mais provável e\no tratamento mais apropriado para a condição.","options":{"A":"Anemia ferropriva - Sulfato ferroso por via oral.","B":"Anemia perniciosa - Vitamina B12 por via oral.","C":"Anemia por deficiência de folato - Ácido fólico por via oral.","D":"Anemia por deficiência de vitamina B12 - Vitamina B12 por via parenteral.","E":"Anemia multicarencial - Ácido fólico, vitamina B12 e sulfato ferroso por via oral."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-247175","number":"247175","sourceNumber":"247175","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente do sexo feminino, 26 anos, apresenta queixa de fadiga e dispneia aos\nesforços. Apresenta pressão arterial de 115/70\nmmHg e a frequência cardíaca de 110 bpm. Ao se\nlevantar, a pressão arterial cai para 95/55 mmHg e a frequência cardíaca se eleva para 128 bpm. O\nhemograma apresenta hemoglobina de 7,8 g/dL, volume corpuscular médio de 74 fL, leucometria\nde 4.300/µL e contagem de plaquetas de 395.000/µL. Assinale a alternativa CORRETA, que\napresenta a hipótese diagnóstica mais provável.","options":{"A":"Anemia ferropriva.","B":"Anemia hemolítica.","C":"Anemia aplástica.","D":"Anemia falciforme.","E":"Anemia perniciosa."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-247188","number":"247188","sourceNumber":"247188","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 6 anos encaminhada ao ambulatório por anemia e icterícia diagnosticadas\nhá cerca de três anos. Nega outras queixas.\nAntecedentes familiares: mãe retirou o baço quando\nera criança devido a anemia. Ao exame físico: bom estado geral, ictérica +/4+, palidez cutânea\n\n+/4+, acianótica, afebril. Fígado não palpável e baço palpável a 2 cm do rebordo costal esquerdo.\nSolicitado exames: Hemoglobina 10,5 g/dL, VCM 90 fl Reticulócitos 8,0% Bilirrubina Total 4,5\nmg/dL, e Direta 1,0 mg/dL. Qual é o melhor exame para confirmar o diagnóstico?","options":{"A":"Eletroforese de hemoglobina.","B":"Dosagem de ferro sérico e ferritina sérica.","C":"Prova de fragilidade osmótica.","D":"Mielograma.","E":"Coombs direto."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-217710","number":"217710","sourceNumber":"217710","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Dentre as hemoglobinopatias, a anemia falciforme é a mais encontrada dentro da\npediatria, sendo CORRETO afirmar que:","options":{"A":"A dactilite aguda falcêmica, se apresentando como síndrome mão-pé, é frequentemente o\nprimeiro surto de que a doença falcêmica está presente em uma criança.","B":"Com o passar dos meses de vida, outras complicações da anemia falciforme tendem a aparecer,\nsendo os episódios vaso-oclusivos mais\nfrequentes entre 3 e 5 anos de vida.","C":"Dificilmente crianças menores, com anemia falciforme, podem ter esplenomegalia associada à\ndoença hemolítica, com progressão para síndrome\ndo hiperesplenismo.","D":"Nos meninos, o priapismo é uma complicação rara, que resulta da concentração do sangue no\ncorpo cavernoso, causando obstrução do fluxo venoso."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-182672","number":"182672","sourceNumber":"182672","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Com relação à anemia ferropriva na infância, marque a alternativa CORRETA:","options":{"A":"Ao avaliar o hemograma percebemos níveis de hemoglobina e HCM baixos, associados ao VCM\nelevado.","B":"Não é a principal causa de anemias na infância.","C":"O tratamento consiste em administração de antihelminticos, complexos contendo ferro na dose\nde 3 a 6 mg/kg/dia de ferro elementar,\nalém de dieta rica em alimentos com boa biodisponibilidade\ndesse elemento.","D":"Indica-se transfusão de concentrado de hemácias a todas as crianças com hemoglobina <7g/dl."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-159063","number":"159063","sourceNumber":"159063","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Quais as alterações que se espera encontrar no hemograma de uma criança com\nanemia ferropriva?","options":{"A":"VCM baixo e RDW baixo.","B":"VCM alto e RDW normal.","C":"VCM baixo e RDW alto.","D":"VCM baixo e RDW normal."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-159070","number":"159070","sourceNumber":"159070","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Beatriz, 4 anos de idade, dá entrada na Unidade de Saúde com importante palidez,\nmas hemodinamicamente estável. O Hemograma evidência\nhemoglobina de 5 g/dI com importante\nmicrocitose e hipocromia. Qual a melhor conduta?","options":{"A":"Internar e fazer ferro endovenoso.","B":"Fazer hemotransfusão.","C":"Prescrever vitamina B12.","D":"Prescrever sulfato ferroso oral e orientação alimentar."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-135977","number":"135977","sourceNumber":"135977","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Pré-escolar de 4 anos dá entrada em unidade de saúde com queixa de febre diária\n38°C há 10 dias, dor em membros inferiores,\npetéquias difusas e aumento de volume abdominal.\nHemograma com 15.000 leucócitos, Bastões 0%, segmentados 10%, Linfócitos 85%, Monócitos\n\n5%, Hb 8,5%, VCM 90, HCM 32, Plaquetas 85.000. Qual o diagnóstico mais provável?","options":{"A":"Meningite meningocócica;","B":"Aplasia de medula óssea;","C":"Anemia carencial;","D":"Leucose aguda;"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-135962","number":"135962","sourceNumber":"135962","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente com quadro de Anemia e contagem de reticulócitos elevada, sem história ou\nexame físico de perda de peso aguda ou\ncrônica, sem nenhum sintoma ou sinal de perda de\nsangue. Qual o provável diagnóstico?","options":{"A":"Aplasia de medula;","B":"Anemia hemolítica;","C":"Anemia ferropriva;","D":"Anemia por deficiência de folato."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-108645","number":"108645","sourceNumber":"108645","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual é o teste laboratorial útil no diagnóstico da anemia falciforme?","options":{"A":"Teste de Coombs.","B":"Eletroforese de hemoglobina.","C":"Diagnóstico morfológico primário.","D":"Haptoglobulina sérica."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-84540","number":"84540","sourceNumber":"84540","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 45 anos, agricultor, morador da zona rural do município de Acrelândia -\nAcre, procura atendimento devido à febre,\ncefaleia, artralgia e calafrios. No exame físico, a única\nalteração era a detecção de febre (temperatura axilar: 38,4ºC). Pesquisa de Plasmodium: duas\ncruzes de P. vivax. Iniciada terapêutica adequada para o caso segundo as normas do Ministério da\nSaúde. Paciente retorna no quarto dia a partir do início do tratamento, apresentando icterícia\nintensa, vômitos e dor abdominal, que diz terem iniciado no dia anterior. Relata desaparecimento\ndos sintomas que apresentara no começo da doença. Provavelmente, a causa desse quadro e a\nconduta serão, respectivamente:","options":{"A":"Hemólise pela primaquina; suspensão do tratamento.","B":"Hemólise pela cloroquina; manter o esquema apenas com primaquina.","C":"Hemólise pelo quinino; substituí-lo pela cloroquina.","D":"Hepatotoxicidade devido à cloroquina e primaquina.","E":"Hepatotoxicidade devido exclusivamente ao quinino."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-66914","number":"66914","sourceNumber":"66914","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Com relação ao tratamento da anemia ferropriva na infância, marque a alternativa\nINCORRETA:","options":{"A":"Deve-se realizar orientação nutricional para uma alimentação com alta biodisponibilidade de\nferro.","B":"Os sais de ferro devem ser ingeridos com alimentos que facilitem a sua absorção, como por\nexemplo, suco de frutas cítricas e leite de vaca.","C":"Prescrever sais de ferro na quantidade de 3 a 5 mg de ferro elementar/kg/dia, fracionado de 2 a\n3 vezes.","D":"O tratamento com ferro deve ser realizado por 3 a 4 meses com a 1ª reavaliação (hemograma)\napós 4 semanas."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-29405","number":"29405","sourceNumber":"29405","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a alternativa incorreta:","options":{"A":"Na presença de hemoglobina C é frequente o achado de hemácias em alvo","B":"Na anemia facilforme é comum o aparecimento de osteomielite por Salmonella SP","C":"Indivíduos com heterozigose para hemoglobina S apresentam anemia discreta.","D":"A deficiência de glicose 6-fosfato-desidrogenase (G6PD) é uma doença hemolítica recessiva\nligada ao cromossomo X.","E":"O teste de fragilidade osmótica é utilizado para o diagnóstico de esferocitose hereditária"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-29366","number":"29366","sourceNumber":"29366","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente com quadro de Anemia microcítica e dosagem de ferritina normal, têm\nprovavelmente?","options":{"A":"Anemia aplásica","B":"Anemia ferropriva","C":"Talassemia","D":"Anemia megaloblástica","E":"Anemia sideroblástica"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-313428","number":"313428","sourceNumber":"313428","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"São os mais pobres, os mais vulneráveis e os menos educados, os mais afetados pela\ndeficiência de ferro. São eles também os mais beneficiados com a reposição. Assinale a alternativa\ncorreta.","options":{"A":"Além da anemia e prejuízo no desempenho físico, intelectual e de trabalho, há relatos de\nfunções neurotransmissoras, imunológicas e inflamatórias\nalteradas e maior risco de infecções.","B":"Além da anemia e prejuízo no desempenho físico, intelectual e de trabalho, há relatos de\nfunções neurotransmissoras, imunológicas e\ninflamatórias alteradas e menor risco de infecções.","C":"Além da anemia e prejuízo no desempenho físico, intelectual e de trabalho, mas não de funções\nneurotransmissoras, imunológicas e inflamatórias alteradas e maior risco de infecções.","D":"Além da anemia e prejuízo no desempenho físico, mas não ocorre intelectual e de trabalho."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-313430","number":"313430","sourceNumber":"313430","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A Ferritina Sérica é o marcador mais utilizado para avaliar as reservas orgânicas de\nferro, sendo correta a alternativa:","options":{"A":"Estando aumentada em caso de deficiência desse mineral, embora seja sujeita a considerável\nvariabilidade biológica e variação entre diferentes técnicas de dosagem.","B":"Estando diminuída em caso de excesso desse mineral, embora seja sujeita a considerável\nvariabilidade biológica e variação entre diferentes técnicas de dosagem.","C":"Estando diminuída em caso de deficiência desse mineral, embora seja sujeita a considerável\nvariabilidade biológica e variação entre diferentes técnicas de dosagem.","D":"Estando diminuída em caso de deficiência desse mineral, embora seja sujeita a considerável\nvariabilidade biológica e nunca variação entre diferentes técnicas de dosagem."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-313432","number":"313432","sourceNumber":"313432","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Os sintomas usuais da Anemia por Deficiência de Ferro (ADF) incluem fraqueza,\ncefaleia, irritabilidade, síndrome das pernas\ninquietas e vários graus de fadiga e intolerância aos\nexercícios ou apetite pervertido, sendo correto que:","options":{"A":"Pica (apetite pervertido por barro ou terra, papéis, amido). Pode ainda ocorrer pica por gelo,\nque\né considerada bastante inespecífica para DF.","B":"Pica (apetite pervertido por barro ou terra, papéis, amido). Mas não pode ocorrer pica por gelo.","C":"Pica por gelo apenas, que é considerada bastante específica para DF.","D":"Pica (apetite pervertido por barro ou terra, papeis, amido). Pode ainda ocorrer pica por gelo,\nque\né considerada bastante específica para DF."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-313435","number":"313435","sourceNumber":"313435","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"No entanto, muitos pacientes com Anemia por Deficiência de Ferro são assintomáticos,\nsem clínica típica e só reconhecem os sintomas\nretrospectivamente, após o tratamento. Assinale a\nalternativa correta.","options":{"A":"Pacientes com ferritina baixa e sem anemia nunca podem ter os mesmos sintomas.","B":"Pacientes com ferritina normal e sem anemia podem ter os mesmos sintomas.","C":"Pacientes com ferritina baixa e com anemia não podem ter os mesmos sintomas.","D":"Pacientes com ferritina baixa e sem anemia podem ter os mesmos sintomas."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-307071","number":"307071","sourceNumber":"307071","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Menino, 8 anos de idade, é trazido pela genitora ao ambulatório com queixa de lesões\nde pele e dor leve em articulações. Relata\nque, há aproximadamente uma semana, apresentou\nfebre, cefaleia, coriza e adinamia. As lesões de pele, por vezes clareiam e retornam; e são pouco\npruriginosas. A genitora informa que o menor é falcêmico. Ao exame, está hipoativo, afebril,\nhipocorado ++/IV. Observa-se rubor facial, concentrado nas bochechas, e exantema macular, de\naspecto rendilhado, em membros, poupando regiões plantares e palmares. Diante do caso, indique\na possível complicação decorrente dessa doença.","options":{"A":"Febre reumática.","B":"Aplasia medular.","C":"Encefalite.","D":"Mielite."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-283709","number":"283709","sourceNumber":"283709","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez,\nqueixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA: 120 x 65\nmmHg, FC: 100 bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas, com\nsopro sistólico panfocal. Fígado palpável a 4 cm do rebordo costal direito e espaço de Traube livre.\nHá ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, identifique o achado\nmais provável na análise do sangue periférico:","options":{"A":"Hemácias em fragmentadas e presença de parasitas amastigotas.","B":"Hemácias em foice e corpúsculos de Howell-Jolly.","C":"Hemácias em alvo e corpúsculos de Heinz.","D":"Hemácias hipocrômicas e anisocitose intensa."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-283710","number":"283710","sourceNumber":"283710","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\nexame padrão-ouro para o diagnóstico da principal hipótese diagnóstica:","options":{"A":"Biópsia de medula óssea.","B":"Mielograma.","C":"Eletroforese de hemoglobina.","D":"Biópsia hepática."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-283711","number":"283711","sourceNumber":"283711","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\ntratamento farmacológico mais adequado para a principal hipótese diagnóstica:","options":{"A":"Sulfato ferroso.","B":"Anfotericina B.","C":"Hidroxiureia.","D":"Complexo B e ácido fólico."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-275971","number":"275971","sourceNumber":"275971","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia falciforme é uma doença do tecido hematopoiético hereditária que se\ncaracteriza por alteração no formato da hemácia, apresentando um tipo de hemoglobina que se\ncristaliza na falta de oxigênio. Relacionados a seguir encontra-se condições e sintomas\nrelacionados a patologia, assinale a que não faz parte da sintomatologia habitual:","options":{"A":"Dores articulares e ósseas e atraso no crescimento.","B":"Tendencia a infecção e feridas nas pernas.","C":"Distúrbios neurológicos, pulmonares e renais.","D":"Priapismo.","E":"Disgeusia."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-279043","number":"279043","sourceNumber":"279043","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale o fator que não é responsável por desencadear dor nos pacientes portadores\nde anemia falciforme.","options":{"A":"Alcalose.","B":"Variação de temperatura.","C":"Infecção.","D":"Desidratação."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-252875","number":"252875","sourceNumber":"252875","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem, 22 anos de idade, procura atendimento médico por alterações de exames\nlaboratoriais de rotina. Assintomático. No\ninterrogatório sistemático, referiu ter notado olhos\namarelados, há cerca de 2 anos, por cerca de 2 dias, mas não procurou atendimento médico. Nega\ncomorbidades. Exame físico sem alterações. Exames laboratoriais com bilirrubinas totais de 2,89\nmg/dl, com bilirrubina indireta de 2,03 mg/dl; AST = 18 U/l (VR = 30); ALT = 16 U/L (VR = 30); FA =\n55 U/L (VR = 100); GGt = 20 U/L (VR = 60) AntiHCV não reagente; AntiHBs reagente; AntiHAV 1gG\nreagente Eletroforense de hemoglobina: HbA1 = 59%; HbA2 = 4%; HbS = 37%. O risco que o filho\ndeste paciente terá de nascer com anemia falciforme, caso a mãe possua traço falcêmico, é de:","options":{"A":"0 (zero)%","B":"25%","C":"50%","D":"100%"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-249396","number":"249396","sourceNumber":"249396","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"No paciente que apresenta diagnóstico de anemia falciforme pelo teste do pezinho, o\nresultado encontrado é:","options":{"A":"HgFSC.","B":"HgFSA.","C":"HgFA.","D":"HgFS."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-249398","number":"249398","sourceNumber":"249398","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Quais das alterações bioquímicas apresentadas abaixo estão relacionadas com a\npresença de hemólise?","options":{"A":"LDH, TGO, bilirrubina, haptoglobina.","B":"TGO, LDH, fosfatase alcalina, amilase.","C":"Haptoglobina, bilirrubina, ferritina, fosfatase alcalina.","D":"Ferritina, TGO, ácido úrico, LDH."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-212225","number":"212225","sourceNumber":"212225","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Na anemia hemolítica, podemos encontrar nos exames laboratoriais as seguintes\nalterações:","options":{"A":"Bilirrubina direta elevada, desidrogenase láctica elevada e haptoglobina elevada.","B":"Bilirrubina indireta elevada, desidrogenase láctica diminuída e haptoglobina elevada.","C":"Bilirrubina indireta elevada, desidrogenase láctica elevada e haptoglobina elevada.","D":"Bilirrubina indireta elevada, desidrogenase láctica elevada e haptoglobina diminuída.","E":"Bilirrubina direta elevada, desidrogenase láctica elevada e haptoglobina diminuída."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-212158","number":"212158","sourceNumber":"212158","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Dadas as afirmativas quanto à Síndrome Torácica Aguda na doença falciforme, I. É a\nforma mais comum de complicação pulmonar. II. Representa um marcador importante de\nmortalidade precoce. III. A presença de infiltrado novo em radiografia de tórax envolvendo pelo\nmenos um segmento pulmonar completo constitui um critério diagnóstico obrigatório. IV. A\nrecorrência da síndrome é associada à hipertensão pulmonar. verifica-se que está(ão) correta(s)","options":{"A":"I, II, III e IV.","B":"I, III e IV, apenas.","C":"II e IV, apenas.","D":"II e III, apenas.","E":"I, apenas."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-219916","number":"219916","sourceNumber":"219916","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 39 anos, vegetariana, comparece ao consultório médico com exames\nadmissionais que evidenciam anemia macrocítica associada a níveis séricos de vitamina B12\ndiminuídos. Marque a alternativa INCORRETA sobre essa afecção:","options":{"A":"Alterações nas células mucosas geram glossite, anorexia e diarreia.","B":"Conversão da homocisteína em metionina está aumentada.","C":"Elevação sérica da lactato desidrogenase e da bilirrubina indireta são secundárias à destruição\nmedular das células eritroides.","D":"Parestesias e distúrbios do equilíbrio e propriocepção são manifestações neurológicas."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-215228","number":"215228","sourceNumber":"215228","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Anemia Aplástica (AA) ou aplasia de medula óssea é uma doença rara, caracterizada\npor pancitopenia moderada a grave no sangue\nperiférico e hipocelularidade acentuada na medula\nóssea, sendo a mais frequente das síndromes de falência medular. Está inadequado que:","options":{"A":"Estima-se que a incidência de AA adquirida seja de 2-4 pessoas por 1.000.000 ao ano, com três\npicos de incidência.","B":"Pico de incidência ocorre primeiro entre os indivíduos de 10-25 anos e outro Pico de incidência\nnos maiores de 60 anos, sem diferenças entre os\nsexos.","C":"Há relatos de que populações de origem asiática têm maior incidência da doença.","D":"Na AA por causas congênitas, o pico de incidência parece situar-se entre 2-5 anos de idade."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-215254","number":"215254","sourceNumber":"215254","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O diagnóstico de Anemia Aplástica AA é realizado pela associação dos seguintes\nachados: pancitopenia no sangue periférico\n(hemoglobina menor de 10 g/dl, plaquetas <\n50.000/mm3 e neutrófilos < 1.500/mm3), baixa contagem de reticulócitos (abaixo do limite\nconsiderado normal pelo método) e medula óssea hipocelular à biópsia, com diminuição de todos\nos elementos hematopoiéticos e seus precursores, na ausência de células estranhas à medula\nóssea, fibrose ou hematofagocitose. Sobre isso, podemos aceitar que:","options":{"A":"Pacientes com AA têm maior probabilidade de desenvolver mielodisplasias e doenças\nneoplásicas hematológicas do que a população geral.\nAs análises citogenética e imunofenotípica\ncomplementares não podem auxiliar na diferenciação diagnóstica, porém isoladamente não devem\nser utilizadas como ferramenta diagnóstica.","B":"Pacientes com AA têm maior probabilidade de desenvolver mielodisplasias e doenças\nneoplásicas hematológicas do que a população geral.\nAs análises citogenética e imunofenotípica\ncomplementares podem auxiliar na diferenciação diagnóstica, porém isoladamente não devem ser\nutilizadas como ferramenta diagnóstica.","C":"Pacientes com AA têm maior probabilidade de desenvolver mielodisplasias e doenças\nneoplásicas hematológicas do que a população geral. As\nanálises citogenética e imunofenotípica\ncomplementares podem auxiliar na diferenciação diagnóstica, isoladamente devem ser utilizadas\ncomo ferramenta diagnóstica.","D":"Pacientes com AA têm menor probabilidade de desenvolver mielodisplasias e doenças\nneoplásicas hematológicas do que a população geral.\nAs análises citogenética e imunofenotípica\ncomplementares podem auxiliar na diferenciação diagnóstica, porém isoladamente não devem ser\nutilizadas como ferramenta diagnóstica."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-215293","number":"215293","sourceNumber":"215293","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A grande maioria dos casos de Anemia Aplástica AA é adquirida, com uma pequena\nproporção de pacientes apresentando a forma\ncongênita da doença. São suas formas\nconstitucionais as listadas abaixo, indique a que foge ao contexto:","options":{"A":"Disceratose congênita.","B":"Anemia de Fanconi.","C":"Manifestação idiossincrática.","D":"Síndrome de Shwachman-Diamond."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-182793","number":"182793","sourceNumber":"182793","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à Síndrome Torácica Aguda, assinale a alternativa CORRETA:","options":{"A":"A oxigenioterapia está indicada apenas em hipoxemia severa.","B":"Caracteristicamente não há dor torácica.","C":"Podem ocorrer infartos pulmonares.","D":"A mortalidade é extremamente baixa."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-181384","number":"181384","sourceNumber":"181384","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, sexo feminino, foi encaminhada para o ambulatório para investigação de\nanemia. Trazia um hemograma com Hb: 9 mg/dl\ne VCM: 115. Após investigação completa, foi\ndiagnosticada com Anemia Perniciosa. A respeito desse assunto, dadas as afirmativas: I. É a causa\nmais comum de deficiência de vitamina B12; II. É mais frequente antes dos 30 anos de idade; III.\nAnticorpos anticélulas parietais e os anticorpos antifator intrínseco são os principais\nautoanticorpos;\n\nIV. Não existe associação com câncer gástrico. Verifica-se que está(ão) correta(s):","options":{"A":"II, apenas.","B":"I e II, apenas.","C":"I e III, apenas.","D":"III e IV, apenas.","E":"I, II, III e IV."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-183039","number":"183039","sourceNumber":"183039","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação à anemia ferropriva.","options":{"A":"Segundo a Organização Mundial de Saúde define-se anemia como uma ?condição na qual o\nconteúdo de hemoglobina no sangue está abaixo do normal ou como resultado da carência de um\nou mais nutrientes essenciais, seja qual for a causa dessa deficiência?, no caso da anemia\nferropriva há deficiência de ferro.","B":"A anemia ferropriva traz os seguintes efeitos adversos ou consequências: diminuição da\nprodutividade e da capacidade de aprendizado,retardo do crescimento e apatia.","C":"A dieta inadequada não estána lista das causas de anemia ferropriva.","D":"Sinais e sintomas da carência de ferro são inespecíficos, necessitando de exames laboratoriais\npara que seja confirmado o\n\ndiagnóstico de anemia ferropriva."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-183083","number":"183083","sourceNumber":"183083","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"As gestantes têm maior risco de desenvolver Deficiência de Ferro (DF), e Anemia\n(ADF) pelas altas demandas fisiológicas\npróprias e da unidade feto?placentária, difíceis de serem\nsupridas apenas pela dieta, além da perda sanguínea que pode ocorrer durante o parto. Em\nrelação a isso, assinale a alternativa INCORRETA:","options":{"A":"Devido à anemia, essas mulheres têm menor ganho de peso durante a gestação.","B":"Existe uma forte relação entre o status de ferro da mãe e a depressão, o stress, as funções\ncognitivas e as interações mãe-filho, mas a deficiência de ferro não afeta o seu humor e as\ninterações com o RN, e a suplementação não protege contra estes efeitos.","C":"A ADF na gestação é frequentemente diagnosticada e tratada, mas os efeitos destes\ntratamentos permanecem largamente desconhecidos e\nmais pesquisas precisam ser realizadas\npara melhorar o prognóstico materno e neonatal de mulheres com anemia moderada e grave em\nlugares com poucos recursos.","D":"Devido à anemia, essas mulheres têm maiores riscos de partos prematuros, placenta prévia,\nhemorragias, ruptura prematura de membranas, pré-eclâmpsia, eclâmpsia, sepsis pós-natal, maior\nrisco de morte, menor desempenho laboral, fadiga, fraqueza e dispneia"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-183116","number":"183116","sourceNumber":"183116","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A prevalência de anemia por DF (ADF) aumenta em populações com carências\nnutricionais; com ingestão ou absorção inadequada\nde ferro. Dessa forma, assinale a interação\ndescrita de maneira INADEQUADA:","options":{"A":"Hábitos vegetarianos; dietas com muito chá ou café, que aumentam a absorção de ferro.","B":"Sem vitamina C (frutas cítricas), que favorece a sua absorção.","C":"Baixo nível socioeconômico e educacional.","D":"Presença de infestações endêmicas (malária, ascaridíase, helmintoses, protozooses intestinais)."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-183124","number":"183124","sourceNumber":"183124","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Os sintomas usuais da Anemia por Deficiência de Ferro incluem fraqueza, cefaleia,\nirritabilidade, síndrome das pernas inquietas e\nvários graus de fadiga e intolerância aos exercícios\nou pica (apetite pervertido por barro ou terra, papeis, amido). Sendo INCORRETO apenas que:","options":{"A":"No entanto, muitos pacientes são assintomáticos, sem clínica típica e só reconhecem os\nsintomas retrospectivamente, após o tratamento.","B":"Pacientes com ferritina baixa e sem anemia podem ter os mesmos sintomas.","C":"Pode ainda ocorrer pica por gelo, que é considerada pouco específica para Deficiência de Ferro.","D":"Idosos costumam apresentar início insidioso com sintomas relacionados à exacerbação de suas\ncomorbidades subjacentes (piora da angina, aumento da confusão mental, dispneia)."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-181433","number":"181433","sourceNumber":"181433","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assim como ocorre nos lactentes, os adolescentes são uma população de risco para\nanemia ferropriva. A recomendação de 8 a 15 mg/kg/dia de ferro nessa fase se deve a:","options":{"A":"carências nutricionais por maior demanda energética.","B":"aumento do volume sanguíneo e diminuição da massa das hemácias.","C":"aumento de necessidades específicas para ganho\npondero-estatural.","D":"pico na velocidade de crescimento e aumento na massa das hemácias.","E":"dietas restritas e monótonas, especialmente em relação ao consumo de vegetais."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-183119","number":"183119","sourceNumber":"183119","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A ADF ? Anemia por Deficiência de Ferro na gestação é frequentemente diagnosticada\ne tratada, mas os efeitos destes tratamentos\npermanecem largamente desconhecidos e mais\npesquisas precisam ser realizadas para melhorar o prognóstico materno e neonatal de mulheres\ncom anemia moderada e grave em lugares com poucos recursos. Sobre esse tema, assinale a\nalternativa INCORRETA:","options":{"A":"Pode também apontar para uma doença grave subjacente com sangramento oculto, que deve\nser afastada com investigação\n\nadequada em homens e mulheres na pós-menopausa, principalmente no que diz respeito ao\ndiagnóstico precoce da doença Maligna Colorretal.","B":"Independente da etiologia, quando o sangue tem células vermelhas insuficientes ou estas\ncarregam hemoglobina insuficiente\n\npara entregar oxigênio dequadamente para os tecidos significa que houve falha na produção das\nhemácias e sobrevém anemia,\n\nmuitas vezes multifatorial num mesmo indivíduo e por isto uma síndrome complexa para avaliação\ne estabelecimento da conduta a adotar.","C":"Alta prevalência de anemia não está associada à idade avançada e a condições agudas ou\ncrônicas, como a Doença Renal Crônica. Em\npessoas com 85 ou mais anos, a prevalência é de 5%\npara homens e de 20% para mulheres.","D":"Além disto, a ADF pode ser causada por hemorragias diversas, como as devidas a traumas ou\npor melena, hematêmese, hemoptise, menstruações, partos ou por múltiplas gestações."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-152636","number":"152636","sourceNumber":"152636","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactente alimentado predominantemente com leite de cabra, poderia apresentar qual\ndeficiência?","options":{"A":"Piridoxina.","B":"Cálcio.","C":"Ácido Fólico.","D":"Ferro.","E":"Ácido ascórbico."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-158817","number":"158817","sourceNumber":"158817","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Anemias hemolíticas podem ser classificadas quanto ao local que ocorre a hemólise,\nsendo denominadas intra ou extravascular. Podem\ntambém ser classificadas de acordo com as\ncausas, como defeito intrínseco ou extrínseco as hemácias. Qual a causa de anemia hemolítica por\ndefeito intrínseco das hemácias?","options":{"A":"Hiperesplenismo.","B":"Deficiência de G6PD.","C":"Estenose de valva aorta.","D":"Anemia hemolítica autoimune.","E":"Hemoglobinúria paroxística noturna."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-161246","number":"161246","sourceNumber":"161246","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Podemos entender sobre as síndromes betatalassêmicas como um grupo de doenças\nhereditárias caracterizadas por uma deficiência genética na síntese de cadeias beta de globina.\n\nSobre isso, aponte a alternativa INCORRETA.","options":{"A":"A betatalassemia afeta um ou ambos os genes da betaglobina (cromossoma 11).","B":"Estas mutações pontuais, ou mais comumente deleções, causando uma inadequada síntese de\nbetaglobina, componente da hemoglobina, resultam em anemia.","C":"Ela é herdada como uma doença autossômica recessiva; no entanto, mutações dominantes\ntambém foram relatadas.","D":"O defeito pode ser uma ausência completa da proteína betaglobina."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-161251","number":"161251","sourceNumber":"161251","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"São fatores adicionais que influenciam as manifestações clínicas da Síndrome\nTalassêmica, ou seja, as mesmas mutações podem ter diferentes manifestações clínicas em\npacientes diferentes. Os seguintes fatores são conhecidos por influenciar o fenótipo clínico,\nEXCETO por","options":{"A":"concentrações de hemoglobina fetal intracelulares.","B":"anemia com necessidade de transfusão de hemácias.","C":"co-hereditariedade com talassemia alfa.","D":"coexistência de traço falciforme."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-158791","number":"158791","sourceNumber":"158791","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Kauê, dezesseis meses de vida, foi submetido a exames complementares: dosagem de\nferritina: 8 mcg/dl; ferro sérico: 25 mcg/dl; hemoglobina: 9 g/dl. Nesse caso, qual o diagnóstico\nmais\nprovável e a melhor conduta?","options":{"A":"Não tem anemia ferropriva e também não há indicação de iniciar profilaxia com ferro.","B":"Tem anemia ferropriva e já deve iniciar tratamento com 2 mg de ferro elementar/kg/dia.","C":"Tem anemia ferropriva e já deve iniciar tratamento com 5 mg de ferro elementar/kg/dia.","D":"Não tem anemia ferropriva, porém já se deve iniciar profilaxia com 2 mg de ferro\nelementar/kg/dia até os dois anos de vida.","E":"Não tem anemia ferropriva, porém já se deve iniciar profilaxia com 1 mg de ferro\nelementar/kg/dia até os dois anos de vida."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-131418","number":"131418","sourceNumber":"131418","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Você está atendendo em uma Unidade Básica de Saúde e recebe uma mãe trazendo\nseu filho de 1 ano para consultar dizendo que\no menor tem falta de apetite e está muito pálido. A\nimunização está em dia e sua alimentação atual é leite com arrozina. Não refere outras queixas. Ao\nexame apresenta bom estado geral, eupneico, hidratado, afebril. Palidez cutâneo-mucosa (+++/4+).\nOuvido, nariz e garganta normais. AC = bulhas normofonéticas e normorrítmicas. AP = Pulmões\nlimpos. Abdome flácido, sem megalias. Genitais e membros inferiores sem alterações. Qual a\nprincipal hipótese diagnóstica?","options":{"A":"Anemia de doenças crônicas.","B":"Anemia megaloblástica.","C":"Anemia ferropriva.","D":"Anemia macrocítica.","E":"Anemia falciforme."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-131324","number":"131324","sourceNumber":"131324","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 6 meses, nunca mamou, apresentando anorexia, irritabilidade, e perda de\npeso há dois meses. Ao exame físico\napresenta palidez cutâneo-mucosa +++, fígado 2 cm RCD,\nbaço 2 cm RCE. No hemograma encontrou: Hb 6,0gdl; Hto 20%; Hem 2.600.000; Leuco 7200 \\mm3\n( bast2, seg36, baso0, eosi0, linf59, mono3) plaquetas 280.000\\mm3. Retic 0,3. Morfologia das\nhemácias: microcitose+++; hipocromia+++; poiquilocitose+; ?cigar cells?+. O diagnóstico mais\nprovável é:","options":{"A":"Anemia ferropriva.","B":"Anemia microesferocítica.","C":"Leucemia.","D":"Anemia falciforme.","E":"Anemia hemolítica."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-131328","number":"131328","sourceNumber":"131328","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale o conjunto de sinais e sintomas que geralmente estão presentes nas anemias\nhemolíticas na infância:","options":{"A":"Anemia, icterícia, esplenomegalia, hemoglobinúria e reticulocitose.","B":"Icterícia, petéquias, hepatomegalia, esplenomegalia e reticulocitose.","C":"Adenomegalia, icterícia, esplenomegalia, equimoses e reticulocitopenia.","D":"Hematúria, esplenomegalia, prurido, adenomegalia e anemia.","E":"Anemia, icterícia, equimoses, petéquias e reticulocitopenia."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-134792","number":"134792","sourceNumber":"134792","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação às anemias carenciais, podemos afirmar que","options":{"A":"o diagnóstico laboratorial da anemia ferropriva inclui ferro sérico e ferritina sérica baixos,\ncapacidade total de ligação de ferro\n\nbaixa e saturação de transferrina alta.","B":"a deficiência de B12 e as talassemias são exemplos clássicos de anemias macrocíticas.","C":"nas crianças com anemia hemolítica esferocítica, está contraindicado o uso de sulfa e\nquinolonas.","D":"baixo peso ao nascimento, desmame precoce e baixa disponibilidade de ferro na dieta\npredipõem às anemias ferroprivas."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-109992","number":"109992","sourceNumber":"109992","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente do sexo masculino, 35 anos, com antecedente de Anemia Falciforme,\napresenta no esfregaço de sangue periférico corpúsculos de Howell-Jolly. Assinale abaixo o\nsignificado desse achado.","options":{"A":"Crise de falcização.","B":"Processo infeccioso viral.","C":"Hipoesplenismo.","D":"Deficiência de folato."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-110542","number":"110542","sourceNumber":"110542","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A deficiência de ferro em lactentes e crianças maiores acompanha-se clinicamente de\ntodos os sinais e sintomas, EXCETO:","options":{"A":"Irritabilidade.","B":"Geofagia.","C":"Hipertrofia das papilas gustativas.","D":"Anorexia.","E":"Palidez."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-86879","number":"86879","sourceNumber":"86879","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Nas anemias por carência de ferro, a capacidade de ligação de ferro total e ferritina\nsérica mostram, respectivamente, o seguinte\npadrão:","options":{"A":"Aumentado ? diminuído;","B":"Aumentado ? normal;","C":"Diminuído ? normal;","D":"Diminuído ? aumentado;","E":"Normal ? aumentado."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-86873","number":"86873","sourceNumber":"86873","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactente feminino, 20 meses de idade, é levado para consulta de puericultura sem\nqueixas. Usou leite materno até o quarto mês\nde vida, quando começou a usar a alimentação\ncomplementar adequada e também leite de vaca 6 vezes ao dia. Não usa ou usou medicamento\nalgum. Trouxe um hemograma que mostra Hb = 9,2 g/dl, VCM = 61 micro3, RDW = 18%. Assinale\na alternativa que apresenta o diagnóstico MAIS PROVÁVEL para o quadro acima.","options":{"A":"Anemia falciforme.","B":"Talassemia minor.","C":"Esferocitose hereditária.","D":"Anemia ferropriva.","E":"Anemia hemolítica autoimune."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-49593","number":"49593","sourceNumber":"49593","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Para saber como anda a reserva de ferro de uma criança para avaliação de anemia, o\nexame adequado a solicitar é:","options":{"A":"Dosagem de hemoglobina.","B":"Dosagem de cálcio sérico.","C":"Dosagem de ferritina.","D":"Saturação de transferrina.","E":"Dosagem de reticulócitos."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-49597","number":"49597","sourceNumber":"49597","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"No teste do pezinho, qual resultado sugere anemia falciforme?","options":{"A":"Padrão FA.","B":"Padrão FAZ.","C":"Padrão FSA.","D":"Padrão FS.","E":"Nenhuma das respostas anteriores."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-327283","number":"327283","sourceNumber":"327283","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"PSD, 9 anos, sexo feminino, natural e procedente da zona rural de Itacoatiara-AM,\nresidente em área, sem rede de esgoto e sem\ntratamento de água. Queixa de dores abdominais,\napresenta-se apático e só quer permanecer deitado. Ao exame, observa-se palidez cutânea, pele\ncom aspecto amarelado, embora não esteja ictérico. Na ausculta cardíaca: sopro sistólico ++/6+,\nem foco mitral sem irradiação, sem frêmito. Hemograma de urgência: Hg- 8,3g/dL; Ht-25%; VCM-\n63fl e RDW-21,5%. O diagnóstico mais provável e uma possível etiologia seria:","options":{"A":"Amenia Ferropriva secundária à Ancilostomíase.","B":"Anemia Megaloblástica secundária à dieta com leite de cabra.","C":"Beta-talassemia secundária à erro inato do metabolismo.","D":"Anemia de doença crônica secundária à Doença Inflamatória Intestinal."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-286762","number":"286762","sourceNumber":"286762","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Ana, 2 anos, foi diagnosticada com anemia ferropriva e recebeu prescrição de sulfato\nferroso 5 mg/kg/dia de ferro elementar. O\nparâmetro laboratorial mais específico para o diagnóstico\nde anemia por deficiência de ferro e o parâmetro laboratorial de resposta mais precoce ao\ntratamento são, respectivamente:","options":{"A":"Ferritina e hematócrito.","B":"Ferritina e reticulócitos.","C":"Ferro sérico e hematócrito.","D":"Ferro sérico e reticulócitos."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-252221","number":"252221","sourceNumber":"252221","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considerando as anemias hemolíticas autoimunes (AHAI), assinale a alternativa\nCORRETA:","options":{"A":"O teste de Coombs indireto detecta anticorpos na superfície das hemácias, enquanto o teste de\nCoombs direto detecta anticorpos no soro.","B":"A terapia com ciclosporina é a medida terapêutica de 1ª linha nas AHAI por anticorpos quentes.","C":"O teste de Coombs direto negativo na maioria das vezes, afasta a hipótese de anemia\nhemolítica.","D":"Anticorpos da classe IgM são os principais responsáveis pelas AHAI por anticorpos quentes,\ncausando hemólise extravascular."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-252281","number":"252281","sourceNumber":"252281","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Pré-escolar de 02 anos, portador de anemia falciforme, é levado à emergência\napresentando dor abdominal, palidez acentuada\n(Hg 3 g/dl), hipovolemia, reticulocitose, taquicardia,\ntaquipneia, prostração, baço 5 cm do Rebordo Costal Esquerdo (RCE). A hipótese diagnóstica mais\nprovável é:","options":{"A":"Sequestro esplênico.","B":"Crise aplástica.","C":"Colelitíase aguda.","D":"Hepatite A."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-208410","number":"208410","sourceNumber":"208410","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A doença falciforme é uma alteração genética caracterizada por um tipo de\nhemoglobina mutante designada por hemoglobina S\n(ou Hb S) que provoca a distorção dos\neritrócitos, fazendo-os tomar a forma de \"foice\" ou \"meia-lua\". Avalie se as afirmativas a seguir\nsão\nfalsas (F) ou verdadeiras (V): I. O exame diagnóstico é a eletroforese de hemoglobina em acetato\nde celulose ou em agarose. II. A crise vaso-oclusiva é a principal característica da doença, resulta\nde um conjunto de interações do endotélio, fatores plasmáticos, leucócitos, falcização e rigidez\neritrocitária. III. As úlceras de perna podem estar presentes nos portadores de doença falciforme.\nAssinale a alternativa CORRETA:","options":{"A":"F, V e F","B":"V, V e F","C":"V, V e V","D":"F, V e V"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-208353","number":"208353","sourceNumber":"208353","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactente de 11 meses, sexo feminino, foi atendida no serviço de ambulatório pois a\nmãe queixa de quadro de irritabilidade,\nanorexia, letargia e palidez. Ao exame, observamos palidez\nnas palmas das mãos, nos vincos palmares, unhas e conjuntiva. Tem exames laboratoriais com os\nseguintes resultados: hemoglobina = 9 g/dl; VCM < 70 mg/l; saturação da transferrina < 16%, RDW\naumentado e ferritina sérica diminuída. Qual o diagnóstico desta anemia?","options":{"A":"Anemia megaloblástica.","B":"Anemia ferropriva.","C":"Anemia falciforme.","D":"Anemia da doença crônica."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-151881","number":"151881","sourceNumber":"151881","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança com 15 meses de idade, apresentou as seguintes manifestações clínicas:\nretardo do crescimento, hepatomegalia,\nhipoglicemia grave, colesterol, triglicerídeos e ácido úrico\nelevados. Qual o defeito básico, característico nas doenças do metabolismo do carboidrato:","options":{"A":"Deficiência da enzima de ramificação.","B":"Deficiência de glicogênio síntetase.","C":"Deficiência de fosforilase hepática.","D":"Deficiência de glicose-6-fosfatase."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-151888","number":"151888","sourceNumber":"151888","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Pré-escolar de 3 anos apresenta \"palidez\" nas palmas da mão, pregas palmares, leito\nungueal e conjuntivas, irritabilidade, anorexia, hemoglobina = 7 g/dl, RDW (índice de anisocitose)\n17%, VCM = 55 m³. A dieta da família é adequada, com boas condições socioeconômicas. Qual o\nexame abaixo mais indicado para a investigação da \"palidez\"?","options":{"A":"Hematoscopia.","B":"Parasitológico.","C":"Dosagem de ferritina.","D":"Pesquisa de sangue oculto nas fezes."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-129816","number":"129816","sourceNumber":"129816","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher, 52 anos, no período de climatério, queixa-se de cansaço em suas atividades\ndiárias, sem outros sintomas. O exame clínico\né normal, exceto pelas mucosas discretamente\nhipocoradas. O hemograma mostra hemoglobina = 10 g/dl; hematócrito = 31%; VCM = 76 fl;\nferritina = 10 ng/ml; ferro = 60 µg/dl e capacidade total de ligação do ferro = 420 µg/dl. O\nprocedimento necessário para o diagnóstico da síndrome anêmica é:","options":{"A":"Investigar presença de sangue oculto nas fezes e o trato digestivo.","B":"Solicitar ureia e creatinina para o diagnóstico de insuficiência renal.","C":"Solicitar TSH, pois é comum hipotireoidismo em mulheres nesta faixa etária.","D":"Iniciar sulfato ferroso e acompanhar com hemograma seriado."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-129761","number":"129761","sourceNumber":"129761","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A carência nutricional de ferro afeta o desenvolvimento mental de 40 a 60% das\ncrianças. Assinale a alternativa com as\nprincipais alterações bioquímicas encontradas na depleção\nde ferro SEM anemia:","options":{"A":"Hgb, VCM, RDW normais; ferro sérico e ferritina baixos.","B":"Hbg, ferro sérico e ferritina baixos; RDW e VCM normais.","C":"Hgb, ferro sérico, ferritina e VCM baixos; RDW normal.","D":"Hbg, VCM normais; RDW elevado; ferro sérico e ferritina baixos."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-103835","number":"103835","sourceNumber":"103835","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem de 55 anos procura atendimento médico no ambulatório Araújo Lima, informa\nque tem se sentido mal, relata astenia, às\nvezes, soluços, \"tique nervoso\", e que ao escrever sente\nsua mão tremendo. Trouxe hemograma com: Hto = 26% e Hb = 6,8. Sua urina é \"normal\". É\ndiabético há 15 anos. Qual o possível diagnóstico?","options":{"A":"Anemia ferropriva.","B":"Neuropatia a esclarecer. Encaminhar ao neurologista.","C":"Anemia a esclarecer. Possível insuficiência renal.","D":"Alcoolismo crônico. Encaminhar ao gastro."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-103840","number":"103840","sourceNumber":"103840","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem de 55 anos procura atendimento médico no Ambulatório Araújo Lima, informa\nque tem se sentido mal, relata astenia, às\nvezes, soluços, \"tique nervoso\", e que ao escrever sente\nsua mão tremendo. Trouxe Hemograma com Hto 26% e Hb 6,8. Sua urina é \"normal\". É diabético\nhá 15 anos. Que/quais exames poderiam ser solicitados na sua investigação?","options":{"A":"Proteinúria de 24h.","B":"Glicemia, uréia, creatinina, sódio, potássio, reticulócitos, VCM, USG rins, próstata, EAS, estudo\ndo ferro.","C":"Estudo do ferro e eletroforese de albumina.","D":"Urinocultura para pesquisa de Clamídia."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-81998","number":"81998","sourceNumber":"81998","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação ao papel do hemograma com hematoscopia na avaliação de distúrbios\nhematológicos e do baço, é INCORRETO:","options":{"A":"Reticulocitose e esplenomegalia de tamanho médio são possíveis nas anemias hemolíticas.","B":"Pancitopenia e esplenomegalia maciça podem estar presente na mielofibrose.","C":"Esquizócitos e esplenomegalia afastam o diagnóstico de anemia hemolítica autoimune.","D":"Na leucemia de células cabeludas (tricoleucemia) a esplenomegalia é comum e os linfócitos têm\naspecto hematoscópico característico.","E":"Tanto a reação leucemoide como a leucemia mieloide crônica podem ter desvio à esquerda."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-61539","number":"61539","sourceNumber":"61539","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem, 50 anos, com diagnóstico de osteoartrite e uso intermitente de AINH, procura o\nambulatório de Clínica Médica devido ao diagnóstico de anemia. Queixa-se de fadiga com\nfacilidade, taquicardia aos esforços e epigastralgia. Trouxe hemograma com Hb = 10 g/dl, Ht =\n35%, microcitose, hipocromia, anisocitose e ferritina sérica de 20 mcg/l. Em uso de sulfato ferroso\n325 mg 3x/dia. Qual o diagnóstico diferencial e a investigação complementar necessária?","options":{"A":"Talassemia e capacidade de ligação do ferro total.","B":"Perda oculta de gastrointestinal e sangue oculto nas fezes.","C":"Perda oculta gastrointestinal e endoscopia digestiva alta.","D":"Anemia de doença crônica e capacidade de ligação de ferro total.","E":"Anemia de doença crônica e ferro sérico."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-60891","number":"60891","sourceNumber":"60891","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre o RDW (red cell distribution width) é INCORRETO:","options":{"A":"Valores de normalidade entre 11% e 16%.","B":"Corresponde a uma medida quantitativa da anisocitose.","C":"Valores aumentados de RDW falam a favor de uma população eritrocitária homogênea.","D":"É obtido a partir do histograma de distribuição das hemácias de acordo com o volume das\ncélulas.","E":"Sua principal utilidade seria numa primeira diferenciação entre a anemia ferropriva e a\nbeta-talassemia heterozigótica."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-61531","number":"61531","sourceNumber":"61531","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação aos estágios da deficiência de ferro no organismo, é CORRETO afirmar:","options":{"A":"Depleção de estoque; Hemoglobina normal; VCM diminuído; Ferro sérico diminuído; Ferritina\nnormal.","B":"Depleção de ferro com anemia; Hemoglobina diminuída; VCM normal; Ferro sérico diminuído;\nFerritina normal.","C":"Depleção de estoque; Hemoglobina aumentada; VCM diminuído; Ferro sérico normal; Ferritina\ndiminuída.","D":"Depleção de ferro sem anemia; hemoglobina normal; VCM normal; Ferro sérico diminuído;\nFerritina diminuída.","E":"Depleção de ferro com anemia; Hemoglobina diminuída; VCM aumentado; Ferro sérico\ndiminuído; Ferritina normal."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-61546","number":"61546","sourceNumber":"61546","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"São fatores de risco para o desenvolvimento de anemia ferropriva, EXCETO:","options":{"A":"Aleitamento materno exclusivo até os 6 meses de vida e complementar até 2 anos de idade.","B":"Ocorrência de pólipos e divertículos.","C":"Desnutrição intrauterina.","D":"Prematuridade.","E":"Baixa renda."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-61581","number":"61581","sourceNumber":"61581","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à presença de anemias na infância qual afirmativa NÃO está correta?","options":{"A":"As anemias podem ser decorrentes de alterações na produção; hemólise; perdas sanguíneas.","B":"Correspondem a desordens de produção; desordens imunológicas; falência absoluta da\neritropoiese.","C":"O VCM (Volume Corpuscular Médio) está aumentado na deficiência da vitamina B12 e na\ndeficiência de ácido fólico.","D":"São consideradas desordens por destruição do eritrócito; defeitos estruturais das hemáceas\n(congênitos); desordens imunológicas; destruição não mediada por anticorpos.","E":"A doença falciforme, as talassemias e as deficiências enzimáticas cursam com anemia devido a\ndesordens por destruição dos eritrócitos (hemólise)."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-60819","number":"60819","sourceNumber":"60819","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Na anemia hipocrômica microcítica por deficiência ou falta de aproveitamento de ferro\nencontra-se:","options":{"A":"CHCM e VCM normal, RDW baixo","B":"CHCM e VCM baixo, RDW normal","C":"CHCN e VCN baixo, RDW aumentado","D":"CHCM e VCM aumentdo, RDW baixo","E":"CHCM e VCM aumentando, RDW aumentado"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-46712","number":"46712","sourceNumber":"46712","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Analise as afirmativas quanto à Anemia Ferropriva e assinale a INCORRETA:","options":{"A":"O melhor exame para estimar o ferro total do organismo, particularmente o dos depósitos, é o\nferro sérico.","B":"Os principais sinais e sintomas são palidez, adinamia, cefaleia, tontura, zumbido no ouvido,\nalterações na visão, dispneia, taquicardia e baixo desempenho no trabalho.","C":"É uma manifestação tardia e insidiosa da carência do ferro e surge quando as reservas de ferro\nesgotam-se em virtude do balanço negativo.","D":"As causas de carência podem ser classificadas: menor ingestão do nutriente, menor absorção\nintestinal, defeitos do transporte ou\nmetabolismo, aumento das excreções ou das perdas, aumento\ndas necessidades fisiológicas ou patológicas.","E":"A mais importante medida do tratamento desta anemia consiste em identificar a causa e\nremovê-la, se possível."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-46669","number":"46669","sourceNumber":"46669","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Pré-escolar com quatro anos vai a sua pediatra, trazido pela sua genitora, com história\nde palidez. A criança está com bom estado geral,\na alimentação é adequada e a família é de bom\nnível socioeconômico. O pai é de origem portuguesa e a mãe é italiana. Quanto ao exame\nlaboratorial: Hb: 10 g/dl; VCM: 60: SEM ANISOCITOSE. Não houve alteração de laboratórios após\ntratamento com ferro por um mês. O resultado mais provável da eletroforese de hemoglobina é:","options":{"A":"Presença de HbS.","B":"Presença de HbS e HbC.","C":"HbA2 baixa e HbF baixa.","D":"HbA2 elevada e presença de HbS.","E":"HbA2 elevada e HbF aumentada."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-34113","number":"34113","sourceNumber":"34113","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia por deficiência de ferro caracteriza-se, sobretudo por:","options":{"A":"Macrocitose, hipocromia e neutrófilos grandes com núcleo hipersegmentado.","B":"Microcitose, hipocromia e RDW alto.","C":"Microcitose, hipocromia, células em alvo e pontilhado basófilo no esfregaço de sangue\nperiférico.","D":"Microcitose, hipocromia e índice de anisocitose (RDW) normal.","E":"Normocitose, hipocromia e índice de anisocitose (RDW) alto."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-34176","number":"34176","sourceNumber":"34176","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual a etiologia da insuficiência cardíaca no adolescente?","options":{"A":"Doença de Kawasaki/Anomalia de Ebstein.","B":"Coarctação da aorta/síndrome de coração esquerdo.","C":"Febre reumática/Anemia Falciforme.","D":"Doença de Kawasaki/Persistência do canal arterial.","E":"Persistência do canal arterial/Comunicação interventicular."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-34177","number":"34177","sourceNumber":"34177","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Com 6-8 semanas de vida existe um declínio progressivo no nível de hemoglobina que\nresulta em uma anemia que chamamos de:","options":{"A":"Anemia megaloblástica.","B":"Anemia congênita.","C":"Anemia aplástica.","D":"Anemia fisiológica da infância.","E":"Anemia Fanconi."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-26449","number":"26449","sourceNumber":"26449","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Os mecanismos principais da anemia da insuficiência renal crônica são deficiências de:","options":{"A":"ferro e hemólise no sistema extracorpóreo.","B":"eritropoietina e de vitamina B12.","C":"ferro, perda sanguínea e intoxicação por alumínio.","D":"eritropoietina e diminuição da sobrevida dos eritrócitos.","E":"ferro e vitamina B12."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-26608","number":"26608","sourceNumber":"26608","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O que caracteriza anemia ferropriva?","options":{"A":"Nível sérico do ferro normal, transferrina elevada e RDW normal","B":"Nível sérico do ferro elevado, transferrida elevada e RDW baixo","C":"Nível sérico do ferro diminuído, transferrina elevada e RDW baixo","D":"Nível sérico do ferro diminuído, tranferrina baixa e RDW aumentado","E":"Nível sérico do ferro normal, tranferrina baixa e RDW aumentado"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-26467","number":"26467","sourceNumber":"26467","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual o principal objetivo da triagem neonatal para anemia falciforme?","options":{"A":"Garantir o acompanhamento sequencial dos índices hematimétricos;","B":"Reduzir a mortalidade por doenças infecciosas no primeiro ano de vida;","C":"Possibilitar a inclusão precoce no programa de doação de medula,","D":"Permitir o tratamento precoce com transfusões de trocas periódicas;","E":"Quantificar o número de portadores da doença na população em geral."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-26514","number":"26514","sourceNumber":"26514","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactante, 8 meses, com evolução de dois meses com quadro de anemia, recebeu\ntransfusão de concentrado de hemácias há 15\ndias. Apresenta edema em mão e pés, distensão\nabdominal, febre e ao raio-x de tórax: condensação em terço inferior de pulmão direito. Hemograma\ncom leucocitose, anemia, plaquetose e reticulócitos aumentado. Mãe com história de anemia, foi\nsubmetida a colocistectomia para tratamento de litíase biliar. Qual o diagnóstico mais provável e\nqual exame indicado para o diagnóstico de certeza?","options":{"A":"Esferocitose, curva de fragilidade osmótica;","B":"Anemia Falciforme, eletroforese de hemoglobina;","C":"Anemia de Fanconi. Mielograma;","D":"Leucemia linfoide aguda. Mielograma;","E":"Linfoma de Hodgkin, biópsia de medula;"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-7517","number":"7517","sourceNumber":"7517","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O diagnóstico de anemia ferropriva é indicado pelos seguintes parâmetros séricos: I-\nferro baixo. II- ferritina baixa. III- ferritina normal. IV- saturação de transferrina baixa. V-\nsaturação\nde transferrina alta. Estão corretos os parâmetros:","options":{"A":"I e III apenas.","B":"I e IV apenas.","C":"II e V apenas.","D":"I, II e IV apenas.","E":"I, II e III apenas."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-324668","number":"324668","sourceNumber":"324668","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher, 40 anos de idade, procura a UBS por apresentar olhos amarelados,\nesporadicamente. Nega comorbidades ou uso de\nmedicações. Ao exame físico, bom estado geral,\nsinais vitais estáveis, icterícia 1+ / 4. Não há alterações no exame segmentar, exceto espaço de\nTraube ocupado. Solicitados exames, com os seguintes resultados: Hb: 10,5g/dL, VCM: 100fL,\nCHCM: 35,1g/dL, RDW: 17%, leucócitos: 5930/mm³, plaquetas: 160mil/mm³, ferritina: 1000ng/mL,\níndice de saturação de transferrina: 54%, bilirrubinas totais: 3,8g/dL, direta: 0,9g/dL, indireta:\n2,89g/dL, AST: 26U/L (VR: 31), ALT: 29U/L (VR: 31U/L), Albumina: 4,0g/dL, RNI: 1,0.\n\nConsiderando o caso clínico descrito, indique o resultado mais provável no caso, entre os seguintes\nexames:","options":{"A":"Haptoglobina baixa.","B":"Reticulócitos baixos.","C":"Ácido metilmalônico elevado.","D":"Lactato desidrogenase baixa."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-324669","number":"324669","sourceNumber":"324669","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher, 40 anos de idade, procura a UBS por apresentar olhos amarelados,\nesporadicamente. Nega comorbidades ou uso de\nmedicações. Ao exame físico, bom estado geral,\nsinais vitais estáveis, icterícia 1+ / 4. Não há alterações no exame segmentar, exceto espaço de\nTraube ocupado. Solicitados exames, com os seguintes resultados: Hb: 10,5g/dL, VCM: 100fL,\nCHCM: 35,1g/dL, RDW: 17%, leucócitos: 5930/mm³, plaquetas: 160mil/mm³, ferritina: 1000ng/mL,\níndice de saturação de transferrina: 54%, bilirrubinas totais: 3,8g/dL, direta: 0,9g/dL, indireta:\n2,89g/dL, AST: 26U/L (VR: 31), ALT: 29U/L (VR: 31U/L), Albumina: 4,0g/dL, RNI: 1,0. Diante do\n\nquadro, indique o exame mais importante para realização do diagnóstico etiológico:","options":{"A":"Pesquisa de mutação para hemocromatose hereditária.","B":"Coombs direto.","C":"Biópsia hepática.","D":"Colangiopancreatografia por ressonância magnética (CPRM)."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-324670","number":"324670","sourceNumber":"324670","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher, 40 anos de idade, procura a UBS por apresentar olhos amarelados,\nesporadicamente. Nega comorbidades ou uso de\nmedicações. Ao exame físico, bom estado geral,\nsinais vitais estáveis, icterícia 1+ / 4. Não há alterações no exame segmentar, exceto espaço de\nTraube ocupado. Solicitados exames, com os seguintes resultados: Hb: 10,5g/dL, VCM: 100fL,\nCHCM: 35,1g/dL, RDW: 17%, leucócitos: 5930/mm³, plaquetas: 160mil/mm³, ferritina: 1000ng/mL,\níndice de saturação de transferrina: 54%, bilirrubinas totais: 3,8g/dL, direta: 0,9g/dL, indireta:\n2,89g/dL, AST: 26U/L (VR: 31), ALT: 29U/L (VR: 31U/L), Albumina: 4,0g/dL, RNI: 1,0. Identifique o\nmecanismo patológico relacionado à esplenomegalia apresentada pela paciente:","options":{"A":"Hipertensão portal.","B":"Depósito de ferro.","C":"Depósito de proteína amiloide.","D":"Aumento da função fagocítica."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-284613","number":"284613","sourceNumber":"284613","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Menina, 8 anos de idade, negra, encaminhada para avaliação no ambulatório de\nreferência com história de anemia crônica. A\nacompanhante (tia) relata que a menor queixa-se de\ncansaço fácil e dor em membros inferiores, frequentemente. Refere anorexia. Não sabe informar\nsobre quadro semelhante em familiares. Ao exame está em regular estado geral, ativa, hidratada,\neupneica, afebril, sem alterações em dados vitais; peso: 24 kg; com mucosas descoradas ++/IV.\nNão há adenomegalias. A ausculta cardíaca apresenta sopro holossistólico II/VI, audível em focos\nda base. Ausculta respiratória e restante do exame segmentar sem alterações. Exames realizados\nhá 45 dias: hematócrito: 24,6% e hemoglobina: 8,2 g/dl. Indique o parâmetro que aponta a\npresença de anisocitose no hemograma, nesse caso:","options":{"A":"RDW.","B":"VCM.","C":"HCM.","D":"Contagem de reticulócitos."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-284614","number":"284614","sourceNumber":"284614","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Menina, 8 anos de idade, negra, encaminhada para avaliação no ambulatório de\nreferência com história de anemia crônica. A\nacompanhante (tia) relata que a menor queixa-se de\ncansaço fácil e dor em membros inferiores, frequentemente. Refere anorexia. Não sabe informar\nsobre quadro semelhante em familiares. Ao exame está em regular estado geral, ativa, hidratada,\neupnéica, afebril, sem alterações em dados vitais; Peso: 24 Kg; com mucosas descoradas ++/IV.\nNão há adenomegalias. A ausculta cardíaca apresenta sopro holossistólico II/VI, audível em focos\nda base. Ausculta respiratória e restante do exame segmentar sem alterações. Exames realizados\nhá 45 dias: hematócrito: 24,6% e hemoglobina: 8,2g/dL. Indique o achado, no esfregaço de sangue\nperiférico, que permitiria fechar o diagnóstico etiológico (e patognomônico) desse tipo de anemia.","options":{"A":"Ovalócitos.","B":"Esferócitos.","C":"Drepanócitos.","D":"Hemáceas em alvo."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-284615","number":"284615","sourceNumber":"284615","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Menina, 8 anos de idade, negra, encaminhada para avaliação no ambulatório de\nreferência com história de anemia crônica. A\nacompanhante (tia) relata que a menor queixa-se de\ncansaço fácil e dor em membros inferiores, frequentemente. Refere anorexia. Não sabe informar\nsobre quadro semelhante em familiares. Ao exame está em regular estado geral, ativa, hidratada,\neupnéica, afebril, sem alterações em dados vitais; Peso: 24 Kg; com mucosas descoradas ++/IV.\nNão há adenomegalias. A ausculta cardíaca apresenta sopro holossistólico II/VI, audível em focos\nda base. Ausculta respiratória e restante do exame segmentar sem alterações. Exames realizados\nhá 45 dias: hematócrito: 24,6% e hemoglobina: 8,2g/dL. Indique o momento a partir do qual o\nexame específico pode ser realizado para o diagnóstico definitivo da causa da anemia em foco.","options":{"A":"Desde o nascimento.","B":"Após o período neonata.l","C":"Após o primeiro ano de vida.","D":"A partir de 3 meses de idade."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-62800","number":"62800","sourceNumber":"62800","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, sexo feminino, 25 anos de idade, admitida em unidade hospitalar com quadro\nde abdome agudo, é encaminhada para o centro\ncirúrgico com achado de isquemia mesentérica. A\npaciente não tinha queixas prévias a esse evento, mas relata avaliação laboratorial no mês anterior\ncom Hb: 7,5 g/dl; leucograma: 2.500; plaquetas: 46.000; creatinina: 0,6 mg/dl. Diante do quadro\ndescrito, o mais provável diagnóstico é:","options":{"A":"Púrpura trombocitopênica trombótica.","B":"Hemoglobinúria paroxística noturna.","C":"Anemia megaloblástica.","D":"Anemia de Fanconi.","E":"Síndrome de Shwachman."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-62803","number":"62803","sourceNumber":"62803","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, sexo feminino, 25 anos de idade, admitida em unidade hospitalar com quadro\nde abdome agudo, é encaminhada para o centro\ncirúrgico com achado de isquemia mesentérica. A\npaciente não tinha queixas prévias a esse evento, mas relata avaliação laboratorial no mês anterior\ncom Hb: 7,5 g/dl; leucograma: 2.500; plaquetas: 46.000; creatinina: 0,6 mg/dl. O exame que deve\nser solicitado para corroborar a principal suspeita diagnóstica é:","options":{"A":"Dosagem de vitamina B12.","B":"Biópsia de medula óssea.","C":"Lâmina do sangue periférico.","D":"Citometria de fluxo.","E":"Estudo genético."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-62857","number":"62857","sourceNumber":"62857","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, quatro anos de idade, apresenta dores intensas nas articulações de joelhos,\npunhos e tornozelos, há cerca de uma\nsemana, com febre e dificuldade para deambulação. Nos\nantecedentes, consta episódio semelhante aos dois anos de idade, ao exame, fácies de sofrimento,\nesclerótica, ictérica +++, palidez cutâneo-mucosa ++. Ausculta pulmonar com roncos. Abdome com\nfígado a 2 cm do RCD, baço palpável a 3 cm do RCE. Hemograma com 6,8 de HB, 20,3 de HTc,\ncom hipocromia, microcitose policromasia e poiquilocitose, reticulocitose importante de 15%. A\npatologia mais provável e o exame para o diagnóstico etiológico são, respectivamente:","options":{"A":"deficiência de GH e dosagem de GH.","B":"anemia falciforme e eletroforese de hemoglobina.","C":"leucemia e mielocultura.","D":"septicemia e hemocultura.","E":"sífilis congênita e VDLR quantitativo."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-49276","number":"49276","sourceNumber":"49276","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, quatro anos de idade, iniciou com febre alta há três dias, associada a vômitos\ne hiporexia, que evoluíram com astenia intensa\ne palidez cutânea. O exame físico mostrava REG,\nhipoativa, taquipneica, descorada (+++/+4), pesando 14,5 kg, FC: 152 bpm, FR: 40 ipm, presença\nde SS +++/+6, plurifocal, baço a 6 cm RCE, fígado não palpável. Realizou sorologia: rk39, hepatites\nA, B e C, e TORCHS, todos negativos. Ácido fólico: 7,8 (VN 3-50), vitamina B12: 432 (VN 174-878).\nMielograma: hiperplasia da série eritrocítica e granulocítica (afastada aplasia medular, leucemia,\ncalazar). Hb: 9,4, Ht: 27, leuc.: 8600 (S52/E1/L42/M5), plaq: 339000/mm³, numerosos esferócitos\nno sangue periférico. Eletroforese de Hb: (A1 96,3%/A2 2,7%/F4%), reticulócitos: 8,7%, ferritina:\n115,7, G6PD: (-), BT: 3,2 (Bl: 2,6), curva de fragilidade osmótica com fragilidade osmótica\naumentada. O diagnóstico mais provável para o caso é:","options":{"A":"anemia falciforme.","B":"anemia esferocítica.","C":"intoxicação medicamentosa.","D":"deficiência enzimática de G6PD.","E":"calazar."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-34994","number":"34994","sourceNumber":"34994","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Referente ao transporte de oxigênio no organismo humano, contribuem para o efeito\nBohr, EXCETO:","options":{"A":"Acidose metabólica.","B":"2,3-difosfoglicerato.","C":"Febre.","D":"Hemoglobina fetal.","E":"Altitude."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-34968","number":"34968","sourceNumber":"34968","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, 7 anos de idade, portador de anemia falciforme, em acompanhamento\nambulatorial, usando ácido fólico, com média de\nhemoglobina de 9,0 g. Apresenta palidez súbita,\nsudorese, queda do estado geral e febre moderada. O hemograma com Hb de 3,8 g e\nreticulopenia. A complicação mais provável dessa patologia é:","options":{"A":"Crise aplástica;","B":"Sequestro esplênico;","C":"Síndrome torácica aguda;","D":"Acidente vascular cerebral;","E":"Pneumonia subaguda."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-27461","number":"27461","sourceNumber":"27461","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, 9 anos de idade, apresenta quadro de tosse, febre e dor torácica, além de\ndores nos membros inferiores, anorexia e\nurina escura. Tem diagnóstico de doença falciforme. Ao\nexame, estado geral comprometido, fácies de sofrimento, esclerótica ictérica, palidez\ncutaneomucosa. Ausculta pulmonar com roncos e crépito nas bases. Ausculta cardíaca com SS em\nmesocárdio. Abdome com fígado a 10 cm do RCD, baço não palpável. Hemograma com Hb: 6,5,\nHtc: 28%, 29.800 leucócitos, segmentados de 72%, bastões 2%, linfócitos de 25%, monócitos 1%,\n\neosinófilos 0%. Plaquetas: 434.000 mm, bilirrubinas BI: 8,9, BT: 12,3. Reticulócitos de 6%.\nSaturando 92%, em ar ambiente. Nesse paciente, o evento clínico agudo a ser considerado é:","options":{"A":"síndrome torácica aguda.","B":"sequestro esplênico.","C":"crise aplástica.","D":"crise álgica.","E":"hepatite subaguda."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-27465","number":"27465","sourceNumber":"27465","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, 9 anos de idade, apresenta quadro de tosse, febre e dor torácica, além de\ndores nos membros inferiores, anorexia e\nurina escura. Tem diagnóstico de doença falciforme. Ao\nexame, estado geral comprometido, fácies de sofrimento, esclerótica ictérica, palidez\ncutaneomucosa. Ausculta pulmonar com roncos e crépito nas bases. Ausculta cardíaca com SS em\nmesocárdio. Abdome com fígado a 10 cm do RCD, baço não palpável. Hemograma com Hb: 6,5,\nHtc: 28%, 29.800 leucócitos, segmentados de 72%, bastões 2%, linfócitos de 25%, monócitos 1%,\n\neosinófilos 0%. Plaquetas: 434.000 mm, bilirrubinas BI: 8,9, BT: 12,3. Reticulócitos de 6%.\nSaturando 92%, em ar ambiente. O tratamento do\nevento descrito deve ser realizado em unidade\nhospitalar e considerar aspectos importantes, exceto:","options":{"A":"hidratação rigorosa com taxa hídrica de 150%.","B":"oxigenoterapia, se saturação de oxigênio \"menor que\" 90%.","C":"antibioticoterapia de amplo espectro.","D":"transfusão sanguínea com o objetivo de manter HbS \"menor que\" 30%.","E":"analgesia criteriosa."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-18025","number":"18025","sourceNumber":"18025","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, sexo masculino, 32 anos de idade, realizou exame pré-admissional que\nrevelou anemia com Hb de 10mg/dl e Ht de 33%\ncom volume corpuscular médio de 70Ftl e RDW\nnormal. As séries leucocitária e plaquetária estão normais. Encaminhado para avaliação clínica,\nevidenciaram-se ao exame físico, discreta hipocromia de mucosas; fígado a 3 cm do RCD e 5cm do\nAX e baço palpável a 4 cm do RCE. Os exames adicionais mostraram índice de saturação de\ntransferrina de 45% com ferritina de 450 mcg/ml. A eletroforese de hemoglobinas revelou 90% de\nhemoglobina A, com 5% de hemoglobina A2 e 5% de hemoglobina F. A causa provável de anemia\ndesse paciente é:","options":{"A":"Carencial, por falta de ferro.","B":"Hemolítica, por sequestração esplênica secundária à esquistossomose.","C":"Hemolítica, por alteração genética na síntese de hemoglobinas.","D":"Hemolítica, por alteração genética nas enzimas que dão resistência osmótica às hemácias.","E":"Carencial, por deficiência de vitamina B12 ou ácido fólico."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-18093","number":"18093","sourceNumber":"18093","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, 15 meses de vida, é atendido com história de dores intensas nas articulações\ndos joelhos e punhos, acompanhadas de febre. Ao\nexame, esclerótica-ictérica, palidez\ncutaneomucosa, ausculta cardíaca com SS em mesocárdio. Abdome com fígado a 2 cm do RCD,\nbaço a 6 cm do RCE. Hemograma com Hb: 7,2, poiquilocitose, hipocromia, anisocitose,\npolicromasia ++, 22.800 leucócitos, segmentados 68%, bastões 2%, linfócitos 26%, monócitos 2%,\neosinófilos 2%, plaquetas: 334.000 mm³, reticulócitos 6%. O diagnóstico mais provável para o caso\ndescrito é:","options":{"A":"Septicemia.","B":"Hepatite aguda.","C":"Leucemia aguda.","D":"Calazar.","E":"Anemia falciforme."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-15759","number":"15759","sourceNumber":"15759","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher, 32 anos de idade, da periferia de Salvador, com história de 5 gestações sendo\n1 aborto, cursando com tonturas e palpitações\ntipo taquicardia, aos esforços. Ao exame físico,\napresenta hipocromia de mucosas 4+, com palidez cutaneomucosa; T.A.: 120X70mmHg,\nP.R:21bpm. Ausência de estase de jugulares; sopro venoso jugular e sopro sistólico plurifocal.\n\nAusência de linfadenopatias. Aparelho respiratório: pulmões limpos. Abdome com fígado palpável\nelástico a 4cm do AX e sob RCD e baço palpável a 3cm do RCE, elástico. O diagnóstico mais\nprovável, nesse caso, é:","options":{"A":"hemoglobinopatia SS.","B":"anemia ferropriva.","C":"betatalassemia.","D":"hemoglobinopatia AS (traço falcêmico).","E":"anemia hemolítica autoimune."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-314291","number":"314291","sourceNumber":"314291","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre a anemia falciforme, analise as assertivas e identifique com V as verdadeiras e\ncom F as falsas. ( ) A anemia falciforme\nestá associada a um estado inflamatório crônico. ( ) O\nendotélio vascular lesado na crise vasoclusiva libera fatores pró-coagulantes e vasoconstrictores.\n( )\nOs pacientes com anemia falciforme apresentam níveis reduzidos de marcadores de ativação da\ntrombina, plaquetas e células endoteliais, mostrando que não há ativação da coagulação na\ndoença. A alternativa que contém a sequência correta, de cima para baixo, é","options":{"A":"F V F","B":"F F V","C":"V F V","D":"V F F","E":"V V F"},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-283845","number":"283845","sourceNumber":"283845","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 19 anos, com queixa de fadiga importante, ao exame físico, visto hipocromia\nacentuada de mucosas. Na investigação laboratorial, foi diagnosticada anemia com 5% de\nreticulócitos. A alternativa que contém a causa para essa anemia é","options":{"A":"Doença inflamatória crônica.","B":"Deficiência de vitamina B12.","C":"Policitemia vera.","D":"Ferropriva.","E":"Hemólise."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-249987","number":"249987","sourceNumber":"249987","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a alternativa incorreta sobre a alfa talassemia:","options":{"A":"Os indivíduos com deleção de 2 alfa-globinas são descritos como portadores de traço\nalfa-talassêmico.","B":"A anemia ferropriva, a saturação de ferro e a ferritina normais são diagnósticos diferenciais.","C":"A alfa-talassemia major é extremamente rara.","D":"A alfa-talassemia ocorre pelo aumento da cadeia de alfa da globina, havendo sobra de cadeia\nbeta."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-249988","number":"249988","sourceNumber":"249988","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A avaliação do paciente com anemia deve conter obrigatoriamente uma história familiar\ne pessoal detalhada, além de exame físico\ncompleto e exames laboratoriais inicias. Dentro dos\nexames laboratoriais que devem ser solicitados em um primeiro momento estão todos os abaixo,\nexceto:","options":{"A":"Hemograma completo.","B":"Contagem de reticulócitos.","C":"DHL.","D":"Hematoscopia."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-249989","number":"249989","sourceNumber":"249989","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Com relação à anemia, assinale a alternativa a alternativa correta:","options":{"A":"A anemia é um diagnóstico que atinge até 25% da população.","B":"Os quadros crônicos de anemia sempre apresentam palidez, taquicardia e letargia.","C":"A produção diária de reticulócitos é maior do que a destruição m condições fisiológicas.","D":"A capacidade de fixação do ferro (TIBC) auxilia no cálculo de saturação de ferro para avaliar a\npresença de deficiência de ferro."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-249991","number":"249991","sourceNumber":"249991","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a alternativa correta sobre o traço falcêmico.","options":{"A":"Apresenta hemograma normal.","B":"Apresenta anemia leve a moderada.","C":"Apresenta esplenomegalia discreta.","D":"Apresenta dores ósseas."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-350875","number":"350875","sourceNumber":"350875","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem, 58 anos, apresenta adinamia progressiva há 6 meses, associada a perda\nponderal de 8kg no mesmo período (peso\nhabitual 78kg e atual 70kg) e constipação de início\nrecente. Buscou assistência médica, sendo observado ao exame físico palidez cutâneo-mucosa\n2+/4+, hemodinamicamente estável, sendo solicitados os seguintes exames: Hemoglobina 9,2g/dL\n(V.R.?13g/dL), VCM 68fL (V.R 80 A 98fL), CHCM 25g/dL (V.R. 32 a 36d/dL), RDW 21% (V.R. 11 a\n\n15%), Leucócitos 9800 com diferencial normal Plaquetas 522mil. Qual a melhor abordagem\ndiagnóstica a seguir?","options":{"A":"Referenciar paciente para hematologista.","B":"Solicitar dosagem de vitamina B12 e ácido fólico e endoscopia digestiva alta.","C":"Solicitar reticulócitos, índice de saturação de transferrina, ferritina e colonoscopia.","D":"Solicitar eletroforese de proteínas séricas, mielograma, imunofenotipagem e biopsia óssea."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-321299","number":"321299","sourceNumber":"321299","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, 72 anos, sexo masculino, diagnosticado com hipertensão arterial sistêmica e\ndiabetes mellitus tipo 2, desde os 56 anos, sob uso de losartana e metformina desde então, com\nbom controle pressórico e dos níveis glicêmicos. Apresenta ainda doença renal crônica estágio 2,\nem conduta expectante. Em consulta de rotina, referiu que há 4 meses apresenta \"formigamento\"\nem mãos, bilateralmente, indolor, sem outras queixas. Ao exame, apresenta discreta palidez\ncutâneo-mucosa, redução da sensibilidade vibratória e proprioceptiva distal em membros\nsuperiores, função motora preservada, sem alterações em membros inferiores. Foram solicitados\nexames complementares laboratoriais que evidenciaram: Hb 10,1g/dl; Ht 30%; VCM 122 fL CHCM\n32g/dL; Leucócitos 2900/mm³; Neutrófilos 1520/mm³; Linfócitos 880/mm³; Plaquetas 88000/mm³;\nUreia 66mg/dL; Cr 1,2mg/dL; Proteínas totais 6,9g/dL; Albumina 4,6g/dL; Globulina 2,3g/dL; Cálcio\nsérico 8,6 mg/dL HbA1c 5,6%. Qual a melhor investigação a ser realizada e o diagnóstico mais\nprovável?","options":{"A":"Aspirado de medula óssea, visto tratar-se provavelmente de leucemia aguda.","B":"Eletroneuromiografia de quatro membros, visto tratar-se de quadro típico de neuropatia\ndiabética.","C":"Eletroforese e imunofixação de proteínas séricas, visto quadro clínico-laboratorial sugestivo de\nmieloma múltiplo.","D":"Dosagem de reticulócitos, vitamina B12, bilirrubina indireta e desidrogenase láctica, visto\nhipótese diagnóstica de deficiência de vitamina B12."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-292814","number":"292814","sourceNumber":"292814","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente, 26 anos, procura unidade básica de saúde com queixa de adinamia leve,\ngengivorragia durante escovação e parestesias em mãos e pés. Refere que os sintomas iniciaram\nhá cerca de 6 semanas. Refere que há 2 anos faz reposição de levotiroxina, pois \"tireoide deixou\nde funcionar\"(sic). Ao exame físico, apresentava palidez cutâneo-mucosa 2+/4+, língua\ndespapilada, ausência de adenomegalias ou visceromegalias. Foi solicitado hemograma que\nevidenciou hemoglobina 7,8 g/dL, hematócrito 22%, VCM 118, leucócitos 4.800 (neutrófilos 1.580),\nplaquetas 42.000/mm3, reticulócitos 38.000. Considerando a principal hipótese diagnóstica, que\noutros exames laboratoriais devem ser solicitados a fim de confirmar o diagnóstico e qual alteração\nesperada nesses exames?","options":{"A":"Desidrogenase láctica elevada, homocisteína diminuída e bilirrubina indireta elevada.","B":"Teste de antiglobulina direta positivo, bilirrubina direta elevada e homocisteína diminuída.","C":"Ácido metilmalônico elevado, bilirrubina indireta elevada e desidrogenase láctica elevada.","D":"Índice de saturação de transferrina diminuído, ferritina diminuída e desidrogenase láctica\nnormal."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-259715","number":"259715","sourceNumber":"259715","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 22 anos, sem comorbidades, vem em consulta ambulatorial com queixa de\nfadiga há 3 meses. Apresenta exame físico inalterado, exceto pela presença de palidez\n\ncutâneo-mucosa. Traz o seguinte hemograma: hemoglobina 9,0 g/dl (Valor de referência (VR):12 a\n\n16); hematócrito 23% (VR: 36 a 48); VCM 80 fl (VR: 76 a 100); HCM 24 (VR: 27 a 33); CHCM 28\n\n(VR: 32 a 36); leucócitos 6.800/mm3; plaquetas 250.000/mm3 (VR: 140.000 a 450.000). Contagem\nde reticulócitos 100.000/mm3. Ausência de\nalterações morfológicas no esfregaço do sangue\nperiférico. A investigação laboratorial subsequente mais indicada para essa paciente é:","options":{"A":"Cinética de ferro e mielograma.","B":"Mielograma, função renal e função tireoidiana.","C":"Cinética de ferro, função renal e função tireoidiana.","D":"Cinética de ferro, dosagem de vitamina B12 e dosagem de ácido fólico."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-234043","number":"234043","sourceNumber":"234043","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente masculino, 25 anos, vegetariano, apresenta-se para exame admissional com\nexames realizados. Traz o seguinte hemograma:\nhemácias = 5,3 milhões/mm³ (VR = 4,5?6\nmilhões/mm³); Hb = 11,1 g/dl (VR = 13,5?17,5); Ht = 33% (VR = 40?52); VCM = 72 fl (VR = 81?99);\nHCM = 25 pg (VR = 30?34); RDW = 13% (VR = 12?14); leucócitos = 6.500/mm³ (VR =\n\n4.000?10.000); plaquetas = 452.000/mm³ (VR = 150.000?450.000) ? presença de hemácias em\nalvo. Demais exames sem anormalidades. Nega\netilismo. Relata estar assintomático e nega\ndoenças prévias, mas relata que sempre teve alguma alteração em hemogramas anteriores, sendo\nque nunca lhe foi orientado nenhum tratamento específico. LEGENDA: VR = Valor de Referência;\nVCM = Volume Corpuscular Médio; HCM = Hemoglobina Corpuscular Média; RDW = índice de\nanisocitose. Em relação ao diagnóstico provável para a anemia encontrada, qual exame seria mais\nespecífico para confirmação?","options":{"A":"Perfil bioquímico do ferro.","B":"Dosagem de vitamina B12.","C":"Eletroforese de hemoglobina.","D":"Mielograma usando corante azul da Prússia."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-234047","number":"234047","sourceNumber":"234047","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Alice, 9 meses de idade, é atendida no ambulatório de puericultura com história de\npalidez cutâneo-mucosa progressiva e irritabilidade há 3 meses. Refere aleitamento materno\nexclusivo até os 2 meses de idade e depois iniciado leite de cabra. Apresenta dieta pobre em\ncarnes e verduras. O pediatra diagnosticou anemia por deficiência de folatos. Quais alterações\ndescritas abaixo no hemograma são mais compatíveis com essa anemia?","options":{"A":"Anisocitose, macrocitose, trombocitopenia, leucopenia.","B":"Anisocromia, neutrófilos hipersegmentados, leucocitose.","C":"Poiquilocitose, hipercromia, reticulocitose, pancitopenia.","D":"Anisopoiquilocitose, microcitose, trombocitose, neutropenia."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-199841","number":"199841","sourceNumber":"199841","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente masculino de 26 anos comparece ao pronto-socorro referindo anemia desde a\ninfância e que há um dia iniciou com quadro de dor em membros inferiores, no momento, de forte\nintensidade. Nega febre, dispneia ou outras queixas. Encontra-se descorado, ictérico, eupneico e\ncom fácies de dor. Hemograma evidenciou hemoglobina = 6,2 g/dl, leucócitos = 13.400/mm³, com\nneutrofilia e plaquetas = 762.000/mm³. A lâmina de sangue periférico encontra-se em anexo. Além\nda busca por foco infeccioso e analgesia, qual melhor abordagem imediata para controle do\nquadro?","options":{"A":"Hidratação vigorosa.","B":"Antibiótico empírico.","C":"Transfusão simples de concentrado de hemácias.","D":"Transfusão de troca de concentrado de hemácias."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":["question_bank/media/medcurso/medcurso-hemato-hem-1/199841.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-150876","number":"150876","sourceNumber":"150876","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente feminino, 20 anos, procura ambulatório queixando-se de fraqueza, mal-estar e\ndores ocasionais nas pernas há aproximadamente um mês. Ao exame físico, apresenta língua\ncareca, palidez cutâneo-mucosa, frequência cardíaca de 88 batimentos por minuto, sem outras\nalterações. Ao hemograma, apresenta Hb = 7,0 g/dl; VCM = 62 fl; RDW = 18%; leucócitos = 3.700;\nneutrófilos = 2.200; plaquetas = 615.000/mm³. Qual a conduta apropriada, além da revisão do\nesfregaço do sangue periférico e da contagem de reticulócitos?","options":{"A":"Solicitar eletroforese de hemoglobina, iniciar ácido fólico e avaliar indicação de início de\ntransfusão crônica.","B":"Solicitar Coombs direto, desidrogenase láctica, bilirrubina total e frações, e iniciar\ncorticoide e\nácido fólico.","C":"Solicitar proteína C-reativa, VHS, investigar doença de base e transfundir uma unidade de\nconcentrado de hemácias.","D":"Solicitar ferro, ferritina e capacidade total de fixação do ferro, iniciar ferro oral e avaliar\nfonte de\nsangramento."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-150827","number":"150827","sourceNumber":"150827","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente masculino, 50 anos, encontra-se internado para investigação de síndrome\nconsumptiva. Relata desconforto abdominal e constipação, sem outras queixas. Ao exame físico,\nencontra-se descorado 2+/4+; FC = 82 bpm; PA = 132 x 86 mmHg, sem outras alterações.\n\nApresenta hemograma com Hb = 7,1 g/dl; VCM = 92 fl; RDW = 16%; leucócitos = 5.300/mm³,\ndiferencial normal e plaquetas de 322.000/mm³. Qual a conduta apropriada?","options":{"A":"Não transfundir e iniciar reposição de ferro e ácido fólico.","B":"Não transfundir e iniciar investigação com contagem de reticulócitos.","C":"Transfundir concentrado de hemácias e solicitar hemograma para avaliar incremento.","D":"Transfundir concentrado de hemácias e solicitar endoscopia digestiva para investigação."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-150855","number":"150855","sourceNumber":"150855","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A mãe de um menino de cinco anos de idade relata que ele está com aparência\nanêmica, nas últimas duas semanas, sem causa\naparente. Ao exame clínico, apresenta apenas\npalidez cutâneo-mucosa e leve icterícia; o restante do exame é normal. Os resultados laboratoriais\nrevelam hemoglobina de 6,5 g% e Coombs direto positivo. Qual a principal hipótese diagnóstica?","options":{"A":"Doença falciforme.","B":"Esferocitose hereditária.","C":"Anemia hemolítica autoimune.","D":"Anemia por deficiência de glicose-6-fosfato desidrogenase."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-102125","number":"102125","sourceNumber":"102125","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente do sexo feminino, 40 anos, testemunha de Jeová, procura ambulatório com\ndores constantes no baixo ventre em decorrência\nde um útero miomatoso. Ao exame físico,\nobserva-se massa palpável e os exames complementares estão normais, exceto por uma discreta\nanemia, hemoglobina de 10,5 g/dl e hematócrito de 38%. Considerando a questão legal frente a\nesta paciente, qual a melhor opção a ser tomada diante da possibilidade de transfusão sanguínea?","options":{"A":"Transfusão de sangue total autólogo fresco.","B":"Uso de hemácias autólogas armazenadas.","C":"Contraindicar a operação.","D":"Operar sem transfusão."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-102150","number":"102150","sourceNumber":"102150","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem de 28 anos comparece para avaliar anemia. Ele tem queixas de episódios de\ndor abdominal e astenia, há dois anos. Conta também que em alguns momentos acha que sua\nurina está mais escura. O exame físico é inexpressivo, exceto por palidez (++/4+). Avaliação\nlaboratorial mostra hemoglobina 9,2 g/dl, com normocitose e normocromia, leucócitos 3.500/mm³,\nplaquetas 105.000/mm³, haptoglobina indetectável, desidrogenase lática 1.620 U/L, bilirrubina\nindireta 1,8 mg/dl e índice de saturação da transferrina 6%. Qual o diagnóstico mais provável?","options":{"A":"Favismo.","B":"Esferocitose.","C":"Anemia hemolítica autoimune.","D":"Hemoglobinúria paroxística noturna."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-65723","number":"65723","sourceNumber":"65723","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 60 anos foi internada com síndrome coronariana aguda. No 5º dia de\ninternação, foi diagnosticada com infecção do\ntrato urinário, sendo medicada com ceftriaxona, 2 g\npor dia, por via venosa. No 11º dia, apresentou piora hemodinâmica, precordialgia, sudorese,\npalidez cutâneo-mucosa e taquicardia. Não apresentava hepatoesplenomegalia. Resultados de\nexames laboratoriais no momento mostravam: hemácias: 1.450.000/mm³; hematócrito: 17,5%;\nhemoglobina: 6,5 g/dl; VCM: 120 fl; HCM = 36,8 pg; CHbCM = 30 g/dl; RDW = 26 %. Reticulócitos:\n18,5 %; esfregaço periférico com presença de anisocitose ++/4+; macrocitose +++/4+; microcitose\n\n+/4+; presença de esferócitos e policromasia. Leucócitos: 8.500/mm³ com diferencial dentro da\nnormalidade e plaquetas: 325.000/mm³; LDH = 1.200 UI/L. O exame colhido na admissão mostrou\nHb de 13,0 g/dl. Qual a conduta terapêutica mais adequada?","options":{"A":"Transfusão sanguínea e corticoterapia IV.","B":"Transfusão sanguínea e ciclofosfamida IV.","C":"Transfusão sanguínea.","D":"Corticoterapia IV.","E":"Rituximabe IV."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-65762","number":"65762","sourceNumber":"65762","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 65 anos, feminina, branca, apresenta parestesias em membros inferiores,\ncom dificuldade para caminhar, associadas a quadro\ndemencial de início recente. Nega outras\nqueixas. Os reflexos patelar e aquileu estão reduzidos bilateralmente. Qual dos achados de\nexames laboratoriais seria suficiente para confirmar o diagnóstico mais provável para o quadro\ndessa paciente?","options":{"A":"Folato baixo.","B":"Tiamina baixa.","C":"Homocisteína elevada.","D":"Ácido metilmalônico elevado.","E":"Hormônio tireoestimulante baixo."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-65746","number":"65746","sourceNumber":"65746","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma criança de dois anos de idade, com dieta predominantemente láctea, é atendida\nno centro de saúde. O médico decide utilizar\ncompostos à base de ferro. Que orientações o médico\ndeve fornecer à família?","options":{"A":"Os estoques são recompostos nos primeiros 15 dias do tratamento.","B":"O ferro é mais bem absorvido quando administrado após a refeição de sal.","C":"Podem-se oferecer chás, leite, cereais e fibras, pois não interferem na absorção de ferro.","D":"Devem-se oferecer frutas cítricas e carboidratos, pois facilitam a absorção do ferro não heme.","E":"Em casos de crianças que aceitam mal a medicação, a alternativa é a transfusão de glóbulos\nvermelhos."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-51211","number":"51211","sourceNumber":"51211","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual é a afirmação correta sobre as anemias microcíticas e hipocrômicas?","options":{"A":"A dosagem da ferritina sérica isoladamente é um parâmetro pouco útil para a avaliação do\nestoque de ferro.","B":"A anemia da doença renal crônica, desde o estágio inicial, caracteriza-se por ferro sérico baixo\ne\nTIBC elevada.","C":"A hiperplasia eritroide e o esfregaço com mais de 50% de rouleaux são observados quando os\nníveis de hemoglobina estão entre 7-8 g/dl.","D":"O diagnóstico diferencial de microcitose inclui deficiência de ferro, betatalassemia, intoxicação\npor chumbo e hemoglobinopatia Lepore."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-51228","number":"51228","sourceNumber":"51228","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem de 58 anos apresenta dormência inicialmente nas mãos e, posteriormente, já\nhá 2 anos, em ambos os pés e pernas\ndistais. A marcha é instável. Fez gastrectomia total há 10\nanos por neoplasia. Apresenta manchas hipocrômicas, descamativas, no pescoço e tórax. Há\nglossite e queilose. Reflexo aquileu ausente bilateralmente. Glicemia de jejum 101 mg/dl,\nhematócrito 28 g/dl, volume corpuscular médio 120 fl, VHS 22 mm. ECG normal. Qual é a causa do\nquadro clínico do paciente?","options":{"A":"Deficiência de vitamina B12.","B":"Intoxicação por arsênico.","C":"Dermatomiosite.","D":"Hanseníase."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-141623","number":"141623","sourceNumber":"141623","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia ferropriva é uma das mais frequentes anemias carenciais. Na avaliação de\numa criança com anemia ferropriva, é\ncaracteristicamente encontrado um aumento de:","options":{"A":"Ferritina sérica.","B":"Volume corpuscular médio.","C":"Hemoglobina globular média.","D":"Capacidade de ligação com o ferro."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-141624","number":"141624","sourceNumber":"141624","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 65 anos de idade, T.U.E., acompanhada por sua médica de família, com a\nseguinte lista de problemas crônicos. (VER IMAGEM) Chega com resultado de hemograma\nsolicitado na consulta anterior: hemácias: 5.100.000/mm³; hemoglobina: 10,3 g/dl; hematócrito:\n34,7%; VCM: 85 fl; HCM: 27 pg; CHCM: 33 g/dl; RDW: 11.2%; HDW: 2.6 g/dl. Diante dos dados\ninformados, qual é a principal hipótese diagnóstica a se considerar?","options":{"A":"Anemia normocítica por insuficiência renal crônica.","B":"Anemia microcítica por deficiência de ferro.","C":"Anemia hemolítica intrínseca.","D":"Anemia megaloblástica."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":["question_bank/media/medcurso/medcurso-hemato-hem-1/141624.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-45379","number":"45379","sourceNumber":"45379","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação às anemias na infância, é correto afirmar:","options":{"A":"O diagnóstico laboratorial da anemia ferropriva inclui ferro sérico e ferritina sérica baixos,\ncapacidade total de ligação do ferro baixa e saturação de transferrina alta.","B":"A deficiência de B12 e as talassemias são exemplos clássicos de anemias macrocíticas.","C":"Nas crianças com anemias hemolíticas esferocíticas estão contraindicados o uso de sulfas e\nquinolonas.","D":"Baixo peso ao nascimento, desmame precoce e baixa disponibilidade de ferro na dieta\npredispõem as anemias ferroprivas.","E":"Lactentes com deficiência de ferro quando apresentam alterações de desenvolvimento e\ncomportamento, geralmente são reversíveis após o tratamento."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-36987","number":"36987","sourceNumber":"36987","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem de 70 anos comparece para que seja avaliada a anemia. Seus exames revelam\nHb: 8,5 g/dl, VCM: 112 fL, LDH: 2.650 U/L.\nNo esfregaço do sangue periférico, há macro-ovalócitos\ne neutrófilos hipersegmentados. Há história de cirurgia de ?retirada do estômago? por úlcera há\noito anos. Ele não faz uso de medicações habitualmente. Qual o diagnóstico mais provável?","options":{"A":"Anemia Hemolítica autoimune.","B":"Deficiência de ácido fólico.","C":"Síndrome mielodisplásica.","D":"Deficiência de vitamina B12."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-32538","number":"32538","sourceNumber":"32538","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Menino de 7 anos, com anemia ferropriva, em uso de sulfato ferroso (4 mg/kg/dia de\nferro elementar) há 5 dias. O médico do PSF\ndeseja assegurar-se de que a prescrição está sendo\ncumprida e de que está havendo uma resposta terapêutica satisfatória. Dentre os exames abaixo,\nqual o mais indicado para essa avaliação, com menos de uma semana de tratamento?","options":{"A":"Dosagem de ferro sérico.","B":"Contagem de reticulócitos.","C":"Dosagem de hemoglobina.","D":"Eletroforese de hemoglobina.","E":"Dosagem de ferritina sérica."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-22824","number":"22824","sourceNumber":"22824","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"São condições associadas a hemólise, EXCETO:","options":{"A":"púrpura trombocitopênica trombótica","B":"deficiência de glicose-6-fosfato desidrogenase","C":"válvula mitral metálica","D":"aplasia pura de células vermelhas","E":"infecção por Clostridium"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-24311","number":"24311","sourceNumber":"24311","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem de 64 anos submetido à gastrectomia total por adenocarcinoma gástrico há 08\nmeses evolui com cansaço aos médios esforços,\npalidez cutâneomucosa e parestesias em MMII.\nTraz um hemograma que revela HT: 27% Hb: 8,2g/dl e VCM: 108 fl. Como devo proceder?","options":{"A":"Penso em anemia ferropriva por recidiva da lesão e solicito exames da cinética do ferro e\nendoscopia digestiva.","B":"Penso em anemia secundária à manifestação paraneoplásica e solicito TC de abdome.","C":"Penso em anemia microcítica por deficiência de folato e solicito dosagem sérica do ácido fólico.","D":"Penso em anemia macrocítica por deficiência de vitamina B12 e solicito sua dosagem sérica."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-24391","number":"24391","sourceNumber":"24391","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Ademir, 5 anos, apresentou quadro de dor no quadril de evolução insidiosa. A princípio,\no traumato-ortopedista imaginou que poderia se tratar\nda doença de Legg-Calvé-Perthes (necrose\nasséptica idiopática da cabeça femoral), porém ao saber que a criança era portadora de uma\ndoença hematológica hereditária, logo percebeu que se tratava de uma osteonecrose da cabeça do\nfêmur, importante complicação da:","options":{"A":"Anemia falciforme","B":"Beta-Talassemia ?Minor?","C":"Esferocitose","D":"Deficiência da G6PD"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-7296","number":"7296","sourceNumber":"7296","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"As anemias são classificadas pela sua causa e pelo tamanho da célula vermelha.\nSobre esse assunto, responda o correto.","options":{"A":"A anemia por deficiência de ferro é a mais comum, geralmente é microcítica e sua principal\ncausa é a doença crônica.","B":"São características das talassemias - espectro de anemias adquiridas - o seguinte: hipocromia,\nnormocitose e células em alvo.","C":"A síndrome mielodisplásica, caracterizada por hiperplasia eritroide decorrente da eritopoiese\nineficaz, é macrocítica e há aumento nos\ndepósitos de ferro na medula.","D":"A anemia megaloblástica por deficiência de vitamina B12 raramente é grave, precede os\nsintomas neurológicos e não causa hiperbilirrubinemia.","E":"A anemia falciforme é uma doença autossômica dominante e está relacionada à produção de\numa hemoglobina defeituosa fruto da troca de\ntirosina por valina na cadeia dessa proteína."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-13403","number":"13403","sourceNumber":"13403","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 35 anos encontra--se convalescente de uma pneumonia por mycoplasma.\nDesenvolveu uma astenia importante. Sua hemoglobina é de 9,0 g/dL e seu VCM é 110. Qual dos\nseguintes é o melhor teste para determinar se o paciente tem uma anemia hemolítica?","options":{"A":"Bilirrubina sérica.","B":"Contagem de reticulócitos e esfregaço periférico.","C":"Antígeno de mycoplasma.","D":"LDH sérico.","E":"Contagem de plaquetas."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-13439","number":"13439","sourceNumber":"13439","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 50 anos com história de Ca de mama desenvolve metástases múltiplas. Com\na progressão da doença ela desenvolveu anemia\ncom leucopenia e plaquetopenia. A possibilidade\nde anemia mielotísica é considerada. Qual dos seguintes achados no sangue periférico deve\nfortemente suportar este diagnóstico?","options":{"A":"Hemácias macrocíticas e hipocrômicas.","B":"Hemácias nucleadas.","C":"Sideroblastos em anel.","D":"Esquizócitos.","E":"Células falciformes."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-13489","number":"13489","sourceNumber":"13489","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sabendo que uma gota da solução de sulfato ferroso apresenta 1,25 mg de ferro\nelementar, quantas gotas por dia estaria mais correto recomendar para o tratamento de uma\ncriança de 10 kg com anemia ferropriva?","options":{"A":"10.","B":"20.","C":"40.","D":"60.","E":"80."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-17814","number":"17814","sourceNumber":"17814","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente com queixa de dor na língua, dor à deglutição e fadiga crônica, apresenta-se\ncom palidez cutaneomucosa, atrofia de papilas\nlinguais, estomatite angular, unhas frágeis e\nbrilhosas. O eritrograma apresenta anemia microcítica e hipocrômica. A hipótese mais provável\npara este quadro é:","options":{"A":"deficiência de ferro","B":"deficiência de vitamina C","C":"deficiência de vitamina B12","D":"talassemia","E":"anemia sideroblástica"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-17847","number":"17847","sourceNumber":"17847","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um menino de dois anos de idade apresenta-se com palidez cutaneomucosa\nacentuada e seu hemograma evidenciou anemia\n(hemoglobina de 9 g%), com microcitose (Volume\nCorpuscular Médio de 50 mcg3), reticulopenia (menos de 0,5%) e anisocitose (RDW maior que\n15%). O diagnóstico mais provável nesse caso é:","options":{"A":"anemia aplástica","B":"deficiência de folatos","C":"deficiência de vitamina B12","D":"hemólise","E":"anemia ferropriva"},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-15922","number":"15922","sourceNumber":"15922","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Anemia aplástica é decorrente de:","options":{"A":"deficiência das células tronco pluripotentes.","B":"lesão medular progressiva por neoplasia.","C":"anormalidade citogenética na série eritrocítica.","D":"mutação no gene PIG-A.","E":"mutação no gene cmpl."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-349756","number":"349756","sourceNumber":"349756","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à Doença Falciforme, assinale a alternativa INCORRETA.","options":{"A":"Não é indicado aconselhamento genético futuro, para evitar preocupações para a família.","B":"As crises álgicas se iniciam antes de 12 meses em muitos casos.","C":"A hidratação venosa está indicada no início do tratamento em caso de crises álgicas.","D":"O alívio da dor não é alcançado com paracetamol nos casos com recidivas.","E":"As complicações da perfusão são pouco importantes durante as crises álgicas."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-365640","number":"365640","sourceNumber":"365640","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma criança de 1 ano de idade foi levada para consulta de rotina. Na história clínica, a\nmãe referiu desmame completo aos 3 meses de vida, passando a ofertar leite de vaca integral.\n\nNegou uso de ferro oral até o momento. Foram solicitados exames complementares para avaliar\npossível deficiência de ferro. Qual é a alteração laboratorial inicial nos casos de deficiência de\nferro?","options":{"A":"Redução do ferro sérico","B":"Redução da ferritina","C":"Microcitose","D":"Anisocitose"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-322216","number":"322216","sourceNumber":"322216","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"José, 55 anos, retorna à UBS para mostrar exames solicitados pelo seu médico da\nfamília após queixar-se de cansaço há alguns\nmeses. Dentre os resultados, tem-se: ferro sérico 45\nmcg/dl (VR 60-150 mcg/dl), ferritina 170 ng/ml (VR 10-150 ng/ml) TBIC 200 mcg/dl (VR 250-360\nmcg/dl) e saturação de transferrina 28% (VR 30-40%). Dessa forma, o diagnóstico mais provável é","options":{"A":"talassemia.","B":"hemocromatose.","C":"anemia ferropriva.","D":"anemia de doença crônica.","E":"anemia megaloblástica."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-284277","number":"284277","sourceNumber":"284277","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma paciente de 32 anos de idade procurou a unidade básica de saúde com queixa de\nastenia há dois meses. É tabagista de um maço por dia há dez anos. Refere ciclos menstruais\nregulares, com sangramento volumoso por doze dias a cada ciclo. Exame físico: pressão arterial de\n120 x 80 mmHg; frequência cardíaca de 110; e saturação de oxigênio de 97%. Hipocorada ++/4+,\nanictérica, acianótica e eupneica. Exame cardiopulmonar: ritmo cardíaco regular, com sopro\nsistólico ++/6+, pancardíaco, sem irradiação. Murmúrios vesiculares audíveis bilateralmente, sem\nruídos adventícios. Restante do exame físico normal. Com base nessa situaçaõ hipotética, julgue o\nitem a seguir. A contagem de reticulócitos deve estar aumentada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-284278","number":"284278","sourceNumber":"284278","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma paciente de 32 anos de idade procurou a unidade básica de saúde com queixa de\nastenia há dois meses. É tabagista de um maço por dia há dez anos. Refere ciclos menstruais\nregulares, com sangramento volumoso por doze dias a cada ciclo. Exame físico: pressão arterial de\n120 x 80 mmHg; frequência cardíaca de 110; e saturação de oxigênio de 97%. Hipocorada ++/4+,\nanictérica, acianótica e eupneica. Exame cardiopulmonar: ritmo cardíaco regular, com sopro\nsistólico ++/6+, pancardíaco, sem irradiação. Murmúrios vesiculares audíveis bilateralmente, sem\nruídos adventícios. Restante do exame físico normal. Com base nessa situaçaõ hipotética, julgue o\nitem a seguir. O sopro cardíaco identificado trata-se, provavelmente, de sopro funcional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-284279","number":"284279","sourceNumber":"284279","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma paciente de 32 anos de idade procurou a unidade básica de saúde com queixa de\nastenia há dois meses. É tabagista de um maço por dia há dez anos. Refere ciclos menstruais\nregulares, com sangramento volumoso por doze dias a cada ciclo. Exame físico: pressão arterial de\n120 x 80 mmHg; frequência cardíaca de 110; e saturação de oxigênio de 97%. Hipocorada ++/4+,\nanictérica, acianótica e eupneica. Exame cardiopulmonar: ritmo cardíaco regular, com sopro\nsistólico ++/6+, pancardíaco, sem irradiação. Murmúrios vesiculares audíveis bilateralmente, sem\nruídos adventícios. Restante do exame físico normal. Com base nessa situaçaõ hipotética, julgue o\nitem a seguir. Espera-se encontrar corpúsculos de Howell-Jolly no esfregaço de sangue periférico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-284297","number":"284297","sourceNumber":"284297","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um lactente com dez meses de vida, nascido de parto normal a termo, com peso\nadequado e sem intercorrência, foi levado\npor sua mãe à unidade de atenção básica para uma\nconsulta de puericultura, apresentando unhas quebradiças, irritabilidade, queilite angular e\nastenia.\nAo exame físico, o pediatra observou palidez da face, das palmas das mãos e da mucosa oral e\nconjuntival e solicitou um hemograma, que demonstrou hemoglobina igual a 10,5 g/dl e hematócrito\n31%, o que o fez suspeitar de anemia ferropriva. A mãe informou que ele é amamentado ao seio\nmaterno, mas recebe complementação com leite de vaca em pó desde o 6.º mês, aceita pouca\nalimentação de sal e nunca fez suplementação com ferro oral. Com base nessa situação hipotética,\njulgue o item a seguir. A dosagem de ferritina é uma ferramenta diagnóstica que pode ser utilizada\ndesde o primeiro estágio da anemia, ainda na depleção de ferro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-177596","number":"177596","sourceNumber":"177596","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"J.S.A., de 55 anos de idade, negra, viúva, com três filhos, hígida, com alimentação\nsaudável, assídua praticante de exercício\nfísico, vai à consulta para a realização de exames de\nrotina. Refere menopausa há 15 anos. Ao exame físico completo, não se encontra nenhuma\nalteração, exceto palidez de mucosas. Apresenta hemograma realizado em pronto atendimento por\nqueixas gripais, há 2 semanas, com anemia microcítica e índice de anisocitose aumentado. Com\nrelação à avaliação desse quadro, julgue o item a seguir. A gastrite atrófica como causa de anemia\nperniciosa é um diagnóstico provável para esse caso.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-140664","number":"140664","sourceNumber":"140664","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma paciente de trinta anos de idade foi atendida em ambulatório com queixas de\ndispneia aos esforços e fadiga. Ao exame\nfísico, o médico constatou palidez cutâneo-mucosa ++/+4\ne ''língua careca\" (papilas ausentes). Após a realização de hemograma, contagem de reticulócitos\nno sangue periférico e outros exames complementares específicos, a paciente foi diagnosticada\ncom anemia megaloblástica por deficiência de cobalamina. Com referência a esse caso clínico,\njulgue o item subsequente. Leucócitos totais de 2.800 células/µL, plaquetas a 120.000/µL,\ncontagem diferencial de leucócitos normal e presença de neutrófilos hipersegmentados\n(pleocariócitos), na avaliação da série branca e das plaquetas dessa paciente, são resultados\ncompatíveis com o diagnóstico proposto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-140727","number":"140727","sourceNumber":"140727","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"No item seguinte é apresentada uma situação hipotética seguida de uma assertiva a\nser julgada. Uma criança de um ano de idade,\nportadora de anemia falciforme, foi atendida em\nemergência pediátrica chorando muito e apresentando-se irritada. Ao exame físico, observaram-se\npalidez intensa, dor à palpação do abdome e volumosa esplenomegalia. O resultado do\nhemograma completo mostrou hematócrito de 15%, hemoglobina de 4,5 g/dL, 15.000\nleucócitos/mm³, 125.000 plaquetas/mm³. Nesse caso, a criança pode estar com crise de sequestro\nesplênico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-108154","number":"108154","sourceNumber":"108154","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Com relação ao tubo digestivo, às suas glândulas anexas e às patologias que\nacometem esses sistemas, julgue o item subsequente. O evento inicial para a produção de\nbilirrubina é representado pela destruição das hemácias no sistema reticuloendotelial.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-79678","number":"79678","sourceNumber":"79678","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A. J. S., 65 anos, cirrótico, histórico de diabetes tipo 2 apresentou exames de\ndiagnóstico salientando-se pancitopenia com\nmicrocitose e hipocromia, prolongamento do tempo de\nprotrombina e tromboplastina ativada, gama-GT e AST acima do limite superior da normalidade,\nácido fólico e vitamina B12 normais. É correto afirmar que se deve excluir cirrose por abuso de\nálcool","options":{"A":"pois o paciente é diabético.","B":"pois o paciente está pancitopênico.","C":"devido à presença de vitamina B12 em níveis normais.","D":"devido à AST elevada.","E":"devido ao tempo de protrombina ativada."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-79667","number":"79667","sourceNumber":"79667","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança com quadro febril fez uso de paracetamol, evoluiu com quadro súbito de\npalidez, icterícia, hemograma com anemia e\nreticulócitos aumentados. Assinale a alternativa que\napresenta o diagnóstico provável.","options":{"A":"Deficiência de G6PD.","B":"Talassemia.","C":"Anemia falciforme.","D":"Síndrome hemolítico-urêmica.","E":"Hepatite fulminante por paracetamol."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-88631","number":"88631","sourceNumber":"88631","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Acerca da crise álgica da anemia falciforme, julgue o item a seguir. A crise álgica pode\nocorrer sem causa aparente ou ser desencadeada por desidratação, infecção, frio ou estresse\nfísico e emocional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-64677","number":"64677","sourceNumber":"64677","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Nos exames de rotina de trabalho, Jéssica, 72 anos, evidenciou uma anemia\nmicrocítica e hipocrômica, com os seguintes\nvalores laboratoriais para o perfil do ferro: ferritina 348\nmg/ml (aumentada), ferro sérico 40 ng/dl (diminuído), CTLT e IST normais e ausência de\ndismorfismo eritrocitário. A partir dos dados acima, pode-se afirmar que se trata da anemia:","options":{"A":"megaloblástica.","B":"ferropriva.","C":"de doença crônica.","D":"sideroblástica.","E":"falciforme."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-64624","number":"64624","sourceNumber":"64624","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação aos resultados apresentados pela\neletroforese quando realizado o teste do pezinho.","options":{"A":"Resultado FA para interpretação de normalidade.","B":"FAS traço falciforme.","C":"FAD para interpretação de traço D.","D":"FAC para interpretação de doença falciforme.","E":"FS para doença falciforme."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-52622","number":"52622","sourceNumber":"52622","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Acerca da anemia ferropriva, doença nutricional comum na infância, julgue o item\nsubsequente. Os principais fatores que devem ser observados ao surgimento da anemia ferropriva\nem crianças com menos de dois anos de idade são: nível de reserva de ferro ao nascimento; taxa\nde crescimento; tipo de dieta; perda de ferro.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-27568","number":"27568","sourceNumber":"27568","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança com 8 meses de vida vem apresentando redução do apetite e pouco ganho\nponderal. Ao exame físico apresenta bom estado geral, ativo, cooperante, porém com importante\npalidez cutâneo-mucossa; fígado a 3 cm do rebordo costal direito, baço não palpável, traube livre,\nsem outras anormalidades no exame físico. História pré e perinatais sem intercorrências, porém\napresentou icterícia fisiológica. É alimentado com leite de vaca desde o 4° mês de vida. Qual a\nhipótese diagnóstica mais provável?","options":{"A":"Anemia ferropriva.","B":"Anemia falciforme.","C":"Anemia hemolítica.","D":"Infecção urinária.","E":"Parasitose intestinal."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-14053","number":"14053","sourceNumber":"14053","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O diagnóstico de anemia perniciosa é confirmado através do seguinte exame:","options":{"A":"hemograma completo.","B":"contagem de reticulócitos.","C":"Mielograma.","D":"anticorpos anticélulas parietais.","E":"teste de Schilling."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-366161","number":"366161","sourceNumber":"366161","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma mulher de 42 anos de idade apresenta queixa de \"\"anemia de longa data\"\". À\nrevisão de sistemas, relata episódios\nrecorrentes de epistaxe espontâneas desde a infância, com\nmúltiplas idas ao Pronto Atendimento, especialmente em dias de clima seco. A paciente informa ter\ntratado a anemia anteriormente com diferentes reposições de sulfato ferroso, mas sem alcançar a\ncura. Destaca que considera isso normal, pois seu pai, irmãos e sobrinha enfrentam quadros\nsemelhantes. Quanto aos antecedentes, não apresenta comorbidades prévias. No exame físico,\nobserva-se palidez cutaneomucosa e a presença de várias telangiectasias cutâneas, algumas\nlocalizadas nas palmas das mãos e plantas dos pés, além de afetar a mucosa oral conforme\nimagem acima. Considerando o quadro clínico apresentado, bem como os assuntos correlatos,\nJulgue o item a seguir. Infere-se do texto que o quadro possa ser decorrente de uma doença\nautossômica dominante.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":["question_bank/media/medcurso/medcurso-hemato-hem-1/366161.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-366232","number":"366232","sourceNumber":"366232","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma mulher de 42 anos de idade apresenta queixa de \"\"anemia de longa data\"\". À\nrevisão de sistemas, relata episódios\nrecorrentes de epistaxe espontâneas desde a infância, com\nmúltiplas idas ao Pronto Atendimento, especialmente em dias de clima seco. A paciente informa ter\ntratado a anemia anteriormente com diferentes reposições de sulfato ferroso, mas sem alcançar a\ncura. Destaca que considera isso normal, pois seu pai, irmãos e sobrinha enfrentam quadros\nsemelhantes. Quanto aos antecedentes, não apresenta comorbidades prévias. No exame físico,\nobserva-se palidez cutaneomucosa e a presença de várias telangiectasias cutâneas, algumas\nlocalizadas nas palmas das mãos e plantas dos pés, além de afetar a mucosa oral conforme\nimagem acima. Considerando o quadro clínico apresentado, bem como os assuntos correlatos,\nJulgue o item a seguir. Conclui-se do quadro exposto que o paciente em questão tem 3 de 4\ncritérios os quais são utilizados para diagnóstico clínico da condição apresentada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":["question_bank/media/medcurso/medcurso-hemato-hem-1/366232.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-366228","number":"366228","sourceNumber":"366228","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma mulher de 54 anos de idade relata fadiga, díspneia em esforços intensos,\nlipotimia, palpitações e perda de peso não\nquantificada nos últimos seis meses. Não menciona\nrestrições alimentares, porém, refere síncope há um mês. Informa que foi hospitalizada\nrecentemente, recebendo transfusão sanguínea devido a uma \"\"Importante alteração no sangue\"\".\nAntecedentes médicos incluem hipertensão arterial sistêmica, obesidade, hipotireoidismo,\nesteatose hepática e dislipidemia, negando tabagismo e etilismo. Na história familiar, destaca-se a\npresença de artrite reumatoide na mãe, que está em tratamento com anti-hipertensivos e\nhipolipemiantes. No exame físico, observa-se palidez cutaneomucosa, sem outras alterações\nevidentes. Os exames laboratoriais revelam hemoglobina de 9,8 g/dL, hematócrito de 37,4%, VCM\nde 114 fL, HCM de 41 e leucograma com quantitativo sem alterações notáveis, exceto por uma\nanomalia visualizada no esfregaço de sangue periférico, conforme imagem apresentada acima.\n\nConsiderando o quadro clínico, exames laboratoriais e achado de série branca e assunto correlatos\nque o caso clínico suscita, julgue o item que\nsubsecutivo. A principal hipótese diagnóstica etiológica\ne deficiência de vitamina B12.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":["question_bank/media/medcurso/medcurso-hemato-hem-1/366228.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-366227","number":"366227","sourceNumber":"366227","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma mulher de 54 anos de idade relata fadiga, díspneia em esforços intensos,\nlipotimia, palpitações e perda de peso não\nquantificada nos últimos seis meses. Não menciona\nrestrições alimentares, porém, refere síncope há um mês. Informa que foi hospitalizada\nrecentemente, recebendo transfusão sanguínea devido a uma \"\"Importante alteração no sangue\"\".\nAntecedentes médicos incluem hipertensão arterial sistêmica, obesidade, hipotireoidismo,\nesteatose hepática e dislipidemia, negando tabagismo e etilismo. Na história familiar, destaca-se a\npresença de artrite reumatoide na mãe, que está em tratamento com anti-hipertensivos e\nhipolipemiantes. No exame físico, observa-se palidez cutaneomucosa, sem outras alterações\nevidentes. Os exames laboratoriais revelam hemoglobina de 9,8 g/dL, hematócrito de 37,4%, VCM\nde 114 fL, HCM de 41 e leucograma com quantitativo sem alterações notáveis, exceto por uma\nanomalia visualizada no esfregaço de sangue periférico, conforme imagem apresentada acima.\n\nConsiderando o quadro clínico, exames laboratoriais e achado de série branca e assunto correlatos\nque o caso clínico suscita, julgue o item\nque subsecutivo. É frequente a coexistência de\nHipotireoidismo de Hashimoto com a deficiência de vitamina B12 como etiologia do quadro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":["question_bank/media/medcurso/medcurso-hemato-hem-1/366227.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-343410","number":"343410","sourceNumber":"343410","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A conduta para anemia em crianças menores de 12 meses, usando fórmulas com leite\nde vaca não enriquecidas com ferro é:","options":{"A":"Indicação de 1 a 2 mg/kg/dia de ferro dos 4 aos 18 meses. Se não tiver sido suplementada,\nsolicite hemograma entre 9 e 12 meses.","B":"Indicação de 2 a 4 mg/kg/dia de ferro dos 2 aos 6 meses, quando deve ser solicitado\nhemograma.","C":"Indicação de 2 mg/kg/dia após 1 mês de vida por 2 meses. Depois, reduza a dose para 1 a 2\nmg/kg/dia até os 18 meses. Solicite hemograma aos 15 meses.","D":"Nenhuma das alternativas anteriores."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-268893","number":"268893","sourceNumber":"268893","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma paciente de 23 anos de idade, sem comorbidades conhecidas, compareceu ao\npronto atendimento com queixa de astenia e de redução da capacidade de exercício e negou\nsangramentos. Ao exame físico, estava hipocorada 3+/4 e não havia outras alterações.\n\nVerificam-se FC = 100 bpm, FR = 22 irpm e SatO? = 97%. Os exames iniciais mostram\nhemoglobina = 7,8 g/dL, hematócrito = 22%,\nVCM = 98 fl, HCM = 32 pg e bilirrubinas totais = 2,0\nmg/dL, sendo 1,3 indireta e 0,7 direta. Para confirmar a hipótese diagnóstica de anemia hemolítica,\nespera-se encontrar","options":{"A":"teste de Coombs direto positivo, aumento de reticulócitos e aumento da haptoglobina.","B":"elevação da desidrogenase láctica, aumento de reticulócitos e queda da haptoglobina.","C":"queda da desidrogenase láctica, aumento de reticulócitos e queda da haptoglobina.","D":"elevação da desidrogenase láctica, queda de reticulócitos e teste de Coombs direto positivo.","E":"teste de Coombs direto positivo, que, isoladamente, já é suficiente para confirmar hemólise."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-266432","number":"266432","sourceNumber":"266432","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada à pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de Doença do Refluxo Gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. Nos casos de pacientes com\nDRGE de longa data, o uso contínuo de Inibidor de Bomba de Prótons (IBP) pode comprometer a\nabsorção da vitamina B12.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-274621","number":"274621","sourceNumber":"274621","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Quanto à ocorrência dos três mecanismos fisiopatológicos essenciais na anemia, é\nCORRETO afirmar:","options":{"A":"Destruição de micróglia, diminuição da contagem de hemácias devido à hemorragia, falência na\nprodução de hemoglobina.","B":"Destruição de eritrócitos, diminuição da contagem de eritrócitos devido à hemorragia, falência na\nprodução de eritrócitos.","C":"Destruição de eritrócitos, diminuição da contagem de células devido à hemorragia, aumento na\nprodução de eritrócitos.","D":"Aumento de eritrócitos, diminuição da contagem de eritrócitos devido à hemorragia, falência na\nprodução de hemoglobina."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-273346","number":"273346","sourceNumber":"273346","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Dentre as combinações de exames laboratoriais abaixo, a que tem a maior\nprobabilidade de representar uma doença megaloblástica secundária à depleção de folato é:","options":{"A":"reticulocitose e elevação da homocisteína.","B":"anemia macrocítica e elevação do ácido metilmalônico.","C":"leucopenia e elevação da homocisteína.","D":"plaquetopenia e elevação do ácido metilmalônico."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-291504","number":"291504","sourceNumber":"291504","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um homem de 57 anos de idade comparece ao ambulatório de clínica médica de\nhospital de média complexidade para\navaliação diagnóstica de quadro de fraqueza, cansaço,\nadinamia e desequilíbrio nos membros inferiores (MMII). Segundo informa, seu estado geral era\nbom até 3 meses antes, quando passou a perceber fraqueza e adinamia. Pensou ser decorrente do\nhipotireoidismo, mas após reavaliação hormonal, sua endocrinologista informou-lhe que a tireoidite\nde Hashimoto estava bem controlada, não sendo necessário nenhum reajuste da dose de\nlevotiroxina em uso crônico (125 mcg/dia). Como os sintomas persistiram, procurou facultativo que\nlhe solicitou um hemograma completo, cujo resultado revelou o seguinte padrão: hemoglobina = 7,6\ng/dl (valor de referência = 13 a 16,5 g/dl); hematócrito = 26% (valor de referência = 40 a 52%);\nhemácias = 2,3 × 10?/mcl (valor de refer?ncia = 4,5 a 6,0 × 10?/mcl); volume corpuscular médio =\n113 fl (valor de referência = 80 a 100 fl); leucócitos = 2.800/mcl (valor de referência = 6.000 a\n10.000/mcl), com contagem diferencial normal; plaquetas = 86.000/mcl (valor de referência = 150 a\n400 × 10³/mcl). Ao exame físico procedido na consulta, o paciente encontra-se bastante pálido,\nictérico (+/4+), normotenso, levemente taquicárdico (104 bpm) e hidratado; exame do aparelho\ncardiovascular revela apenas sopro sistólico pancardíaco, enquanto o exame do aparelho\nrespiratório e do abdome é normal. Contudo, ao exame neurológico, é observada perda da\npropriocepção consciente e da sensibilidade vibratória nos MMII, sendo o reflexo cutâneo-plantar\nem extensão bilateral. Uma hematoscopia realizada durante o exame no ambulatório revela a\npresença de plurissegmentação dos neutrófilos. A etiologia mais provável da anemia do paciente\nem apreço é:","options":{"A":"Hipotireoidismo.","B":"Anemia hemolítica autoimune.","C":"Anemia perniciosa.","D":"Deficiência de ácido fólico."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-263393","number":"263393","sourceNumber":"263393","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um Agente Comunitário de Saúde solicita que o médico da equipe avalie uma senhora\nde 78 anos de idade que vem apresentando\nconfusão mental nos últimos meses. Ao realizar a\navaliação, o médico nota que a paciente está em regular estado geral, confusa e descorada. O\nexame físico mostrou reflexo de Babinski presente bilateralmente e incoordenação motora.\n\nConsiderando o caso clínico apresentado, assinale a alternativa que contempla CORRETAMENTE\no exame laboratorial que deve ser solicitado, o\nresultado e o diagnóstico.","options":{"A":"Hemograma; VCM = 120 fl; anemia perniciosa.","B":"Hemograma; VCM = 80 fl; anemia por deficiência de ácido fólico.","C":"FAN; positivo com padrão nuclear pontilhado fino denso; encefalopatia renal.","D":"FAN; positivo com padrão nuclear pontilhado grosso; encefalopatia lúpica."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-291548","number":"291548","sourceNumber":"291548","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um adolescente do sexo masculino, de 13 anos de idade, em atendimento de rotina,\nrelata desânimo e cansaço para ajudar nas\natividades domésticas e inapetência. Recordatório\nalimentar: 3 sanduiches de pão de forma com manteiga e batata frita no almoço e no jantar, nos\nintervalos ingere balas e biscoitos, além de 1 000 mL de leite por dia. Exame físico sem alterações,\npeso, estatura e IMC no percentil 50 das curvas de referência e G3P3 de acordo com estadiamento\nde Tanner. Hemograma: hemoglobina = 12,1 g/dL; hematócrito = 35%; VCM ? 75fl; CHCM ?\n\n26,5g/dl. Considerando que a Organização Mundial de Saúde refere, de maneira geral para\nadolescentes, valores normais de hemoglobina ? 12g%, é correto afirmar que","options":{"A":"o paciente apresenta anemia megaloblástica, sendo necessária a correção dietética com\nalimentos fontes de vitamina B12 e folatos.","B":"o paciente não apresenta alterações clínicas ou laboratoriais, sendo necessário investigar outras\ncausas que justifiquem as queixas do mesmo.","C":"o paciente apresenta anemia carencial por deficiência de ferro, sendo necessária a correção\ndietética e a administração de sulfato ferroso.","D":"o paciente não apresenta anemia, contudo o resultado laboratorial sugere deficiência de ferro,\ndevendo-se realizar a orientação dietética pertinente."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-158056","number":"158056","sourceNumber":"158056","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 22 anos de idade, negra, atendende de telemarketing, apresenta-se ao\npronto-socorro queixando-se de dor muito intensa nos antebraços esquerdo e direito. Nega trauma\ne esforços físicos não usuais. O exame físico é normal, exceto pela dor. As radiografias não\ndemonstram alterações. A paciente refere que apresenta esses sintomas desde criança, várias\nvezes ao ano, com exames sempre normais, frequentemente sendo liberada com prescrição de\nanti-inflamatórios não hormonais, sem grande melhora dos sintomas. Já apresentou esses mesmos\nsintomas em diversas topografias do esqueleto apendicular. No histórico médico progresso, refere\napenas uma anemia em investigação, de etiologia não definida. Relata que dois dos três irmãos\n\napresentam quadro clínico semelhante. Considerando esse caso clínico e o provável diagnóstico da\npaciente, assinale a alternativa CORRETA.","options":{"A":"O uso de penicilina V oral está indicado para essa paciente em razão da maior suscetibilidade a\ninfecções por bactérias encapsuladas.","B":"A presença de leucocitose sem desvio nos exames laboratoriais não é achado compatível.","C":"Aumento expressivo de LDH e da bilirrubina direta são esperados com diminuição da\nhaptoglobina.","D":"A presença de corpúsculos de Howell-Jolly na hematoscopia não é compatível com quadro\nclínico da paciente.","E":"Essa paciente apresenta indicação de profilaxia para as crises, sendo que, quando iniciada a\nmedicação, certos níveis de mielossupressão são toleráveis."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-168481","number":"168481","sourceNumber":"168481","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma criança com 6 anos de idade, portadora de anemia falciforme, é internada com\nquadro de febre de 38,5°C, associada a\ntosse, dispineia intensa e dor torácica há 3 dias. Ao exame\nfísico, encontra-se hipoativa, hipocorada +++/4, taquipineica, taquicárdica, com sopro sistólico de\n\n++/6, fígado a 2 cm do rebordo costal direito e baço não papável, saturação de O2 = 92% em ar\nambiente. Radiografia de tórax revela opacificações em lobos inferiores. O hemograma revela\nhemoglobina = 6,0 g/dL (valor de referência: 12 a 16 g/dL), sendo a hemoglobina do mês anterior\nigual a 7,2 g/dL. Foram iniciados os procedimentos de oxigenioterapia com máscara com\nreservatório a 10 L/min, hidratação venosa e analgesia, observando-se elevação da saturação de\nO2 para 94%. Nesse caso, a conduta terepêutica adequada é","options":{"A":"transfusão de concentrado de hemácias e início de antibioticoterapia empírica de amplo\nespectro.","B":"transfusão de concentrado de hemácias e instalação de BIPAP.","C":"antibioticoterapia empírica de amplo espectro e surfactante.","D":"exosanguineotransfusão parcial e instalação de BIPAP."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-111354","number":"111354","sourceNumber":"111354","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O achado clínico mais comumente observado nos pacientes portadores de carcinoma\nde cólon direito é:","options":{"A":"A alteração do hábito intestinal.","B":"O tenesmo.","C":"A hematoquezia.","D":"A obstrução.","E":"A anemia."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-111358","number":"111358","sourceNumber":"111358","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma criança do sexo feminino, de 11 meses de idade, é levada ao pediatra por falta de\napetite e palidez. História de prematuridade e aleitamento materno exclusivo até os 2 meses de\nidade, sendo então introduzido leite de vaca. Sem icterícia neonatal. Hemograma: hemoglobina =\n7,1 g/dl; hematócrito = 21%; VCM = 55 fl; reticulócitos = 0.5%; leucócitos = 6000/mm³; plaquetas\n700.000/mm³. Assinale a hipótese diagnóstica mais provável e os exames necessários para a\nconfirmação:","options":{"A":"Esferocitose - fragilidade osmótica.","B":"Anemia ferropriva - eletroforese de hemoglobina.","C":"Talassemia - dosagem de hemoglobina fetal.","D":"Deficiência de G6PD - dosagem de G6PD.","E":"Anemia ferropriva - dosagem de ferro sérico e ferritina."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-97842","number":"97842","sourceNumber":"97842","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um lactente, negro, com um ano de idade, foi encaminhado ao Ambulatório de\nPediatria pelo surgimento de quadro recente\nde febre e palidez acompanhadas de dor e inchaço\nnos dedos das mãos e pés. Na ocasião foi colhido hemograma e prescrito analgésico. O lactente,\nnascido com 38 semanas de gestação, foi amamentado exclusivamente até quatro meses de vida,\nquando foi introduzida alimentação complementar. A mãe acha que a criança não aceita bem a\nrefeição salgada e toma quatro mamadeiras por dia. Nega doenças anteriores. Ao exame físico, a\ncriança encontra-se descorada ++/4+, sem outras alterações. A mãe traz hemograma anterior:\nHemoglobina = 8,5 g/dl (Valor de referência = 10,5 - 13,5 g/dl); Hematócrito = 25% (Valor de\nreferência = 33% - 39%); VCM = 85 fl (Valor de referência = 70 - 86 fl); RDW normal; reticulócitos =\n4% CVSs (Valor de referência = 0,5% - 2,5% CVSs); leucócitos = 14,400/mm³ (Valor de referência\n\n= 6,000 - 17,000/mm³); plaquetas = 323,000/mm³ (Valor de referência = 150,000 - 350,00/mm³).\nCom base no quadro clínico e no hemograma\napresentados, qual o diagnóstico correto e qual\nexame laboratorial deve(m) ser solicitado(s) para confirmação do diagnóstico?","options":{"A":"Anemia ferropriva; perfil de ferro sérico.","B":"Talassemia; eletroforese de hemoglobina.","C":"Anemia falciforme; eletroforese de hemoglobina.","D":"Anemia megaloblástica; dosagem de vitamina B12 e ácido fólico sérico."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-97740","number":"97740","sourceNumber":"97740","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma mulher com 34 anos de idade, em atendimento ambulatorial, refere palpitação,\nfraqueza e sensação de desmaio, iniciadas há\ntrês meses e que vêm se agravando. A paciente não\nrefere emagrecimento ou febre e está em uso irregular de anticoncepcional oral e de fluoxetina - 40\nmg/dia. Ao exame encontra-se descorada, hidratada, sem visceromegalias, taquicárdica, com\nbulhas rítmicas e normofonéticas. O resultado do hemograma revela: hemoglobina:7,8 g/dl (Valor\nde referência = 12 - 16 g/dl); hematócrito: 25% (Valor de referência = 36% - 46%); volume\ncorpuscular médio: 70 fl (Valor de referência= 80 - 100 fl); RDW diminuído; leucócitos totais:\n7.470/mm³ (Valor de referência = 4.500 - 11.000/mm³) - [3% bastões, 55% segmentados, 35%\nlinfócitos, 7% monócitos]; plaquetas: 234.000/mm³ (Valor de referência = 150.000 - 350.000/mm³).\nSobre as hipóteses diagnósticas e a investigação laboratorial complementar para essa paciente, é\ncorreto afirmar que se trata de provável anemia:","options":{"A":"ferropriva e espera-se que a dosagem de ferro sérico, a ferritina e o índice de saturação de\ntransferrina estejam baixos.","B":"por perda crônica de sangue, por via menstrual ou gastrointestinal, e espera-se aumento na\ncontagem de reticulócitos.","C":"secundária à neoplasia, sendo necessário o rastreamento nos sítios mais comuns para mulher,\nmama e colo de útero.","D":"devido à deficiência ou erro alimentar na ingestão de ferro, não sendo necessária investigação\nadicional para a paciente."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-75562","number":"75562","sourceNumber":"75562","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher com 50 anos de idade procura Ambulatório de Clínica Médica com queixa de\nfadiga e dispneia aos esforços. Informa ser portadora de refluxo gastroesofágico, em uso frequente\nde cimetidina para alívio sintomático. Tem endoscopia digestiva normal. Não tem outras queixas.\n\nAo exame físico apresenta palidez cutâneo-mucosa e não\n\nhá outros achados relevantes. Hemograma mostra: Ht = 22%; Hb = 7,1 g/dl; VCM = 102 fl; CHCM =\n33%; Leucócitos = 2.500/mm³ (neutrófilos = 1.200, linfócitos = 800, monócitos = 500); Plaquetas =\n95.000/mm³; Reticulócitos ausentes.\n\nCom base nesses achados, qual o diagnóstico mais provável?","options":{"A":"Anemia perniciosa.","B":"Anemia aplásica.","C":"Anemia hemolítica.","D":"Anemia de doença crônica.","E":"Anemia por deficiência de folato."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-137549","number":"137549","sourceNumber":"137549","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma criança com 6 anos de idade, moradora em zona rural, é trazida por sua mãe à\nUnidade Básica de Saúde (UBS) por apresentar palidez, falta de apetite, perda de peso e\nrendimento escolar insatisfatório observados há dois meses.\n\nAlém da dosagem de hemoglobina e hematimetria, que outros exames, com seus respectivos\nresultados, servirão para o diagnóstico de uma anemia carencial?","options":{"A":"Morfologia das hemácias: normocítica e normocrômica; ferritina baixa; ferro sérico normal;\ncapacidade de ligação do ferro baixa; saturação de transferrina normal.","B":"Morfologia das hemácias: microcítica e hipocrômica;\n\nferritina baixa; ferro sérico baixo; capacidade de ligação do ferro elevada; saturação de\ntransferrina\nbaixa","C":"Morfologia das hemácias: normocítica e normocrômica;\n\nferritina normal; ferro sérico baixo; capacidade de ligação do ferro baixa; saturação de\ntransferrina\nnormal.","D":"Morfologia das hemácias: microcítica e normocrômica;\n\nferritina baixa; ferro sérico baixo; capacidade de ligação do ferro elevada; saturação de\ntransferrina\nbaixa.","E":"Morfologia das hemácias: normocítica e hipocrômica; ferritina normal; ferro sérico normal;\ncapacidade de ligação do ferro baixa; saturação de transferrina normal."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-138398","number":"138398","sourceNumber":"138398","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança com um ano de idade foi amamentada com leite materno exclusivamente até\nos seis meses, quando passou a receber alimentação complementar com frutas, papa salgada\ncomposta de vegetais, cereais e, às vezes, carne. Na ocasião da consulta de puericultura, por\napresentar palidez, o médico solicitou eritrograma que apresentou os seguintes resultados :\nHemoglobina = 10,2 mg/dL (valor normal = 11 - 13 mg/dL); Hematócrito = 30,8 % (valor normal =\n36-44 %); Volume\n\nCorpuscular Médio = 75 fL (valor normal = 77- 101 fL); Hemoglobina Corpuscular Média = 21 pg\n(valor normal = 23-31 pg); Concentração de\nHemoglobina Corpuscular Média = 26 g/dL (valor\nnormal = 28-33 g/dL) e RDW = 15,5 % (valor normal <14 %). A hipótese diagnóstica elaborada pelo\nmédico e o exame complementar que melhor confirrma esse diagnóstico são, respectivamente,","options":{"A":"anemia falciforme e contagem de reticulócitos.","B":"anemia por deficiência de ácido fólico e dosagem\nde folatos.","C":"anemia megaloblástica e eletroforese de hemoglobina.","D":"anemia carencial ferropriva e dosagem da ferritina\nsérica.","E":"talassemia e dosagem de ferro sérico."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-138401","number":"138401","sourceNumber":"138401","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher com 48 anos de idade, parda, comerciante, procura o posto de saúde por\napresentar astenia, palidez e fadiga fácil ao\nrealizar suas tarefas diárias. Na história da doença\natual relata que esteve bem de saúde até há 15 dias, quando iniciaram estes sinais e sintomas.\nNega doenças como diabetes, hipertensão, doenças da tireóide. Nega também o uso de\nmedicamentos. Ao exame físico apresenta palidez, icterícia (2+/4+), esplenomegalia de 4 cm do\nrebordo costal esquerdo e hepatomegalia de 2 cm do rebordo costal direito. Exames laboratoriais\nrealizados mostram hemoglobina = 4,2 g/ dL; hematócrito = 13 %; VCM = 110 fL (VR = 80 ? 100\nfL); HCM = 32 pg (VR = 26 ? 34 pg); leucograma = 10.500 / mm3 com diferencial normal; plaquetas\n\n= 240.000 /mm3; reticulócitos aumentados; bilirrubina total = 4,0 mg/dL (VR=0,3 -1,2 mg/dL) com\nfração direta de 0,8 mg/dl (VR = 0 - 0,2\nmg/dL). Qual o diagnóstico mais provável para a anemia da\npaciente?","options":{"A":"Anemia por déficit de produção ocasionada por\ndeficiência de vitamina B12","B":"Anemia do tipo regenerativa provocada por doença hemolítica adquirida.","C":"Anemia arregenerativa por deficiência quantitativa\nde células progenitoras associada à hepatite viral.","D":"Anemia por deficiência na síntese do heme durante a diferenciação das células eritroides.","E":"Anemia por deficiência na síntese da globina durante a diferenciação das células eritroides."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-30949","number":"30949","sourceNumber":"30949","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Julgue o item seguinte, a respeito da anatomia e fisiologia humanas. O fator intrínseco,\nmucoproteína secretada pelas células parietais gástricas, é essencial para a absorção de vitamina\nB12 no íleo terminal?","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-30980","number":"30980","sourceNumber":"30980","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um jovem, 18 anos de idade, com diagnóstico de anemia falciforme foi trazido ao\npronto-socorro em consequência de\nhemiparesia direta e afasia iniciadas há uma hora. Os\nantecedentes pregressos desse paciente são seis episódios de vaso-oclusão ao longo da vida e\npolitransfusões sanguíneas. Julgue o item a seguir, relativo ao caso clínico em apreço. Como nessa\nsituação o principal diagnóstico é de evento isquêmico cerebral, deve-se realizar hemotransfusão\ncomo parte essencial do tratamento.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-30983","number":"30983","sourceNumber":"30983","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um jovem, 18 anos de idade, com diagnóstico de anemia falciforme foi trazido ao\npronto-socorro em consequência de hemiparesia direta e afasia iniciadas há uma hora. Os\nantecedentes pregressos desse paciente são seis episódios de vasoclusão ao longo da vida e\npolitransfusões sanguíneas. Julgue o item a seguir, relativo ao caso clínico em apreço. De acordo\ncom as atuais evidências científicas, recomenda-se o uso hidroxiureia no tratamento desse\npaciente.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-138740","number":"138740","sourceNumber":"138740","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança do sexo masculino, com três anos de idade e que apresenta anemia falciforme,\né levado pela mãe à consulta na Unidade Básica\nde Saúde porque está tendo febre há quatro dias,\nchegando a 39°C. Apresenta tosse produtiva que aumentou de intensidade. Encontra-se em estado\ngeral de prostração e a mãe notou que a criança está mais pálida e ictérica nos últimos dias. O\npediatra encaminhou a criança de imediato para o hospital de referência, considerando que","options":{"A":"as infecções são as complicações mais frequentes\nna anemia falciforme, acompanhadas de\n\nesplenomegalia que se acentua após os cinco anos de idade.","B":"a importância das infecções como complicações na anemia falciforme, deve-se à maior\nsusceptibilidade à bactéria Salmonella na faixa etária abaixo dos cinco anos.","C":"a mortalidade entre crianças falcêmicas menores de cinco anos é elevada, sendo as\ncomplicações mais frequentes as infecções por Haemophilus influenzae tipo b (Hib) e por\npneumococo.","D":"as infecções são as complicações mais frequentes, e o uso de profilaxia com penicilina é\ncontra-indicado pelos riscos de aumento da taxa de colonização por cepas de pneumococos\nresistentes.","E":"as infecções são as complicações mais frequentes, o que leva à necessidade de profilaxia com\npenicilina, recomendada do momento do diagnóstico da anemia falciforme e mantida por toda a\nvida."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-351612","number":"351612","sourceNumber":"351612","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um paciente com 13 anos de idade, com diagnóstico de anemia falciforme comparece à\nconsulta de rotina no ambulatório e questiona seu médico sobre seu risco de apresentar um\nacidente vascular cerebral (AVC), pois seu irmão mais novo, também portador de anemia\nfalciforme, está internado no hospital devido a um AVC. Nesse caso, é CORRETO afirmar que as\nrecomendações para a prevenção de AVC são:","options":{"A":"Realizar ecografia transcraniana com Doppler, apenas se o paciente apresentar sintomas.","B":"Verificar o uso de hidroxiureia e sua eficácia pelos níveis de HbF e rever resultados de sua\núltima ecografia transcraniana, repetindo-a, se necessário.","C":"Iniciar esquema de transfusão crônica, se houver alteração na velocidade de fluxo da artéria\ncerebral acima de 270cm/seg.","D":"Manter níveis de HbS inferiores a 50%."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-368189","number":"368189","sourceNumber":"368189","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Dentre as doenças hematológicas a seguir, aquela que tem como indicação primária o\ntratamento pela esplenectomia é a","options":{"A":"eliptocitose hereditária.","B":"talassemia maior.","C":"anemia falciforme.","D":"esferocitose hereditária."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-359218","number":"359218","sourceNumber":"359218","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Na anemia ferropriva, a resposta terapêutica à reposição com ferro pode ser avaliada\npelo exame clínico e/ou exames laboratoriais.\nNesse contexto, correlacione a COLUNA II de acordo\ncom a COLUNA I. COLUNA I; I - 24h de tratamento; II - 48h de tratamento; III - 1 semana de\ntratamento; IV - 30 dias de tratamento; V - 4 meses de tratamento; COLUNA II; ( ) Resposta\nmedular inicial, hiperplasia eritróide. ( ) Aumento do nível de hemoglobina. ( ) Reposição de\nreservas de ferro. ( ) Melhora da irritabilidade, recuperação de enzimas férricas. ( )\nReticulocitose.\n\nAssinale a alternativa que apresenta a sequência CORRETA.","options":{"A":"I, II, IV, V, III","B":"III, V, IV, I, II","C":"II, IV, V, I, III","D":"IV, I, III, II, V"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-352204","number":"352204","sourceNumber":"352204","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactente masculino, 9 meses, compareceu para puericultura com quadro de palidez\ncutâneomucosa. História pregressa não relevante. Exame físico sem outras alterações. O\nhemograma revelou hemoglobina de 9,1 g/dl, VCM e HCM baixos, RDW elevado. Teste de pezinho\ncom eletroforese de hemoglobina mostrando padrão FAS. Considerando o relato, assinale a\ncorreta:","options":{"A":"Repetir eletroforese de hemoglobina para confirmar traço falciforme e iniciar profilaxia com\nácido\nfólico e ferro.","B":"Repetir eletroforese de hemoglobina para confirmar doença falciforme e iniciar antibioticoterapia\nprofilática.","C":"Realizar dosagem de ferro sérico, ferritina e saturação de tranferrina para confirmar anemia por\ndeficiência de ferro e iniciar tratamento com ferro oral.","D":"Hemoglobina normal para a idade (anemia fisiológica do lactente). Não há necessidade de\nnovos exames e deverá ser iniciado profilaxia com\nferro oral."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-334720","number":"334720","sourceNumber":"334720","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"São causas de anemia normocítica.","options":{"A":"Doença renal, doença crônica.","B":"Deficiência de ferro, lesão medular.","C":"Mielodisplasia, talassemia minor.","D":"Anemia sideroblástica, anemia hemolítica."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-335071","number":"335071","sourceNumber":"335071","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre as características e os contextos clínicos que diferenciam a anemia aguda da\nanemia crônica, numere a coluna II de acordo com a coluna I. COLUNA I 1. Anemia aguda 2.\n\nAnemia crônica COLUNA II ( ) Hemorragias secundárias a trauma, sequestro hepático,\nsangramento gastrintestinal ou gênito-urinário. (\n) Etiologia específica de destruição ou diminuição\nda produção das hemácias; pode apresentar reticulocitose. ( ) Processo progressivo que o\norganismo instala para ajustar a reduzida capacidade de transporte de O2 . ( ) Anemia hemolítica\nsecundária à microangiopatia e à coagulação intravascular disseminada. ( ) Doença falciforme com\ncrise aplástica, anemia dilucional após rápida infusão de cristaloides. Assinale a sequência\ncorreta.","options":{"A":"2 1 2 1 2","B":"2 2 1 1 2","C":"1 1 1 2 1","D":"1 2 2 1 1"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-321181","number":"321181","sourceNumber":"321181","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia não é uma entidade específica, mas sim o resultado de diversos processos\npatológicos subjacentes. Sobre as anemias, é CORRETO afirmar que:","options":{"A":"Uma forma de diferenciar anemias por deficiência de ferro de talassemia é através do Red Cell\nDistribution Width (RDW) que na talassemia está aumentado.","B":"A anemia megaloblástica por deficiência de ácido fólico pode ocorrer como resultado da ingesta\ninadequada de folato, da diminuição da absorção de folato, ausência de secreção do fator\nintrínseco ou distúrbios adquiridos do metabolismo do folato.","C":"Na anemia fisiológica da infância não é necessário tratamento, apenas que a dieta do neonato\npossua os nutrientes necessários para a\nhematopoiese, como ferro e ácido fólico.","D":"Na anemia falciforme, os pacientes devem receber ácido fólico, 1mg/dia, para prevenir a\ndeficiência secundária de ácido fólico."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-335104","number":"335104","sourceNumber":"335104","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Estudos demostram que a anemia ferropriva afeta dois bilhões de pessoas, sendo\n51,2% da população pediátrica com idade entre\ndois meses e cinco anos. Os fatores como nível\nsocioeconômico, aspectos demográficos e nível de escolaridade dos pais associam-se à alta\nprevalência. Acerca da anemia ferropriva, a resposta terapêutica da reposição com ferro pode ser\navaliada por meio do exame clínico e / ou exames laboratoriais. A esse respeito, numere a\nCOLUNA II de acordo com a COLUNA I. COLUNA I 1. 24 horas de tratamento; 2. 48 horas de\ntratamento; 3. Uma semana de tratamento; 4. 30 dias de tratamento; 5. Quatro meses de\ntratamento. COLUNA II ( ) Resposta medular inicial, hiperplasia eritroide. ( ) Aumento do nível de\nhemoglobina. ( ) Reposição de reservas de ferro. ( ) Melhora da irritabilidade, recuperação de\nenzimas férricas. ( ) Reticulocitose. Assinale a sequência correta.","options":{"A":"1 2 4 5 3","B":"3 5 4 1 2","C":"2 4 5 1 3","D":"4 1 3 2 5"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-304842","number":"304842","sourceNumber":"304842","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem de 22 anos apresenta quadro de fadiga e baixo rendimento físico há cerca de 6\nmeses. Nega outras doenças no período. Ao exame físico, encontrava-se hipocorado, sem outras\nalterações relevantes. O hemograma evidenciou eritrócitos = 2.210.000/mL; hemoglobina = 8,1\ng/dL; hematócrito = 24,1%; VCM = 82,5 fL; HCM = 31pg; CHCM = 38,2%; RDW = 24,2%. O\n\ndiagnóstico etiológico do caso pode ser confirmado por:","options":{"A":"Eletroforese de hemoglobina.","B":"Dosagem de vitamina B12 e ácido fólico.","C":"Testes de Coombs e de fragilidade eritrocitária.","D":"Dosagem de ferritina e índice de saturação da transferrina."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-313277","number":"313277","sourceNumber":"313277","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considerando o caso da questão anterior, o médico identifica uma possível deficiência\nde vitamina B12 e folatos na análise da série\nvermelha. O achado identificado, para levar a essa\nhipótese diagnóstica é:","options":{"A":"Presença de leptócitos.","B":"Presença de dacriócitos.","C":"Presença de microcitose.","D":"Inclusões de Howell-Jolly.","E":"Presença de macrocitose."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-304995","number":"304995","sourceNumber":"304995","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considere que um homem de 41 anos de idade apresenta hemograma com\nhemoglobina = 10 g/L, VCM = 72 fL,\nleucócitos = 3.500/mm³, plaquetas = 170.000/mm³ e ferritina =\n50 ng/mL. Nesse caso, qual é o provável diagnóstico?","options":{"A":"Anemia ferropriva.","B":"Anemia falciforme.","C":"Talassemia.","D":"Sideroblastose."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-314035","number":"314035","sourceNumber":"314035","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação aos critérios morfológicos para classificação das anemias, assinalar a\nalternativa CORRETA:","options":{"A":"A anemia por deficiência de ferro é do tipo macrocítica normocrômica.","B":"A anemia secundária à doença crônica é do tipo macrocítica normocrômica.","C":"A anemia hemolítica é do tipo microcítica hipocrômica.","D":"A anemia por deficiência de folato ou de vitamina B12 é do tipo macrocítica normocrômica.","E":"A anemia aplásica é do tipo microcítica hipocrômica."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-314076","number":"314076","sourceNumber":"314076","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à anemia por deficiência de ferro, analisar os itens abaixo: I. O controle da\nabsorção do ferro pelas células das criptas duodenais é crucial, uma vez que não há um\nmecanismo fisiológico regulável para a excreção do ferro. II. Nos Países desenvolvidos, as\ninfecções por helmintos, que incluem a ancilostomíase e a esquistossomose, estão entre as causas\nmais comuns de perda sanguínea pela via gastrointestinal. III. A anemia ferropriva manifesta-se por\nmeio de sintomas inespecíficos, como fraqueza, palidez, tontura, diminuição da tolerância aos\nexercícios físicos e irritabilidade. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-283885","number":"283885","sourceNumber":"283885","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual dos sintomas ou sinais abaixo NÃO ocorre na anemia ferropriva grave?","options":{"A":"Hipertrofia gengival.","B":"Queilose.","C":"Coiloníquia.","D":"Disfagia secundária à Síndrome de Plummer-Vinson.","E":"Fadiga."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-266367","number":"266367","sourceNumber":"266367","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Anemia é definida pela redução da concentração de hemoglobina e/ou massa\neritrocitária, com variações de acordo com a\nidade, sexo, raça e a altitude em relação ao nível do\nmar. Podem ser classificadas do ponto de vista fisiológico e morfológico. Na classificação\nmorfológica das anemias é CORRETO afirmar:","options":{"A":"A deficiência de ferro, a anemia responsiva à tiamina e a anemia da doença hepática causam\nanemias microcíticas.","B":"A deficiência de ferro, as síndromes talassêmicas e as deficiências de vitamina B12 causam\nanemias microcíticas.","C":"A deficiência de vitamina B12 e ácido fólico, o hipotireoidismo e a aplasia medular congênita ou\nadquirida causam anemias macrocíticas.","D":"A deficiência de vitamina B12 e ácido fólico, a doença inflamatória crônica e a intoxicação pelo\nchumbo causam anemias macrocíticas."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-287856","number":"287856","sourceNumber":"287856","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre as anemias, assinalar a alternativa CORRETA:","options":{"A":"A principal causa de anemia no mundo é a deficiência de vitamina B12.","B":"A anemia ferropriva e a talassemia são consideradas anemias microcíticas.","C":"Solicitar apenas o hemograma é suficiente para a abordagem completa das anemias.","D":"A anemia em homens na faixa dos cinquenta anos e nas mulheres pós-menopausa é\nconsiderada um achado comum.","E":"A anemia perniciosa é comum em crianças, sendo causada, na maior parte das vezes, por\ndeficiência de ácido fólico."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-287904","number":"287904","sourceNumber":"287904","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação às anemias, assinalar a alternativa CORRETA:","options":{"A":"A Organização Mundial da Saúde estima que apenas 10% de todas as anemias sejam causadas\npor deficiência de ferro.","B":"O ferro não heme, encontrado nos produtos de origem vegetal e em alguns produtos de origem\nanimal, tem menor biodisponibilidade do que o ferro heme.","C":"Não há relação entre o alto consumo de leite de vaca e a inibição da absorção do ferro.","D":"A geofagia é um sintoma muito raro de ser encontrado em crianças com anemia.","E":"Em um quadro de deficiência de ferro, com anemia, é esperado que a saturação da transferrina\nesteja acima de 16%."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-234407","number":"234407","sourceNumber":"234407","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um homem de 35 anos vai ao pronto atendimento queixando-se de dispneia ao\ncaminhar 1 quarteirão, com piora progressiva há 7 dias. Nega febre ou outros sintomas.\n\nDesconhece ser portador de doenças prévias e nega o uso de medicamentos ou drogas quaisquer.\nAo exame físico, apresenta-se alerta,\norientado, com as mucosas descoradas, ictéricas e\nhidratadas. Os dados vitais são: PA = 120 x 76 mmHg; FC = 92 bpm; FR = 17 ipm; SpO? em ar\nambiente 98%. Está eupneico em repouso. Sem alterações no restante do exame físico. Exames\nde laboratório: hemoglobina = 6,9 g/dl; HCM = 32 pg; VCM = 102 fl; CHCM = 35 g/dl; RDW =\n18,4%; leucócitos = 7.560/mm³; neutrófilos segmentados = 5.980/ mm³; plaquetas = 230.000/mm³;\nproteína C-reativa = 12 mg/L; creatinina = 1,5 mg/dl; ureia = 90 mg/dl; Coombs direto positivo;\nlactato desidrogenase = 1.090 U/L; bilirrubina total = 2,5 mg/dl; bilirrubina direta = 0,5 mg/dl;\nbilirrubina indireta = 2,0 mg/dl; reticulócitos = 12,2%. Considerando o caso descrito, assinale a\nconduta terapêutica imediata MAIS ADEQUADA para esse paciente:","options":{"A":"Administrar 1 mg/kg de prednisona pela via oral.","B":"Administrar eritropoietina pela via subcutânea.","C":"Administrar ferro pela via intravenosa.","D":"Transfundir 600 ml de concentrado de hemácias."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-246353","number":"246353","sourceNumber":"246353","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 35 anos, vigilante, previamente hígida, comparece ao ambulatório de clínica\nmédica referindo parestesia em membros inferiores de evolução há cerca de um ano. Há 2 meses\nsua mãe faleceu de câncer gástrico e, desde então, está apresentando dificuldade de concentração\ne déficit de memória recente. Após o falecimento de sua mãe a paciente foi submetida a\nendoscopia digestiva alta, que evidenciou gastrite atrófica confirmada por biópsia, com pesquisa\nnegativa para Helicobacter pylori. Além disso, também traz exames realizados de rotina há 1\nsemana que foram solicitados por sua ginecologista: Hemoglobina: 10,4 g/dL, hematócrito 30%,\nVCM: 110 fL, HCM 28 pg, CHCM 32g/dL, RDW 10%, Leucócitos totais 3,5 x 10³/mm³ (basófilos\n0,5%/ eosinófilos 2,5%/ mielócitos 0%/ metamielócitos 0%/ bastões 1%/ segmentados 55%/\nlinfócitos 35%/ monócitos 6%) com hiperssegmentação de neutrófilos, plaquetas 87.000, TSH 4,0\nmUI/L (VR: 0,45 - 4,5 mUI/L). Diante da hipótese diagnóstica mais provável, qual a melhor\nestratégia de tratamento para esse paciente?","options":{"A":"Reposição de vitamina B12 parenteral.","B":"Corticoide em dose imunossupressora.","C":"Ara-C em dose padrão por cinco a dez dias, associado a idarrubicina.","D":"Transplante alogênico de células-tronco hematopoiéticas."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-246354","number":"246354","sourceNumber":"246354","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 35 anos, vigilante, previamente hígida, comparece ao ambulatório de clínica\nmédica referindo parestesia em membros inferiores de evolução há cerca de um ano. Há 2 meses\nsua mãe faleceu de câncer gástrico e, desde então, está apresentando dificuldade de concentração\ne déficit de memória recente. Após o falecimento de sua mãe a paciente foi submetida a\nendoscopia digestiva alta, que evidenciou gastrite atrófica confirmada por biópsia, com pesquisa\nnegativa para Helicobacter pylori. Além disso, também traz exames realizados de rotina há 1\nsemana que foram solicitados por sua ginecologista: Hemoglobina: 10,4 g/dL, hematócrito 30%,\nVCM: 110 fL, HCM 28 pg, CHCM 32g/dL, RDW 10%, Leucócitos totais 3,5 x 10³/mm³ (basófilos\n0,5%/ eosinófilos 2,5%/ mielócitos 0%/ metamielócitos 0%/ bastões 1%/ segmentados 55%/\nlinfócitos 35%/ monócitos 6%) com hiperssegmentação de neutrófilos, plaquetas 87.000, TSH 4,0\nmUI/L (VR: 0,45 - 4,5 mUI/L). Diante do caso, qual a hipótese diagnóstica mais provável?","options":{"A":"Síndrome mielodisplásica.","B":"Leucemia mieloide aguda.","C":"Anemia perniciosa.","D":"Anemia aplásica."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-227251","number":"227251","sourceNumber":"227251","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"No estado carencial de ferro é comum o seguinte achado no hemograma:","options":{"A":"Neutropenia.","B":"Trombocitose.","C":"Aumento do volume corpuscular médio das hemácias (VCM).","D":"Diminuição do RDW (amplitude de distribuição dos eritrócitos)."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-246728","number":"246728","sourceNumber":"246728","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Não corresponde à anemia ferropriva o seguinte achado:","options":{"A":"Volume corpuscular médio baixo.","B":"Ferritina baixa.","C":"Capacidade total de ligação do ferro baixo.","D":"Ferro sérico baixo.","E":"Hemoglobina corpuscular média baixa."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-243029","number":"243029","sourceNumber":"243029","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente, 14 anos, sexo feminino, vai ao consultório acompanhada de sua mãe com\nqueixa de fraqueza, cansaço e falta de apetite há um mês. Há dois anos se tornou vegana e por\nisso não come nenhum tipo de carne. Exame físico: emagrecida, hipocorada +/4+, queilite angular,\ndiscreta fotofobia e leve nistagmo ocular. P: 38 kg, E: 158cm, IMC: 15,2. RCR 2T BNF FC: 99 bpm,\nSat O2: 98%. FR: 37 irpm. A hipótese diagnóstica é deficiência de:","options":{"A":"vitamina K.","B":"zinco e cobre.","C":"zinco e selênio.","D":"vitaminas do complexo B.","E":"zinco selênio e cobre."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-255663","number":"255663","sourceNumber":"255663","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Quanto ao tratamento da anemia ferropriva, em geral em quanto tempo após o início do\ntratamento a contagem de reticulócitos deve começar a aumentar? MARQUE A CORRETA:","options":{"A":"1 a 2 dias.","B":"4 a 7 dias.","C":"7 a 14 dias.","D":"2 a 4 semanas."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-246799","number":"246799","sourceNumber":"246799","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em crianças com diagnóstico confirmado de deficiência de\nglicose-6-fosfato-desidrogenase, a medida terapêutica mais importante é:","options":{"A":"esplenectomia eletiva","B":"hemotransfusão preventiva","C":"prevenção da hemólise","D":"exsanguíneo transfusão parcial","E":"transfusão mensal de concentrado de hemácias"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-220287","number":"220287","sourceNumber":"220287","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 45 anos comparece ao consultório do seu clínico, queixando-se de dispneia\naos esforços e fadiga ao se exercitar. É\netilista e faz uso de 1 L de cachaça ao dia há 15 anos. Traz\nconsigo os resultados dos seguintes exames: hemoglobina = 9,5 g/dl; hematócrito = 28%; volume\ncorpuscular médio = 74 fl; hemoglobina corpuscular média = 23 pg; leucócitos = 5.780/mm³;\nplaquetas = 198.000/mm³; ferro sérico = 15 mcg/dl (VR 50-170); ferritina = 5 ng/ml (VR 11-306);\níndice de saturação de transferrina = 15% (20-50%) e capacidade total de ligação do ferro 410\nmcg/dl (VR 250-425). Em relação ao caso descrito, assinale a alternativa CORRETA:","options":{"A":"A anemia pode estar associada à doença celíaca, à síndrome de supercrescimento bacteriano e\nà angiodisplasia colônica.","B":"A histerectomia está indicada para a prevenção de perda sanguínea pela menstruação.","C":"O principal mecanismo da anemia é a mielotoxicidade induzida pelo álcool.","D":"A transfusão de concentrado de hemácias está indicada, uma vez que a paciente está\nsintomática."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-199527","number":"199527","sourceNumber":"199527","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre o diagnóstico diferencial das anemias, assinale a alternativa CORRETA:","options":{"A":"A talassemia menor cursa, mais comumente, com\nanemia hemolítica normocítica e normocrômica.","B":"A anemia microcítica e hipocrômica, com ferro\nsérico e transferrina reduzidos, índice de\nsaturação de transferrina normal e ferritina\naumentada, é compatível com causa ferropriva.","C":"As anemias macrocíticas podem ser encontradas\nna mielodisplasia, na doença de Crohn ileal, no\nhipotireoidismo e em pacientes etilistas.","D":"As anemias hemolíticas por anormalidades intrínsecas dos eritrócitos possuem em comum o\naumento da bilirrubina indireta e da desidrogenase láctica, a redução da haptoglobina\n\ne o teste de Coombs direto positivo."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-202745","number":"202745","sourceNumber":"202745","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Os diagnósticos diferenciais de anemias hipocrômicas/ microcíticas incluem:","options":{"A":"Anemia ferropriva, traço falcêmico e esferocitose hereditária.","B":"Anemia de doença crônica, deficiência de b12 e ferro.","C":"Deficiência de ferro, talassemias e anemia sideroblástica.","D":"Anemia ferropriva, deficiência de b12, traço falsemico.","E":"Deficiência de ferro e ácido fólico, anemia falciforme."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-199625","number":"199625","sourceNumber":"199625","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A doença falciforme é o termo utilizado para definir um grupo de alterações genéticas\ncaracterizadas pelo predomínio da hemoglobina S (HbS). Na doença falciforme é CORRETO\nafirmar:","options":{"A":"A síndrome torácica aguda é um evento agudo e paciente com doença falciforme, caracterizado\npela presença de febre e/ou sintomas respiratórios\n(taquipneia, dispneia, tosse e dor torácica) e a\npresença de infiltrado pulmonar na radiografia de tórax descarta o diagnóstico.","B":"Na anemia falciforme, a crise aguda de sequestro esplênico pode ocorrer mais frequentemente\napós os 6 anos de idade.","C":"Nos pacientes com doença falciforme e osteomielite, o patógeno mais comum é a Salmonella.","D":"No paciente com doença falciforme, a principal causa de aplasia medular eritrocítica é a infecção\npelo Haemophilus, que acomete principalmente\ncrianças na faixa etária de 4 a 10 anos, por seu\ntropismo pelas células precursoras eritropoiéticas."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-212914","number":"212914","sourceNumber":"212914","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação às anemias hemolíticas, todas as afirmativas abaixo estão corretas, exceto:","options":{"A":"Esferocitose hereditária: o diagnóstico baseia-se na anemia crônica, reticulocitose esferocitose\ne\ncurva de fragilidade osmótica diminuída.","B":"Anemia falciforme: predisposição à infecção por bactérias capsuladas.","C":"Deficiência de glicose-6-fosfato-desidrogenase: é comum a história de episódio de hemólise com\nperíodos de remissão, em crianças do sexo masculino.","D":"Talassemia maior: anemia importante, deformidades óssea e dentária podem estar presentes.","E":"Anemia hemolítica autoimune: autoanticorpos se ligam à superfície das hemácias, ocasionando\nsua destruição via sistema complemento ou sistema\nreticuloendotelial."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-196790","number":"196790","sourceNumber":"196790","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Jerônimo é morador da região das montanhas capixabas têm ascendentes italianos,\ntinha manifestações de anemia e foi diagnosticado\ncom Talassemia, sabe-se que há dois tipos; Alfa\n\n(a) e Beta (ß). Marque a CORRETA sobre quais indivíduos / populações são afetados pela\nTalassemia Beta:","options":{"A":"Europeus (Central)","B":"Europeus (Nórdico)","C":"Asiáticos (Sudeste)","D":"Africanos (Costa Atlântica)"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-215136","number":"215136","sourceNumber":"215136","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Menino de 4 anos tem diagnóstico de anemia falciforme e é levado ao pronto socorro\ncom quadro agudo de febre e queda importante\ndos níveis de hemoglobina, sendo caracterizado\ncomo episódio aplásico. O agente viral mais frequentemente envolvido nesses episódios é o:","options":{"A":"Citomegalovírus.","B":"Vírus herpes simples.","C":"Vírus Epstein-Baar.","D":"Hantavírus.","E":"Parvovírus B 19."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-187463","number":"187463","sourceNumber":"187463","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Numa consulta em Unidade Ambulatorial Dra Fergie atende Dona Julita, 75 anos, que\ntraz exames laboratoriais numa consulta de\nrevisão. Olhando detidamente o resultado hemograma\na médica faz o seguinte comentário: ?É Dona Julita fique tranquila, no geral está tudo bem, mas... a\nsenhora está com a causa mais frequente de anemia?. Marque a opção CORRETA que indica qual\nseria este tipo mais comum de anemia a que se refere o Drª Fergie:","options":{"A":"Anemia por hiperesplenismo.","B":"Anemia por insuficiência medular.","C":"Anemia megaloblástica.","D":"Anemia ferropriva.","E":"Anemia falciforme."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-172557","number":"172557","sourceNumber":"172557","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança de 1 ano e 4 meses, em consulta de rotina, sem queixas ou alterações no\nexame físico e crescimento/desenvolvimento,\napresenta o seguinte exame laboratorial\n(Hemograma): Ht: 34,5% (VR: 36%); Hb: 11,5 g/dL (VR: 12 g/dL); RDW: 16% (VR: 11,5 a 14,5%);\n\nreticulócitos: 0,4% (VR: 0,5 a 1,5%); hipocromia e microcitose. Nesse caso:","options":{"A":"A terapia de escolha é a reposição de Fe elementar, por via oral; sugestivo de anemia por\ncarência de ferro.","B":"A terapia de escolha é a cobalamina parenteral (IM); sugestivo de anemia por deficiência de\nvitamina B12.","C":"Encaminhar para acompanhamento com hematologista; sugestivo de anemia hemolítica.","D":"A terapia de escolha é Fe parenteral; sugestivo de sangramento acentuado ou de difícil controle."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-187490","number":"187490","sourceNumber":"187490","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em todas as alternativas abaixo temos achados sugestivos de anemia ferropriva exceto\nna alternativa:","options":{"A":"Pica.","B":"Coiloniquia.","C":"Baixa resposta dos reticulócitos.","D":"Diminuição da capacidade total de ligação do ferro.","E":"Diminuição da ferritina sérica."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-162533","number":"162533","sourceNumber":"162533","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considera-se esplenomegalia de grande monta quando o baço se estende a mais de 8\ncentímetros do rebordo costal, ultrapassa a linha umbilical ou atinge peso superior a 1 kg. Qual das\nseguintes alternativas não representa uma causa frequente desse achado clínico?","options":{"A":"Anemia hemolítica autoimune","B":"Leucemia linfocítica crônica","C":"Cirrose com hipertensão porta","D":"Linfoma de zona marginal","E":"Mielofibrose com metaplasia mieloide"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-162558","number":"162558","sourceNumber":"162558","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual é a principal hipótese diagnóstica para a tríade: trombose de veia porta,\npancitopenia e anemia hemolítica?","options":{"A":"Púrpura trombocitopênica idiopática.","B":"Leucemia promielocítica aguda.","C":"Hemoglobinúria paroxística noturna.","D":"Púrpura trombocitopênica trombótica.","E":"Síndrome hemolítico-urêmica."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-155367","number":"155367","sourceNumber":"155367","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente com doença falciforme em crise vaso-oclusiva álgica muito intensa (nota 9 em\n10 na escala analógica). Das condutas a\nseguir, assinale a mais apropriada nesse caso - com\nmaiores evidências de qualidade na literatura médica.","options":{"A":"Ofertar morfina por via parenteral o mais rápido possível.","B":"Mesmo com dor muito intensa, sempre iniciar com analgesia simples (dipirona ou paracetamol),\nsubindo gradativamente a escada de analgesia\nproposta pela OMS.","C":"A transfusão de hemácias deve ser feita, independente da Hb ou do hematócrito do paciente, já\nque reduz a intensidade e a duração da crise álgica.","D":"Hiper-hidratar por via venosa, sem parcimônia, mesmo pacientes euvolêmicos, uma vez que isso\nauxilia na melhora da vaso-oclusão.","E":"A oxigenoterapia é habitualmente contraindicada, já que pode causar vasoconstrição."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-155443","number":"155443","sourceNumber":"155443","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma mulher de 76 anos apresenta-se no setor de emergência com piora na falta de ar.\nEla tem uma história médica pregressa de Diabetes Mellitus e estenose aórtica. O exame físico\nidentifica palidez, além de um sopro compatível com estenose aórtica. A concentração de\nhemoglobina dessa paciente é de 7,4 g/dL. Considerando riscos da paciente de apresentar tanto\nanemia por deficiência de ferro como anemia inflamatória, quais dos valores laboratoriais a seguir\nserão mais úteis no diagnóstico da causa de sua anemia?","options":{"A":"Capacidade Total de Ligação ao ferro e Nível de Ferro.","B":"Saturação de Transferrina e Nível de Ferritina.","C":"Nível de Ferritina e Capacidade Total de Ligação ao ferro.","D":"Nível de Ferro e Saturação de Transferrina.","E":"Nível de Ferro e Nível de Ferritina."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-148599","number":"148599","sourceNumber":"148599","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança de quatro anos é trazida, pela mãe, a uma consulta de puericultura com palidez\ncutânea e fadiga. Foi solicitado hemograma, que apresentou hemoglobina de 8,3 g/dl. Na\ninvestigação da causa da anemia, são importantes alguns conhecimentos. Qual das afirmativas\nabaixo está ERRADA?","options":{"A":"A anemia fisiológica infantil ocorre do 2º ao 4º mês de vida. A anemia em criança com 4 anos de\nidade sempre deve ser pesquisada.","B":"A anemia por deficiência de ferro é hipocrômica e microcítica por reticulocitose.","C":"A anemia por deficiência de vitamina B12 é macrocítica.","D":"A anemia perniciosa é macrocítica.","E":"A anemia sideroblástica apresenta hipocromia com ferro sérico alto."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-155398","number":"155398","sourceNumber":"155398","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual o melhor exame para avaliar as reservas corporais de ferro?","options":{"A":"Concentração da hemoglobina corpuscular média.","B":"Transferrina sérica.","C":"Volume corpuscular médio.","D":"Protoporfirina eritrocitária livre.","E":"Ferritina sérica."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-155427","number":"155427","sourceNumber":"155427","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Pré-escolar de 2 anos e 10 meses, portador de anemia falciforme, é levado para\natendimento médico em um serviço de emergência\ncom queixa de dor abdominal, irritabilidade e\npalidez. Ao exame físico apresentava-se hipocorado (2+/4+), com temperatura axilar de 38°C e\nbaço palpável a 6 cm do rebordo costal esquerdo. Foi solicitado hemograma, que revelou\nleucocitose, Hb= 6 g/dl e reticulocitose. Assinale a opção que indica a provável hipótese\ndiagnóstica\npara o caso descrito:","options":{"A":"Crise aplástica.","B":"Sequestro esplênico.","C":"Cisto de colédoco.","D":"Pancreatite aguda.","E":"Síndrome torácica aguda."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-126914","number":"126914","sourceNumber":"126914","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre a macrocitose, assinale a alternativa CORRETA.","options":{"A":"A causa mais comum de macrocitose é a deficiência de vitamina B12.","B":"O uso de medicamentos como hidroxiuréia, a gestação e o hipotireoidismo podem levar à\nmacrocitose.","C":"A hemoglobinúria paroxística noturna caracteriza-se por tendência à trombose e predomínio de\nhemólise extravascular.","D":"Apesar de ser uma eritroenzimopatia rara a deficiência de G6PD causa sintomas de anemia\nhemolítica grave em mais de 90% dos pacientes."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-131633","number":"131633","sourceNumber":"131633","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"São dados encontrados nos pacientes portadores de Thalassemia, exceto:","options":{"A":"Reticulocitose.","B":"Esplenomegalia.","C":"Macrocitose.","D":"Cálculos biliares.","E":"Risco de hemocromatose."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-131634","number":"131634","sourceNumber":"131634","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Esfregaço periférico de uma mulher de 40 anos revelou a presença de corpos de\nHowell ? Jolly nos eritrócitos. Dos abaixo, o mais provável é haver:","options":{"A":"Presença de hemoglobina C à eletroforese de hemoglobina.","B":"Presença concomitante de esquizócitos.","C":"Antecedente de esplenectomia.","D":"Deficiência de G6PD.","E":"Teste de Coombs positivo."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-131688","number":"131688","sourceNumber":"131688","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Escolar de 8 anos em tratamento de infecção urinária com Sulfametoxazol +\nTrimetoprim, evolui com icterícia e colúria.\nTem bom estado geral. Baço e Fígado não palpáveis. Os\nexames laboratoriais mostram queda de hemoglobina, reticulocitose e hiperbilirrubinemia indireta.\n\nQual o diagnóstico mais provável?","options":{"A":"Deficiência de Glicose-6-Fosfato-Desidrogenase.","B":"Hepatite medicamentosa.","C":"Esferocitose hereditária.","D":"Hepatite A.","E":"Síndrome de Crigler-Najjar Tipo I."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-106434","number":"106434","sourceNumber":"106434","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lara, 3 anos, tem queixas de dor em membros inferiores, principalmente após quadros\ninfecciosos. A mãe reclama que a filha tem uma anemia que nunca melhora, mesmo com uso de\nsulfato ferroso há meses. Ao exame físico: palidez, fígado a 1 cm do rebordo costal direito, baço\nnão palpável. Exames laboratoriais: Hematócrito = 23%; hemoglobina = 7,8 g/dl; reticulócitos: 6%;\nferritina: 88; hematoscopia: normocitose, normocromia, e hemácias em foice. Qual o diagnóstico\nmais provável?","options":{"A":"Anemia de Fanconi.","B":"Talassemia.","C":"Anemia falciforme.","D":"Anemia megaloblástica.","E":"Esferocitose Hereditária."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-111576","number":"111576","sourceNumber":"111576","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Menina, 4 anos de idade, tem diagnóstico de anemia falciforme (FSC), faz uso de\npenicilina oral desde os 3 meses de idade e recebeu vacinação adequada. Hoje apresenta\nadinamia, cansaço, dispneia, dor abdominal e fezes amolecidas. Ao exame está pálida, a FC é de\n150 bpm e o baço é palpável a 2 cm do RCE. A hemoglobina basal é de 9 g/dL e hoje é de 4,5\ng/dL, reticulócitos ausentes. Foi prescrito transfusão de concentrado de glóbulos e pedido:","options":{"A":"sorologia para eritrovírus.","B":"mielograma.","C":"hemocultura.","D":"dosagem de ferritina.","E":"coprocultura."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-88917","number":"88917","sourceNumber":"88917","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactente de 15 meses apresenta palidez das palmas das mãos que motivou a\nsolicitação de hemograma, cujo resultado revelou: Hgb = 7,5 g/dl, VCM = 68 ?3, RDW = 18% e\nreticulócitos corrigidos = 0,9%. São achados esperados para o caso em questão:","options":{"A":"ferritina \"menor ou igual\" 15, porcentagem de saturação em ferro da transferrina \"maior ou igual\"\n12, anisocitose e hipocromia.","B":"ferritina diminuída, porcentagem de saturação em ferro da transferrina > 16 e HCM \"menor ou\nigual\" 25 pg e anisocitose.","C":"ferritina \"menor ou igual\" 10 µg/L, porcentagem de saturação em ferro da transferrina entre 10 e\n16,\n\nanisocitose e HCM diminuído.","D":"ferritina < 10 µg/L, porcentagem de saturação em ferro da transferrina < 12, HCM diminuído e\nanisocitose.","E":"ferritina diminuída, porcentagem de saturação em ferro da transferrina \"maior ou igual\" 16, HCM\nnormal, anisocitose."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-77489","number":"77489","sourceNumber":"77489","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactente de 12 meses procura o ambulatório de pediatria do HUCAM com história de\npalidez, irritabilidade e anorexia. Não aceita alimentação (almoço e jantar). Ainda mama leite\nmaterno, que alterna com leite de vaca engrossado desde os 4 meses de idade. Não tem nenhum\nantecedente de doença ou internação. Em sua avaliação inicial:","options":{"A":"Deve-se pensar em anemia ferropriva, pois se trata de lactente em faixa etária de risco para\nesse tipo de anemia.","B":"O ferro do leite materno é muito bem absorvido e a amamentação mantida até essa idade,\nmesmo que quase exclusivamente, evita o aparecimento de anemia ferropriva.","C":"Como se trata de lactente sem nenhuma doença prévia, a possibilidade de talassemia minor\nestá afastada quando se pensa na etiologia da anemia.","D":"Não se pode afastar a possibilidade de esferocitose hereditária, já que as manifestações clínicas\nda doença só aparecem após os 4 meses de idade.","E":"A possibilidade de anemia ferropriva está afastada nessa situação clínica, especialmente se\ndurante o exame físico detectarmos esplenomegalia."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-43966","number":"43966","sourceNumber":"43966","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Ao exame neurológico de uma paciente de 45 anos com história de fraqueza muscular\ndos membros inferiores há 5 meses, constataram-se\nas seguintes alterações: paraparesia crural\nsimétrica, reflexos miotáticos profundos exaltados nos quatro membros, reflexo cutâneo-plantar em\nextensão bilateralmente, marcha parético-atáxica, apalestesia e anartrestesia nos membros\ninferiores. Considerando-se as opções terapêuticas abaixo, qual a mais apropriada para o caso?","options":{"A":"Pulsoterapia com metilprednisolona.","B":"Descompressão cirúrgica.","C":"Vitamina B12 parenteral.","D":"Imunoglobulinoterapia.","E":"Praziquantel e prednisona."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-43930","number":"43930","sourceNumber":"43930","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente JCO apresenta quadro clínico compatível com abscesso esplênico. Na\ninvestigação diagnóstica, a doença hematológica que mais frequentemente causa abscesso\nesplênico é:","options":{"A":"Anemia hemolítica autoimune.","B":"Púrpura trombocitopênica idiopática.","C":"Anemia falciforme.","D":"Esferocitose hereditária.","E":"Talassemia maior."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-355627","number":"355627","sourceNumber":"355627","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma paciente de 26 anos de idade, portadora de anemia falciforme, sem seguimento\nclínico adequado, procura atendimento\nambulatorial com objetivo de retomar o acompanhamento\nrotineiro. Apresentou quatro crises álgicas de falcização, quatro episódios de pneumonias\ncomunitárias e a necessidade de dez transfusões de concentrados de hemácias nos últimos 12\nmeses. No momento, encontra-se com PA 120 mmHg x 80 mmHg, FC 100 bpm, FR 18 irpm, afebril\ne com Sat02 98%,sem queixas álgicas. A respeito deste caso clínico e das ações terapêuticas\nindicadas nesse momento para a paciente, com o intuito de redução das crises álgicas e diminuição\ndas taxas de internações, assinale a alternativa correta:","options":{"A":"avaliação sorológica de doenças transmissiveis pelo sangue e vacinação para pneumococo e\nmeningococo","B":"início de hidroxiureia com objetivo de aumento dos níveis de hemoglobina fetal e redução do\nnúmero de crises de falcização, revisão do calendário vacinal para avaliação de cobertura de\ngermes capsulados e uso de ácido fólico","C":"realização de ecocardiograma transtorácico palpação difusa, pelo elevado risco de hipertensão\npulmonar secundária assintomática nos pacientes portadores de anemia falciforme","D":"administração de hidroxiureia com objetivo de reducão da contagem leucocitária e diminuição do\nrisco de hiperviscosidade sistêmica, principal responsável pelo risco de AVC nesses pacientes","E":"solicitação de ecodoppler transcraniano, pois, em razão do perfil de recorrência das crises, a\navaliação do fluxo sanguíneo cerebral se faz necessária com objetivo de redução do risco de\nacidente vascular cerebral (AVC)."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-363920","number":"363920","sourceNumber":"363920","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual é o principal sintoma da anemia falciforme em lactentes?","options":{"A":"Febre alta.","B":"Icterícia prolongada.","C":"Policitemia.","D":"Dor intensa."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-339765","number":"339765","sourceNumber":"339765","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Que exame complementar deve ser solicitado para elucidação etiológica de uma\npaciente de 70 anos, portadora de anemia megaloblástica por deficiência de vitamina B12 e\nqueixas dispépticas?","options":{"A":"Colonoscopia","B":"Pesquisa do anticorpo antifator intrínseco","C":"Endoscopia com biópsia da segunda porção duodenal","D":"Coombs direto","E":"Mielograma"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-342623","number":"342623","sourceNumber":"342623","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considerando-se as anemias microcíticas e hipocrômicas, assinale a alternativa\ncorreta:","options":{"A":"têm, como principais diagnósticos diferenciais, a anemia ferropriva, a talassemia e a anemia de\ndoença crônica","B":"ocorrem com aumento de reticulócitos por se trata de anemias hiperproliferativas","C":"o diagnóstico definitivo necessita de mielograma","D":"o tratamento é feito com sulfato ferroso"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-346438","number":"346438","sourceNumber":"346438","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança de 04 anos, asmática e com diagnóstico de anemia falciforme, apresenta\nquadro de exacerbação da asma, sem febre\nassociada, com radiografia de tórax sem alterações.\nNo dia seguinte, apresentou piora da dispnéia, dor torácica importante (09/10) e saturação de 92%\ncom máscara de oxigênio não reinalante a 15 l/min. Qual o provável diagnóstico? Além de\noxigenação, broncodilatador e expansão volêmica, qual a conduta mais adequada?","options":{"A":"Pneumonia. Iniciar analgésico não opióide e repetir imagem pulmonar;","B":"Pneumonia. Iniciar analgésico não opioide e não repetir imagem pulmonar;","C":"Síndrome torácica aguda. Iniciar analgésico opioide e repetir imagem pulmonar;","D":"Síndrome torácica aguda. Iniciar analgésico opioide e não repetir imagem pulmonar."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-321601","number":"321601","sourceNumber":"321601","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O tratamento para anemia ferropriva, de acordo com o consenso da Sociedade\nBrasileira de Pediatria (SBP) de 2021, consiste na administração de","options":{"A":"ferro elementar na dose de 3 a 6 mg/kg/dia por 6 meses.","B":"ferro elementar na dose de 1 a 2 mg/kg/dia por 6 meses.","C":"glicinato férrico na dose de 0,5 mg/kg/dia por até 30 dias.","D":"glicinato férrico na dose de 2 a 4 mg/kg/dia por 12 meses."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-300894","number":"300894","sourceNumber":"300894","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Malácia é o termo utilizado para gestante que tem:","options":{"A":"aversão a odores.","B":"desejo de comer substâncias não convencionais.","C":"cansaço exacerbado.","D":"aumento do desejo sexual."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-300801","number":"300801","sourceNumber":"300801","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"As vitaminas são compostos orgânicos presentes em pequenas quantidades nos\nalimentos. Não são fontes diretas de energia,\nmas desempenham papel essencial na regulação de\nprocessos metabólicos. Considerando as principais carências vitamínicas na prática clínica, alguns\nsinais e sintomas da deficiência de vitamina B9 são:","options":{"A":"Síndrome carcinoide, alcoólatras, gastrectomizados, anorexia nervosa, uso prolongado de\nIsoniazida, Pirazinamida e Cloranfenicol.","B":"Anemia megaloblástica, leucopenia, anorexia, diarreia, glossite, dermatite, acne, irritabilidade\ne\ndemência.","C":"Hipoprotrombinemia plasmática, hematúria e epistaxe.","D":"Hemólise, síndrome cerebelar, neuropatia periférica, miopatia e retinopatia."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-295360","number":"295360","sourceNumber":"295360","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 25 anos, previamente hígida, apresentou quadro de dores abdominais\nintermitentes associadas a fadiga, dispneia progressiva e palidez cutaneomucosa. Ao exame,\ndescorada moderada, com icterícia leve e baço a 3 cm do rebordo costal esquerdo. Hemograma\ncom HB: 7,5 g/dl, VCM: 105, leucócitos de 2.500/uL, plaquetas de 102.000/uL, DHL de 650 U,\nbilirrubina indireta de 2,8 TGP de 25,0. Ao ultrassom, notada esplenomegalia leve e trombose de\nveia porta. Nesse caso, a hipótese diagnóstica é:","options":{"A":"Aplasia de medula óssea.","B":"Esferocitose hereditária.","C":"Anemia megaloblástica.","D":"Hemoglobinúria paroxística noturna."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-317946","number":"317946","sourceNumber":"317946","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia da doença crônica é caracterizada por","options":{"A":"nível normal de ferro sérico.","B":"transferrina diminuída.","C":"diminuição da ferritina circulante.","D":"reservas de ferro normais ou aumentadas."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-300825","number":"300825","sourceNumber":"300825","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Na faixa etária pediátrica, a carência alimentar constitui a causa mais comum de\nanemia, particularmente nos países em\ndesenvolvimento. Quanto à anemia megaloblástica, analise\nas proposições abaixo e, em seguida, assinale a alternativa CORRETA: I. A anemia megaloblástica\né uma forma de anemia macrocítica que ocorre por defeito no metabolismo do ácido nucleico e\nconsequente defeito na divisão celular, com desequilíbrio entre núcleo e citoplasma. II. A anemia\nmegaloblástica é causada por deficiência de vitamina B12 e/ou ácido fólico, mas também pode ser\ndevido a medicações que interferem na síntese de DNA. III. A anemia megaloblástica é provocada\npela deficiência de ferro no organismo. Acarreta prejuízos em curto e longo prazos no\ndesenvolvimento neuropsicomotor e na aprendizagem, além de comprometimento na resposta do\nsistema imunológico.","options":{"A":"Somente I está correta.","B":"Somente I e II estão corretas.","C":"Somente II e III estão corretas.","D":"I, II e III estão corretas."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-300941","number":"300941","sourceNumber":"300941","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um paciente de 13 anos de idade, portador de anemia falciforme está apresentando\npriapismo há 3 horas, de modo contínuo, qual\ndas alternativas abaixo apresenta a conduta inicial\nmais adequada neste caso?","options":{"A":"Solicitar avaliação do urologista para punção do corpo cavernoso por conta do risco de\ndisfunção erétil no priapismo prolongado.","B":"Solicitar ao paciente que esvazie a bexiga, estimular hidratação intensa (via oral e parenteral,\nse\nnecessário), prescrever analgesia de horário com morfina, associada a analgésicos comuns e pedir\navaliação da urologia se a resposta ao tratamento clínico não for satisfatória.","C":"Estimular diurese, indicar suplementação de oxigênio e exsanguineotransfusão, prescrever\nanalgesia com morfina e analgésicos comuns e solicitar avaliação do urologista.","D":"Indicar suplementação de O2, transfusão de concentrado de hemácias e avaliação do urologista."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-313234","number":"313234","sourceNumber":"313234","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um escolar de 9 anos é trazido à Unidade Básica de Saúde pela mãe com queixa de\ncansaço, má aceitação alimentar e baixo rendimento escolar. A mãe refere que a criança é muito\nseletiva na aceitação alimentar. O peso e a estatura estão no percentil 10%, mas se apresenta\nhipocorada (++/4+), com FC = 110bpm e FR = 26irpm, sem outras alterações. Considerando essas\ninformações, a alteração mais provável do hemograma é:","options":{"A":"anemia hipocrômica, microcítica com anisocitose","B":"anemia normocrômica, normocítica sem anisocitose","C":"anemia hipocrômica, normocítica sem anisocitose","D":"anemia normocrômica, macrocítica com anisocitose"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-313235","number":"313235","sourceNumber":"313235","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma paciente de 9 anos, com anemia falciforme, chegou ao pronto-socorro com história\nde hemiparesia à esquerda há 2 horas. Ao exame\nfísico, encontrava-se consciente, orientada e\nnormotensa. O hemograma mostrou hemoglobina de 8,5g/dL. A tomografia de crânio não mostrou\nanormalidades. Com base nesse caso hipotético a conduta mais adequada seria:","options":{"A":"transfusão simples de concentrado de hemácias filtradas, 15mL/kg","B":"manter apenas observação clínica com hidratação e analgesia","C":"aguardar ressonância magnética de encéfalo","D":"realizar transfusão de troca com hemácias filtradas e fenotipadas"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-316390","number":"316390","sourceNumber":"316390","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre a anemia ferropriva na pediatria, leia as afirmações abaixo e assinale a\nalternativa correta: I - O estágio 1 é\nconhecido como depleção de ferro, em que há redução nos\ndepósitos de ferro no fígado, baço e medula óssea. O principal exame que avalia as reservas de\nferro é a ferritina. II - O estágio 2 cursa com deficiência de ferro e são utilizados para o\ndiagnóstico\no ferro sério que encontra-se baixo, aumento da capacidade total de ligação da transferrina e da\nsaturação de transferrina. III - O estágio 3 é a anemia ferropriva; neste estágio há redução de\nhemoglobina e hematócrito, podendo também haver leucopenia, plaquetose e alteração de\nreticulócitos. IV - O tratamento da anemia ferropriva é realizado por 2 a 6 meses, no mínimo 8\nsemanas. Podme ser usados sais ferrosos ou sais férricos, sendo que estes últimos têm baixo\ncusto e estão relacionados com mais sintomas gastrointestinais, levando a uma má adesão.","options":{"A":"Corretas: I, II e III","B":"Corretas: I, III e IV","C":"Incorretas: II e III","D":"Incorretas: II e IV"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-277401","number":"277401","sourceNumber":"277401","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considerando os dados a seguir, referentes à anemia em adultos, relacione os tipos de\nanemia e as causas: Tipos de anemia: I - Microcítica II - Normocítica III - Macrocítica Causas: ( )\nDoenças crônicas ( ) Deficiência de ferro ( ) Deficiência de vitamina B12 ( ) Alcoolismo ( )\nTalassemias A sequência correta é:","options":{"A":"II, I, III, III, I","B":"I, I, III, II, III","C":"I, II, II, I, III","D":"II, I, II, I, I"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-285065","number":"285065","sourceNumber":"285065","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação às anemias hipocrômicas e microcíticas:","options":{"A":"A causa mais comum é deficiência de vitamina B12.","B":"Devem ser tratadas com sulfato ferroso.","C":"Devem ser investigadas com mielograma.","D":"Os principais diagnósticos diferenciais são anemia ferropriva, talassemia e anemia de doença\ncrônica","E":"Os reticulócitos geralmente estão aumentados por se tratar de anemia hiperproliferativa"},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-281813","number":"281813","sourceNumber":"281813","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 32 anos, com lúpus eritematoso sistêmico, dá entrada no pronto-socorro\ncom intensa dispneia e dosagem de hemoglobina\nde 3,1 g/dL. O teste de Coombs direto é reagente\n(4+/4+); é solicitada a transfusão de dois concentrados de hemácias, porém o serviço de\nhemoterapia informa que todos os concentrados de hemácias cruzados foram incompatíveis e a\npesquisa de anticorpo irregular foi positiva. Também não foi possível definir o grupo sanguíneo\nABO e Rh do paciente. A conduta recomendada para este paciente é:","options":{"A":"iniciar corticoide e suspender a transfusão.","B":"realizar uma plasmaférese de urgência para retirar o autoanticorpo.","C":"transfundir, lentamente, concentrado de hemácias O Rh negativo, mesmo incompatível.","D":"continuar cruzando bolsas de concentrados de hemácias até encontrar alguma que seja\ncompatível."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-274761","number":"274761","sourceNumber":"274761","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre anemia ferropriva, afirma-se:","options":{"A":"observa-se aumento do número de linfócitos e risco aumentado de intoxicação por cromo.","B":"não se justifica tratamento empírico antes de investigar possíveis causas de sangramento.","C":"os sais de ferro devem ser administrados com as refeições para facilitar a absorção duodenal.","D":"deve-se pesquisar doença celíaca ou infecção por H. pylori quando não houver resposta ao\ntratamento."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-273156","number":"273156","sourceNumber":"273156","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em um exame, quando detectada a alteração no número de eritrócitos e na quantidade\nde hemoglobinas, pode-se identificar como\nconsequência final o quadro de:","options":{"A":"Anorexia.","B":"Hipóxia tecidular.","C":"Isquemia cerebral.","D":"Anoxia cerebral."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-273157","number":"273157","sourceNumber":"273157","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"É função principal do eritrócito:","options":{"A":"Transporte do surfactante.","B":"Transporte do hematócrito.","C":"Transporte da hemoglobina.","D":"Transporte apenas do grupo granulócito."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-265877","number":"265877","sourceNumber":"265877","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considerando que o oxigênio se liga à porção heme da molécula de hemoglobina,\nassinale a alternativa CORRETA:","options":{"A":"Cada molécula de hemoglobina carrega quatro moléculas de oxigênio.","B":"Cada molécula de meta hemoglobina carrega oito moléculas de oxigênio.","C":"A hemoglobina oxigenada (oxihemoglobina) carrega seis moléculas de oxigênio.","D":"A desoxi-hemoglobina carrega duas moléculas de oxigênio."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-277469","number":"277469","sourceNumber":"277469","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma adolescente de 13 anos é portadora de anemia falciforme (Hb SS). Refere que há\n2 meses apresenta náuseas, vômitos\nesporádicos e dor em cólica no quadrante superior direito do\nabdome, com piora progressiva. Nega sintomas respiratórios. Qual é o exame subsidiário que tem\nmelhor capacidade diagnóstica?","options":{"A":"Hbs Ag","B":"EAS e urocultura","C":"USG","D":"Radiografia de tórax"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-273211","number":"273211","sourceNumber":"273211","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considerando a dimensão étnico-racial dos agravos à saúde, a anemia falciforme é\numa doença geneticamente transmitida,\ntorneada de tensões e desafios. Considerando a anemia\nfalciforme, analise as proposições abaixo e, em seguida, assinale a alternativa que as classificam\nem V (verdadeira) ou F (falsa) de forma respectivamente CORRETA: I. A origem dos genes\nresponsáveis pela anemia falciforme é africana e esses genes são distribuídos largamente na\npopulação da América Latina devido às altas taxas de miscigenação. II. Como os genes\nresponsáveis pela anemia falciforme não são acoplados aos genes responsáveis pela coloração da\npele, traços faciais ou tipos de cabelo, não podem ser restritos à população brasileira, definida\nsocialmente como ?negra? ou ?parda?. III. A associação feita entre a ?raça negra? e a anemia\nfalciforme tem o efeito pragmático de naturalizar aquilo que não é natural: ?a raça negra?.","options":{"A":"V, F, V.","B":"F, V, F.","C":"V, F, F.","D":"F, V, V."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-254209","number":"254209","sourceNumber":"254209","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente 25 anos, sexo feminino, assintomática , encaminhada para hematologista por\nalterações em exames pré-operatórios de abdominoplastia. O hematologista completou a\ninvestigação diagnóstica com os achados descritos abaixo. Hemograma: Hb 10mg/dl, VCM 25pg,\nRDC 20%; Eletroforese de Hemoglobina: Hemoglobina A1 - 93%; Hemoglobina A2 - 68% e\nHemoglobina Fetal - 0,2% (imagem ao lado); Valores de referência; Hemograma: Hb 13.5-19.6g/dl;\nVCM 77-101FI; HCM 28-33 pg; RDW 11.5-14.5; Eletroforese de Hemoglobina: Hemoglobina A1 -\n\n>= 96,8%; Hemoglobina A2 - entre 2,2 e 3,2% e Hemoglobina Fetal - <0,5%. Baseado apenas nos\nresultados acima descritos, é possível firmar o diagnóstico de:","options":{"A":"Beta talassemia maior.","B":"Beta talassemia menor.","C":"Alfa talassemia.","D":"Anemia ferropriva."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":["question_bank/media/medcurso/medcurso-hemato-hem-1/254209.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-248906","number":"248906","sourceNumber":"248906","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um paciente de 88 anos, portador de doença arterial obstrutiva periférica em uso de\nantiagregantes plaquetários, vem apresentando quadro de astenia e cansaço, associado a palidez\ncutânea. Apresenta Hb = 7,1g/dL, com VCM = 72 e HCM = 22. Por se tratar de uma anemia\nhipocrômica e microcítica, aventou-se o diagnóstico de anemia ferropriva. Nesse caso, podemos\nafirmar que:","options":{"A":"a ferritina sérica nos casos de anemia ferropriva pode estar alta, principalmente em casos de\nsangramento gastrintestinal crônico","B":"a transfusão sanguínea é recomendada, após solicitação do perfil de ferro, principalmente\ndevido aos sintomas","C":"não será possível manter a hemoglobina elevada se os níveis de ferro sérico estiverem normais\ne a ferritina estiver baixa","D":"o paciente tem indicação apenas de reposição de ferro para tratamento de sua anemia, sem\nnecessidade de transfusão sanguínea"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-248907","number":"248907","sourceNumber":"248907","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considerando os dados a seguir, referentes à anemia em adultos, relacione os tipos de\nanemia e as causas: Tipos de anemia: I - Microcítica; II - Normocítica; III - Macrocítica; Causas:\n( )\nDoenças crônicas; ( ) Deficiência de ferro; ( ) Deficiência de vitamina B12; ( ) Alcoolismo; ( )\nTalassemias. A sequência correta é:","options":{"A":"II, I, III, III, I","B":"I, I, III, II, III","C":"I, II, II, I, III","D":"II, I, II, I, I"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-229824","number":"229824","sourceNumber":"229824","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O tipo mais frequente de anemia carencial na criança ocorre pela deficiência de ferro.\nNa investigação laboratorial, qual a alteração que\nocorre inicialmente na anemia por deficiência de\nferro?","options":{"A":"Ferritina sérica diminuída.","B":"Ferro sérico diminuído.","C":"Hemoglobina globular média diminuída.","D":"Hematócrito diminuído."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-241699","number":"241699","sourceNumber":"241699","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Na doença falciforme, crises de anemia com baixa contagem de reticulócitos são\ncausadas, principalmente, por:","options":{"A":"deficiência de vitamina B12.","B":"deficiência de folato.","C":"infecção por parvovírus B19.","D":"fenômenos de vasoclusão.","E":"hemólise grave."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-249852","number":"249852","sourceNumber":"249852","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente do sexo feminino, de 51 anos, queixa-se de cansaço e fraqueza há meses. O\nhemograma demonstra hemoglobina de 9.5 g/dL, hematócrito de 28.1%, VCM de 134 fL associado\na reticulócitos baixos. O hematologista faz um esfregaço de sangue periférico e observa\npolimorfonucleados hipersegmentados com cerca de cinco a seis segmentações. O exame que\nmais contribuiria para o diagnóstico correto seria:","options":{"A":"dosagem de B12 e folato.","B":"biópsia da medula óssea.","C":"ferritina sérica.","D":"eletroforese de hemoglobina."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-246534","number":"246534","sourceNumber":"246534","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre as anemias, julgue os seguintes itens. I. Na anemia magaloblástica por\ndeficiência de vitamina B12, observa-se\ndefeito da maturação nuclear. II. Nas anemias carenciais\npor deficiência de ferro, o índice de anisiocitose encontra-se diminuído. III. Nas anemias\nhemolíticas\nautoimunes, pode-se observar aumento do índice de reticulócitos. Pode-se afirmar que apenas:","options":{"A":"o item I está certo.","B":"o item II está certo.","C":"o item III está certo.","D":"os itens I e II estão certos.","E":"os itens I e III estão certos."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-252749","number":"252749","sourceNumber":"252749","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à anemia falciforme, marque a alternativa INCORRETA:","options":{"A":"A presença de neutrofilia crônica, história de sequestro esplênico, aumenta a morbidade e reduz\na sobrevida.","B":"Com frequência os pacientes têm perda da função esplênica, o que aumenta a suscetibilidade\npara infecções, principalmente para o pneumococo.","C":"A crise do sequestro esplênico ocorre por obstrução arterial aguda do baço, causando isquemia\ne atrofia do baço, assim como dor súbita no\nhipocôndrio direito.","D":"As crises álgicas devem ser tratadas com hidratação vigorosa, investigação de fatores\ndesencadeantes, como infecções e analgesia agressiva."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-232231","number":"232231","sourceNumber":"232231","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher de 55 anos com Artrite Reumatoide (AR) foi\nencaminhada ao ambulatório de hematologia\npor causa de anemia. Ela tem AR há cerca de cinco\nanos e seu nível de hemoglobina vem diminuindo gradualmente de 14 g/dl para 9,5 g/dl. São\nsolicitados exames e observam-se os seguintes parâmetros: hemoglobina de 9,6 g/dl, leucócitos de\n\n8.500 com diferencial normal, plaquetas de 450 mil, ferritina de 240 ng/ml, saturação da\ntransferrina\nde 14%, proteína C reativa de 50 mg/ml. Nesse\ncaso, qual é o mecanismo fisiopatológico causador\nda anemia?","options":{"A":"O aumento da hepcidina induzida por citocinas aumentou a ferroportina e reduziu a absorção de\nferro e saturação da transferrina.","B":"A eritropoiese ineficaz aumentou a degradação de glóbulos vermelhos, a diminuição da\nhepcidina, a diminuição da ferroportina e a saturação da transferrina.","C":"O aumento da hepcidina induzida por citocinas diminuiu a ferroportina, reduziu a absorção de\nferro e a saturação da transferrina.","D":"O aumento da hepcidina induzida por citocinas diminuiu a ferroportina e aumentou a absorção\nde ferro."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-252750","number":"252750","sourceNumber":"252750","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O distúrbio que se caracteriza por deficiência do fator intrínseco por atrofia gástrica\nassociado à presença de anticorpos contra a célula parietal é a(o):","options":{"A":"Anemia hemolítica autoimune.","B":"Anemia perniciosa.","C":"Lúpus eritematoso sistêmico.","D":"Policitemia Vera."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-252751","number":"252751","sourceNumber":"252751","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O distúrbio que se caracteriza por deficiência do fator intrínseco por atrofia gástrica\nassociado à presença de anticorpos contra a célula parietal causa a deficiência de:","options":{"A":"Vitamina D.","B":"Vitamina B12.","C":"Vitamina A.","D":"Vitamina B1."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-249491","number":"249491","sourceNumber":"249491","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"No paciente que apresenta diagnóstico de anemia falciforme pelo teste do pezinho, o\nresultado encontrado é:","options":{"A":"HgFSC","B":"HgFSA","C":"HgFA","D":"HgFS"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-249493","number":"249493","sourceNumber":"249493","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Quais das alterações bioquímicas apresentadas abaixo estão relacionadas com a\npresença de hemólise?","options":{"A":"LDH, TGO, bilirrubina, haptoglobina.","B":"TGO, LDH, fosfatase alcalina, amilase.","C":"Haptoglobina, bilirrubina, ferritina, fosfatase alcalina.","D":"Ferritina, TGO, ácido úrico, LDH."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-229871","number":"229871","sourceNumber":"229871","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente com astenia em investigação com hematologista, traz consigo exames que\nrevelam: Hb 10mg/dl, VCM 65fL, HCM 25pg, RDW 20%, ácido fólico 5.0ng/ml; vitamina B12\n200pg/ml, Ferro 30mcg/dl, IST 15% e Ferritina 18ng/ml. TIBC 600mcg/dl. Reticulócito 0.1%. Valores\nde referência: Hb 13.5-19.6g/dl; VCM 77-101Fl, HCM 28-33 pg; RDW 11.5-14.5%; ácido fólico\n\n>3.37ng/ml; vitamina B12 300-900pg/ml; Ferro 50-170 mcg/dl; IST 20-50%; Ferritina 23-336ng/ml;\nTIBC 250-425mcg/dl. Reticulócito 0.5-2.1%. O provável\ndiagnóstico é anemia","options":{"A":"ferropriva.","B":"de doença crônica.","C":"Megaloblástica.","D":"hemolítica."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-234389","number":"234389","sourceNumber":"234389","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma criança de dois anos, portadora de doença falciforme, é atendida na unidade de\npronto atendimento com quadro de febre iniciada há 36 horas, sem outros sintomas associados. O\nexame físico não apresenta alterações além da temperatura de 38,9ºC. A conduta será:","options":{"A":"Acompanhamento ambulatorial e retorno em caso de persistência da febre após 48 a 72 horas\nou antes, se houver piora clínica.","B":"Realização dos seguintes exames complementares: hemograma, hemocultura, urocultura e\nradiografia de tórax; os resultados definirão o plano terapêutico.","C":"Admissão hospitalar e início de antibioticoterapia parenteral, mesmo antes dos resultados dos\nexames laboratoriais.","D":"Prescrição de oseltamivir, pois o exame físico sem alterações sugere doença viral, e esses\npacientes são grupo de risco para influenza grave."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-210536","number":"210536","sourceNumber":"210536","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre as complicações da anemia falciforme, julgue os itens a seguir. l. A crise\n\nvaso-oclusiva pode apresentar derrame articular e a artrocentese deve ser realizada de rotina. ll.\nDor lombar de forte intensidade pode indicar\ninfarto renal que leva à hematúria macroscópica e\ninsuficiência renal. lll. A síndrome torácica aguda é a forma mais comum de complicação pulmonar\nnesses pacientes. lV. Na faixa etária de até 20 anos, o AVC hemorrágico é a principal manifestação\nneurológica. Pode-se afirmar que:","options":{"A":"apenas os itens l, ll e lll estão certos.","B":"apenas os itens ll e lll estão certos.","C":"apenas os itens ll e lV estão certos.","D":"apenas os itens lll e lV estão certos.","E":"apenas os itens l, lll e lV estão certos."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-201946","number":"201946","sourceNumber":"201946","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em crianças com anemia falciforme:","options":{"A":"as crises de dor geralmene respodem ao uso de hidratação oral e antiinflamatório não hormonal","B":"a icterícia é decorrente da predisposição à hepatite","C":"deve-se fazer profilaxia com penicilina V oral, após o 1º quadro de pneumonia","D":"com síndrome torácica aguda apresentando dispneia com taquipneia acentuada, é indicada\ntransfusão simples ou troca parcial de sangue","E":"o sequestro esplênico geralmente tem remissão espontânea, podendo ser de acompanhamento\ndomiciliar"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-214939","number":"214939","sourceNumber":"214939","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considerando os dados a seguir, referentes à anemia em adultos, relacione os tipos de\nanemia e as causas: Tipos de anemia: I - Microcítica; II - Normocítica; III - Macrocítica. Causas:\n( )\nDoenças crônicas; ( ) Deficiência de ferro; ( ) Deficiência de vitamina B12; ( ) Alcoolismo; ( )\nTalassemias. A sequência correta é:","options":{"A":"II, I, III, III, I","B":"I, I, III, II, III","C":"I, II, II, I, III","D":"II, I, II, I, I"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-201739","number":"201739","sourceNumber":"201739","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A gastrite atrófica autoimune está mais frequentemente associada:","options":{"A":"À litíase biliar.","B":"À insuficiência biliopancreática.","C":"Ao lúpus eritematoso sistémico.","D":"À anemia perniciosa."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-216468","number":"216468","sourceNumber":"216468","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"G.F., 67 anos, fez um hemograma que mostrou anemia com aumento importante do\nvolume corpuscular médio. Para melhor investigação do caso, deve-se fazer a dosagem da(o):","options":{"A":"Ferritina.","B":"Cobalamina.","C":"Zinco.","D":"Tiamina."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-214185","number":"214185","sourceNumber":"214185","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia é um marcador clínico importante dos pacientes portadores da doença\nfalciforme, sendo, a transfusão de concentrados\nde hemácias, a intervenção terapêutica habitual\npara estes pacientes. Em relação a tal procedimento indica-se:","options":{"A":"Transfusão de concentrado de hemácias em pacientes com hemoglobina menor que 7,0 g/dL\nobjetivando melhor qualidade de vida.","B":"Sempre que possível deve-se utilizar hemácias fenotipadas para os sistemas RH, Kidd, Kell e\nDuffy.","C":"Tratamento em casos de crises dolorosas.","D":"Em casos de priapismo não há benefícios da realização exsanguíneo transfusão."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-216653","number":"216653","sourceNumber":"216653","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 24 anos de idade, sexo feminino, foi ao ambulatório de clínica médica\ndevido a astenia intensa. Ao exame físico\napresentava mucosas hipocoradas e aumento da\nfrequência cardíaca. Exames laboratoriais mostravam aumento de VCM (acima de 120) com\nferritina normal, ferro sérico e índice de saturação de transferrina também normais. Negava\nmenstruação excessiva e episódios de sangramento. O médico assistente solicitou endoscopia\ndigestiva alta, sendo encontrada pangastrite atrófica. A principal hipótese e exame complementar a\nser solicitado são respectivamente:","options":{"A":"Anemia megaloblástica e anticorpo antimicrossomal.","B":"Talassemia e anticorpo antifator intrínseco.","C":"Anemia perniciosa e anticorpo anticélula parietal.","D":"Anemia megaloblástica anticorpo antimitocondrial."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-214112","number":"214112","sourceNumber":"214112","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre o teste do pezinho: I - deverá ser colhido, idealmente, entre o 3º e o 5º dia de\nvida. II - pacientes submetidos a\nhemotransfusão antes da coleta do teste deverão ter sua coleta\nadiada até 120 dias após a administração do último hemoconcentrado. III - doenças maternas como\nhipertireoidismo podem interferir no resultado do exame do recém-nascido. IV - após 28 dias de\nvida não se deve mais realizar a coleta do teste do pezinho, sendo então indicada seguimento\nclínico rigoroso e investigação laboratorial dos pacientes que apresentarem sintomas de alerta para\nquaisquer das doenças incluídas no programa. Assinale as afirmações corretas relacionadas ao\nteste do pezinho:","options":{"A":"I e III.","B":"I e II.","C":"II e III.","D":"II e IV."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-216456","number":"216456","sourceNumber":"216456","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual das afirmações a seguir com relação à hemoglobina fetal é verdadeira?","options":{"A":"Ela é constituída de subunidade alfa e gama.","B":"Está presente em crianças normais até a idade de 6 anos.","C":"Ela é substituída pela hemoglobina adulta por volta da trigésima oitava semana de gestação.","D":"Ela tem menor afinidade por oxigênio que a hemoglobina adulta."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-216560","number":"216560","sourceNumber":"216560","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Os pais de uma criança recém-nascida estão muito preocupados, pois, no teste do\npezinho, houve observação de \"traço falciforme\". A fim de esclarecê-los sobre o que significa esse\nresultado de exame, as informações que devem ser repassadas aos pais sobre a doença, são:","options":{"A":"A presença de traço falciforme não predispõe a criança às complicações observadas na doença\nfalciforme homozigótica, como a síndrome torácica aguda.","B":"A doença é de transmissão autossômica dominante, portanto, basta um dos pais apresentarem\no traço para a ocorrência da anemia falciforme\nem seus filhos.","C":"A anemia falciforme se desenvolve em 60% dos pacientes portadores do traço falciforme,\nindependentemente de meninos ou meninas.","D":"A expectativa de vida para pacientes com traço falciforme é de 40 anos para meninos e 50 anos\npara meninas."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-178808","number":"178808","sourceNumber":"178808","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação ao metabolismo do ferro na Anemia de Doença Crônica, assinale a\nalternativa correta.","options":{"A":"Ferro sérico baixo, ferritina sérica baixa, transferrina sérica baixa.","B":"Ferro sérico baixo, ferritina sérica alta, transferrina sérica baixa.","C":"Ferro sérico normal, ferritina sérica baixa, transferrina sérica normal.","D":"Ferro sérico normal, ferritina sérica baixa, transferrina sérica baixa.","E":"Ferro sérico alto, ferritina sérica alta, transferrina sérica baixa."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-185203","number":"185203","sourceNumber":"185203","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 24 anos foi encaminhada ao ambulatório de hematologia para investigação\nde anemia. Os exames solicitados pelo médico da\nfamília revelaram hiperbilirrubinemia indireta,\nDHL aumentado e COOMBS negativo. O hemograma apresentava hemoglobina = 9,8mg/dL,\nhematócrito 30%, CHCM elevado, VCM normal, e reticulocitose. A principal hipótese diagnóstica é:","options":{"A":"esferocitose","B":"alcoolismo","C":"anemia ferropriva","D":"anemia hemolítica autoimune"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-174095","number":"174095","sourceNumber":"174095","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A droga de escolha para tratamento da hemoglobinúria paroxística noturna, em sua\nforma hemolítica clássica, é a seguinte:","options":{"A":"Ciclosporina.","B":"Rituximabe.","C":"Eculizumabe.","D":"Cetuximabe."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-186468","number":"186468","sourceNumber":"186468","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 35 anos procura atendimento referindo cansaço, principalmente aos\nesforços, tonturas, mal-estar e hipermenorreia.\nNega outras comorbidades, nega uso de\nmedicamentos, nega gestações. Nega tabagismo e etilismo. Ao exame, paciente hipocorada\n(++/4+). Exames laboratoriais: hemoglobina: 8,5 g/dl, VCM: 65 fl, leucócitos: 7.000/mm³, plaquetas:\n230.000/mm³. A causa mais provável para a anemia da paciente é:","options":{"A":"Deficiência de ácido fólico.","B":"Anemia de doença crônica.","C":"Deficiência de ferro.","D":"Deficiência de vitamina B12."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-178787","number":"178787","sourceNumber":"178787","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Após a estabilização clínica de uma criança com anemia falciforme que apresentou\nAVC isquêmico, é realizada uma terapêutica\nespecífica para alteração dos níveis hematimétricos.\nQual é essa terapia e qual é seu objetivo?","options":{"A":"Transfusão sanguínea; aumentar a hemoglobina acima de 10 mg/dL.","B":"Transfusão sanguínea; aumentar a hemoglobina fetal acima de 70%.","C":"Exsanguíneotransfusão parcial; reduzir o nível de Hemoglobina S para menos de 30%.","D":"Exsanguíneotransfusão parcial; reduzir o nível de Hemoglobina S para menos de 60%.","E":"Transfusão sanguínea; aumentar a hemoglobina acima de 12 mg/dL."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-178834","number":"178834","sourceNumber":"178834","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à anemia ferropriva em crianças, considere os seguintes fatores. I. Aumento\nda contagem de reticulócitos ao final da\nprimeira semana de tratamento.; II. Aumento de 1 g/dl na\nhemoglobina após 1 a 2 meses.; III. Aumento da contagem de 3% no hematócrito após 1 a 2\nmeses. Quanto à análise da eficácia do tratamento, está correto o que se apresenta em:","options":{"A":"I, somente.","B":"II, somente.","C":"III, somente.","D":"I e III, somente.","E":"todas."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-186433","number":"186433","sourceNumber":"186433","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança de três anos, portador de anemia falciforme, apresentando dor abdominal,\npalidez e prostração. Exame físico: Tax. =\n38,2°C, PA = 80 x 50 mmHg, palidez cutânea 3+/4+,\nicterícia de esclera, FC = 160 bpm, FR = 44 irpm, fígado: 1 cm do RCD, baço: 5 cm do RCE. A\nhipótese diagnóstica mais provável é:","options":{"A":"Hepatite A.","B":"Crise aplástica.","C":"Colelitíase aguda.","D":"Sequestro esplênico."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-185170","number":"185170","sourceNumber":"185170","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mãe leva seu filho lactente de 7 meses para consulta de puericultura, preocupada, pois\nacha seu filho muito pálido, irritado e com pouco apetite, há cerca de 2 meses. Não apresentou\ndoenças anteriores. Foi amamentado ao seio materno até 2 meses, quando iniciou leite de vaca\npuro e retirou o leite materno. Aos 6 meses iniciou, além de leite de vaca, legumes e frutas, que é\na\nalimentação atual. Ganho pondero estatural adequado. Desenvolvimento neuropsicomotor\nadequado. Ao exame, apresenta palidez cutâneo mucosa, abdômen levemente distendido com\nbaço percutível, sem outros achados. Qual a principal hipótese diagnóstica?","options":{"A":"Anemia secundária a doença celíaca.","B":"Anemia falciforme.","C":"Anemia por deficiência de ferro.","D":"Anemia por deficiência de vitamina b12."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-186513","number":"186513","sourceNumber":"186513","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Pré-escolar, sexo feminino, 5 anos, há 6 meses em tratamento de anemia não\nresponsiva ao sulfato ferroso na dose de\n5mg/kg/dia, administrado meia hora antes do almoço e\njantar com suco de laranja. Nos antecedentes pessoais, não há nada digno de nota, recebeu\naleitamento materno exclusivo até o sexto mês de vida. O pai teve anemia recorrente na infância.\nAtualmente come adequedamente. Exame físico: paciente pálido, sem outras alterações.\n\nHemograma: Hm: 6.000.000/mm3; Hb: 10,2g/dL; Ht: 30%, VCM: 50 fL; HCM: 16pg; CHCM: 22%;\n\nRDW: 12%; morfologia da série vermelha: hipocromia e microcitose; leucometria: 8.500/mm3 (eos:\n1%, basófilos: 0%, bastões: 2%, seg: 35%,\nlinf: 60%, mon:2%) e plaquetas: 230.000/mm3;\nreticulócitos: 1,6%. Para confirmar a hipótese diagnóstica mais provável, o exame a ser solicitado\né:","options":{"A":"Ferritina.","B":"Mielograma.","C":"Eletroforese de hemoglobina.","D":"Índice de saturação da transferrina."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-186486","number":"186486","sourceNumber":"186486","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactente, 1 ano e 6 meses, vem apresentando irritabilidade e dificuldade de manter-se\nde pé há um mês. A família é vegetariana, e a\nmãe não fez pré-natal. Exames laboratoriais: Hm:\n1.460.000/mm3, Hb:5,7g/dL, Ht: 18,7%, VCM: 128fL, HCM: 38,7pg, CHCM: 30,2g/dL; leucometria:\n3.500/mm3 (eos: 2%, bastões; 3% seg: 63%, linf: 30%, mon: 2%); Plaquetas: 100.000/mm3.\n\nAnisocitose (+/4+), macrocitose (+++/4+), macroovalócitos, corpúsculos de Howel-Jolly,\nReticulócitos: 2%, LDH: 900U/L (normal: 240 a\n480U/L), bilirrubina total: 3,5mg/dL, BD: 0,7mg/dL,\nBl: 2,8mg/dL. Esse quadro não teria se instalado caso a família ingerisse habitualmente:","options":{"A":"Ovo.","B":"Sucos de fruta.","C":"Vegetais de cor verde.","D":"Castanhas."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-186503","number":"186503","sourceNumber":"186503","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em hemograma de rotina de lactente de 18 meses, foi encontrado Hb: 9,1g/dl, Ht: 28%,\nhemácias: 3.000.000/mm3, esquizócitos, micrócitos e moderada hipocromia, leucometria: normal\nsem eosinofilia. Nunca fez uso de vermífugos, pois recebe água tratada e vive em área com\nsaneamento básico. Usou irregularmente as vitaminas e o ferro profilático prescritos. Recebeu\naleitamento materno exclusivo até os seis meses, depois foi introduzida alimentação complementar\ne leite de vaca in natura. A etiopatogenia deste quadro é:","options":{"A":"Uso precoce de leite de vaca.","B":"Verminose.","C":"Ferropenia.","D":"Deficiência de folato e vitamina B12."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-157269","number":"157269","sourceNumber":"157269","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A necrose da medula óssea secundária ao infarto ósseo predispõe o paciente com\nanemia falciforme a complicações, como a\nosteomielite. O agente etiológico mais associado a essa\ncondição é:","options":{"A":"S. aureus.","B":"Klebsiella.","C":"Salmonella.","D":"S.Pneumoniae.","E":"B-streptococcus."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-154651","number":"154651","sourceNumber":"154651","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Com relação à anemia no recém-nascido, assinale a alternativa correta:","options":{"A":"ocorre pela falta de produção hepática de eritrócitos, principalmente no recém-nascido pré-termo","B":"a concentração de hemoglobina cai gradualmente, atingindo os níveis mais baixos entre a 8ª e a\n12ª semanas de vida do recém-nascido a termo","C":"ocorre devido ao reduzido volume corpuscular médico dos eritrócitos em qualquer idade\ngestacional","D":"a deficiência de ferro é um importante fator etiológico no seu desenvolvimento","E":"a hematopoese encontra-se em estado de baixo fluxo e evolução lenta, proporcional com a\nidade gestacional"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-157034","number":"157034","sourceNumber":"157034","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um pré-escolar de 3 anos é levado ao ambulatório pediátrico para consulta com queixa\nde perversão do apetite e palidez cutânea\nprogressiva. Exame físico: em estado geral regular,\npálido, apático, hidratado, afebril e taquipneico. O murmúrio vesicular é positivo, sem ruídos\nadventícios, com ritmo cardíaco regular, bulhas normofonéticas, sopro sistólico (++/++++) e FC =\n160 bpm. O hemograma revela hemoglobina = 5 g%, hematócrito = 15% e VCM = 63. A ferritina é\nde 5 mg%, e a morfologia das hemácias revela anisocitose. Com relação ao exposto, assinale a\nalternativa correta.","options":{"A":"Para a confirmação diagnóstica de anemia ferropriva, falta a dosagem de ferro sérico.","B":"O tratamento indicado é concentrado de hemácias na dose de 10 mL/kg e ferroterapia oral\ndurante 4 meses.","C":"A concentração sérica de ferritina está nos limites inferiores da normalidade, não podendo\nconfirmar o diagnóstico.","D":"O uso de concentrado de hemácias não se impõe ao tratamento, uma vez que não há sinais de\ninsuficiência cardíaca."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-150253","number":"150253","sourceNumber":"150253","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Escolar de sete anos, do sexo masculino, portador de anemia falciforme, chega ao\npronto-socorro com história de que há quatro horas sofre de cefaleia intensa, acompanhada de\ndiminuição de força muscular em membros superior e inferior esquerdos. A tomografia de crânio\nmostrou tratar-se de acidente vascular cerebral isquêmico (AVC-I). Que tratamento deverá ser feito\ncronicamente como medida preventiva de novos episódios de AVC?","options":{"A":"Intolerância à lactose.","B":"Hemorragia digestiva alta.","C":"Pancreatite aguda recidivante.","D":"Síndrome torácica aguda."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-149270","number":"149270","sourceNumber":"149270","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considere as medidas não farmacológicas de tratamento da dor em anemia falciforme a\nseguir. I. Compressas de água quente/fria; II. Distração; III. Música; IV. Relaxamento. São\nCORRETAS as medidas farmacológicas contidas em:","options":{"A":"I e II, apenas.","B":"II e III, apenas.","C":"I e IV, apenas.","D":"I, II, III e IV."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-138647","number":"138647","sourceNumber":"138647","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O agente etiológico mais frequentemente envolvido nos episódios de crises aplásicas\nde crianças com anemia falciforme é:","options":{"A":"Parvovírus B19.","B":"Citomegalovírus.","C":"Vírus Epstein-Barr.","D":"Streptococcus pneumoniae."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-137046","number":"137046","sourceNumber":"137046","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"De acordo com a Organização Mundial de Saúde (OMS), anemia é um problema de\nsaúde pública global, que afeta a capacidade\nlaborativa e a qualidade de vida de cerca de 2 bilhões\nde pessoas, sendo que a deficiência de ferro é responsável por 75% dos casos de anemia. O\nachado laboratorial esperado na anemia ferropriva é:","options":{"A":"Capacidade total de ligação do ferro à transferrina aumentada.","B":"Macrocitose.","C":"RDW diminuído.","D":"Índice de saturação da transferrina maior que 55%."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-127706","number":"127706","sourceNumber":"127706","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Quais são as duas situações clínicas mais frequentes na hemoglobinopatia SC em\nrelação à hemoglobinopatia SS homozigótica?","options":{"A":"Esplenomegalia e insuficiência cardíaca.","B":"Colelitíase e úlceras maleolares.","C":"Priapismo e osteomielite por Salmonella sp.","D":"Retinopatia e necrose de cabeça de fêmur."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-103658","number":"103658","sourceNumber":"103658","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Cálculos biliares na infância são incomuns, porém, podem ser observados em qual\nsituação?","options":{"A":"Anemia falciforme.","B":"Verminose crônica.","C":"Hepatite crônica autoimune.","D":"Fibrose cística."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-110235","number":"110235","sourceNumber":"110235","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"As anemias megaloblásticas constituem um grupo de doenças com alterações\nmorfológicas semelhantes da medula óssea e macrocitose e são decorrentes da carência de\nvitamina B12 e/ou ácido fólico. Uma causa de deficiência de ácido fólico é:","options":{"A":"Anemia perniciosa.","B":"Uso prolongado de antiácidos.","C":"Pancreatite crônica.","D":"Uso de metotrexate."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-101184","number":"101184","sourceNumber":"101184","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"As figuras A e B (VER IMAGEM) correspondem a um exame radiológico obtido de um\npaciente de 11 meses de idade que se apresentava com edema de mãos e pés, simétrico,\ndoloroso, de início súbito, afebril. A imagem B foi obtida 15 dias após a imagem A, que corresponde\nao primeiro dia do quadro descrito. O diagnóstico mais provável é:","options":{"A":"Osteomielite.","B":"Síndrome mão-pé.","C":"Doença de Kawasaki.","D":"Artrite Idiopática Juvenil (AIJ)."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":["question_bank/media/medcurso/medcurso-hemato-hem-1/101184.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-103727","number":"103727","sourceNumber":"103727","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Correlacione as colunas segundo à classificação fisiopatológica das anemias e, em\nseguida, marque a sequência CORRETA: 1. Falta de produção; 2. Alteração na maturação\neritroide e eritropoiese ineficaz; 3. Perdas hemorrágicas; 4. Excesso de destruição de eritrócitos.\n(\n\n) Agudas ou crônicas; ( ) Deficiência de ferro; ( ) Defeito na membrana do eritrócito; ( )\nAnemia aplásica congênita e adquirida.","options":{"A":"1, 2, 3 e 4.","B":"3, 2, 4 e 1.","C":"4, 3, 2 e 1.","D":"1, 4, 3 e 2."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-89975","number":"89975","sourceNumber":"89975","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"É um fator de risco para Anemia Perniciosa, exceto:","options":{"A":"Dieta vegetariana/vegana.","B":"Doença celíaca.","C":"Esôfago de Barrett.","D":"Gastrectomia.","E":"Gastrite atrófica."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-85348","number":"85348","sourceNumber":"85348","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Os exames laboratoriais de uma criança de um ano de idade evidenciaram anemia\nmicrocítica, ferro sérico normal, ferritina sérica e saturação de transferrina diminuídas. A\nprincipal\nhipótese diagnóstica é:","options":{"A":"talassemia minor.","B":"talassemia major.","C":"anemia ferropriva.","D":"anemia de doença crônica."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-86347","number":"86347","sourceNumber":"86347","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A presença de desidratação, palidez, extremidades frias, febre, prostração e dor\nabdominal associados à esplenomegalia em uma\ncriança ictérica, 04 anos de idade, e portadora de\nanemia falciforme, deve ter como principal diagnóstico:","options":{"A":"Crise aplástica.","B":"Febre tifoide.","C":"Salmonelose.","D":"Sequestro esplênico."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-84404","number":"84404","sourceNumber":"84404","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale o item abaixo que ocasiona Volume Corpuscular Médio (VCM) elevado\n(macrocitose) observado no hemograma.","options":{"A":"Leishmaniose visceral.","B":"Uso prolongado de Abatacepte.","C":"Deficiência de vitamina D3.","D":"Alcoolismo.","E":"Hipertireoidismo."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-85395","number":"85395","sourceNumber":"85395","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente do sexo masculino, com 50 anos de idade, morador de uma comunidade\nvegetariana em Pirenópolis, chega com queixa de\nperda da propiocepção e sensibilidade vibratória,\nmarcha de base alargada e dificuldade para deambular, fraqueza muscular e hiper-reflexia.\n\nApresenta, também, glossite e queilose. Questionado sobre sua alimentação, confirma que é\nvegetariano exclusivo há dez anos. Exames: anemia com macrocitose (VCM: 120 pg), anisocitose,\nmacro-ovalócitos, leucopenia e neutrófilos com núcleos hipersegmentados. Vitamina B12: 200\npg/ml (valor de referência: 200 - 900 pg/ml). Como confirmar, laboratorialmente, a deficiência de\nvitamina B12?","options":{"A":"Teste de Schilling.","B":"Aferição do nível urinário dos metabólicos acidometilmalônico e homocisteína.","C":"Anticorpo anticélula parietal ou fator intrínseco.","D":"Teste para avaliar a má absorção intestinal."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-83821","number":"83821","sourceNumber":"83821","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança que teve AVC secundário e anemia falciforme deve estar sendo tratada com:","options":{"A":"antiagregação plaquetária regular.","B":"anticoagulação regular.","C":"transfusões sanguíneas regulares.","D":"uso regular de vitamina K.","E":"uso regular de hidroxiureia."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-85356","number":"85356","sourceNumber":"85356","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Menino, 3 anos, negro, com história de doença falciforme, que iniciou-se com queixa de\nfebre e dor difusa no corpo, principalmente no terço proximal da perna esquerda. Feito diagnóstico\nde osteomielite hematogênica aguda, qual organismo é o agente mais comum dessa infecção?","options":{"A":"Pneumococos sp.","B":"Salmonella sp.","C":"E. coli.","D":"S. aureus."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-78140","number":"78140","sourceNumber":"78140","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma menina de três anos de idade, portadora de anemia falciforme, é trazida ao\npronto-socorro com história de dois dias de\nfadiga; palidez; erupção cutânea; febre de 38,2°C. O\nexame físico revelou: frequência cardíaca de 140 bpm; frequência respiratória de 24 irpm; pressão\narterial de 90 x 40 mmHg e oximetria de pulso de 99% em ar ambiente. Observada palidez\nconjuntival e palmar, sem icterícia; não havia nenhuma evidência de esplenomegalia. Havia uma\n\nerupção cutânea difusa rendilhada em seus braços, pernas e peito. Exames laboratoriais revelaram\nhemoglobina de 3,3 g/dl e contagem de reticulócitos inferior a 0,1%, contagem de glóbulos brancos\nde 17 x 103/µl e uma contagem de plaquetas de 250 x 103/µl. O agente etiológico mais provável é\no:","options":{"A":"Mycoplasma pneumoniae.","B":"Bocavírus.","C":"Adenovírus.","D":"Parvovírus."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-63232","number":"63232","sourceNumber":"63232","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"As dosagens séricas da homocisteína e do ácido metilmalônico estão AUMENTADAS\nna deficiência da vitamina:","options":{"A":"E.","B":"D.","C":"B12.","D":"B1.","E":"A."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-64579","number":"64579","sourceNumber":"64579","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia de doenças crônicas (ADC) é habitualmente leve ou moderada, e normocítica\nou microcítica. Sua etiologia é multifatorial,\nenvolvendo:","options":{"A":"baixos níveis de citocinas, como interleucinas 1 e 6.","B":"Hemólise intravascular.","C":"Hematopoese extramedular.","D":"Ferro sérico diminuído e quantidade aumentada de ferro de depósito.","E":"A diminuição da hepcidina."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-64583","number":"64583","sourceNumber":"64583","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia falciforme corresponde à homozigose para o gene ßs e:","options":{"A":"Raramente cursa com complicações clínicas.","B":"Representa a forma mais grave das síndromes falciformes.","C":"A hematúria é a anormalidade mais frequente nesta doença genética.","D":"Suas manisfestações clínicas iniciam-se no terceiro mês de vida quando diminui a expressão de\nhemoglobina fetal.","E":"Apresenta eletroforese de hemoglobina com predomínio de hemoglobina S, aumento da\nhemoglobina A2 e diminuição da hemoglobina fetal."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-61822","number":"61822","sourceNumber":"61822","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considera-se o mais forte preditor de deficiência em ferro em crianças uma baixa\nconcentração de:","options":{"A":"Ferro sérico.","B":"Hematócrito","C":"Hemoglobina do reticulócito","D":"Ferritina","E":"Transferrina"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-61826","number":"61826","sourceNumber":"61826","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Considera-se o agente infeccioso mais comum na Síndrome Torácica Aguda em\ncrianças portadoras de doença falciforme:","options":{"A":"Pneumococo","B":"H Influenza","C":"S aureus","D":"Salmonella","E":"Klebisiella"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-63231","number":"63231","sourceNumber":"63231","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Laura, 1 ano de idade, apresenta febre e dor nas mãos e pés. Ao exame físico, palidez\nde pele e mucosas, FC = 110 bpm; temperatura\n= 38,5°C, edema doloroso nas mãos e pés\nbilateralmente. Hemoglobina = 6,5 g/dl; contagem de leucócitos = 15.500/mm³ (55% linfócitos, 4%\nmonócitos, 8% bastonetes, 33% segmentados); plaquetas = 350.000/mm³. Reticulócitos = 18%. O\ndiagnóstico e a conduta adequada são, respectivamente:","options":{"A":"anemia falciforme/ iniciar antibioticoterapia, hidratação endovenosa e analgesia com morfina.","B":"anemia falciforme/ iniciar hidratação endovenosa e transfusão de concentrado de hemácias;\nevitar uso de morfina.","C":"anemia hemolítica autoimune/ iniciar antibioticoterapia, hidratação endovenosa e analgesia com\ndipirona endovenosa.","D":"artrite séptica/ iniciar antibioticoterapia e transfusão de concentrado de hemácias.","E":"osteomielite com septicemia/ iniciar antibioticoterapia e drenagem cirúrgica."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-47810","number":"47810","sourceNumber":"47810","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma idosa refere fraqueza há dois meses e apresenta esplenomegalia a 2 cm da borda\ncostal esquerda. O hemograma mostrou Hb - 9 g/dl, Leuc. - 4.200/ul (50% de neutrófilos, 42% de\nlinfócitos e <1% de monócitos) e Plaq. - 50.000/ul. O mielograma revelou medula normocelular,\ncom predomínio de eritroblastos atípicos, 20% de sideroblastos em anel de 3% de blastos. Foi\nrealizado o tratamento com vitaminas B12, B6 e ácido fólico, porém, sem resposta e com piora da\nanemia e da plaquetopenia. Nesse caso, qual é o diagnóstico?","options":{"A":"Leucemia mieloide aguda.","B":"Anemia sideroblástica.","C":"Síndrome de deleção do 5q (Síndrome do 5q-).","D":"Síndrome mielodisplásica."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-49012","number":"49012","sourceNumber":"49012","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 70 anos chega ao ambulatório queixando-se de astenia, sonolência,\npalpitações aos pequenos esforços e um\nepisódio de lipotimia. Além disso, refere alopecia e unhas\nquebradiças. Há seis meses vem apresentando alterações no hábito intestinal, ora obstipada, ora\ncom diarreia, algumas vezes com sangue nas fezes. No exame físico, foi observada palidez\ncutâneo-mucosa (+++/4+), queilite angular, glossite e unhas e cabelos quebradiços. O hemograma\ncom Hb-6,0, VCM-55, HCM-18, CHCM-25 e RDW-27; Leuc-9.300 e Plaq-720.000. Marque a\n\nalternativa correta quanto aos exames necessários para definição do diagnóstico desta paciente.","options":{"A":"Eletroforese de hemoglobinas e CEA.","B":"Perfil de ferro e colonoscopia.","C":"Dosagem sérica de vitamina B12, pesquisa de sangue oculto nas fezes e EPF.","D":"Dosagem sérica de ácido fólico, pesquisa de sangue oculto nas fezes e EPF.","E":"USG abdominal e dosagem sérica de vitamina B12."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-48232","number":"48232","sourceNumber":"48232","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O achado de reticulocitose é frequentemente associado a, exceto:","options":{"A":"Anemias hemolíticas crônicas","B":"Após hemorragias agudas","C":"No início da reposição de ferro em pacientes com anemia ferropriva","D":"Na anemia aplásica","E":"Durante o tratamento das anemias megaloblásticas"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-53635","number":"53635","sourceNumber":"53635","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Nas crianças portadoras de anemia falciforme, o agente etiológico mais comum nas\nformas graves de artrite séptica é:","options":{"A":"Streptococcus B hemolítico.","B":"Salmonella.","C":"Hemophilus influenzae","D":"Pseudomonas aeruginosa.","E":"Staphylococcus aureus."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-48278","number":"48278","sourceNumber":"48278","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia falciforme é frequente em nosso meio e caracterizada por doença hemolítica\ncrônica e grave, resultante da destruição prematura dos eritrócitos. Relativamente a esta doença,\nindique a assertiva correta:","options":{"A":"A crise dolorosa deve ser tratada com transfusão sanguínea.","B":"Quando ocorre osteomielite, a salmonella é um agente etiológico importante a ser considerado.","C":"A dactilite ocorre por isquemia de partes moles de mãos e pés em geral em crianças menores de\ndois anos.","D":"A vacina contra pneumococo deve ser feita em crianças maiores de dois anos e confere ampla\nproteção contra esse agente.","E":"A crise de sequestro é mais comum após os cinco anos de idade."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-48851","number":"48851","sourceNumber":"48851","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher de 40 anos, branca, com queixa de cansaço, fraqueza e desânimo por vários\nanos, com piora há 4 meses. Refere, também,\ndor lombar e em joelho direito de média intensidade\nem uso regular de analgésicos. Faz regime para emagrecer há pelos menos 4 anos, com\ndificuldade na manutenção da perda de peso. Refere perda de 2 kg, mucosas descoradas 1+/4+.\nHb = 10,8 g/dL; VCM = 59 fL, Hemácias = 5,25 x 106/mm³, RDW = 14 (VN = 10%-15%), leucócitos\n\n= 7.300/mm³, Neutrófilos = 4.400/mm³, plaquetas = 285.000/mm³, Reticulócitos = 1,5%. Moderada\nhipocromia, hemácias em alvo e alguns eliptócitos. O diagnóstico provável é:","options":{"A":"talassemia minor.","B":"anemia ferropriva.","C":"anemia de doença crônica.","D":"anemia sideroblástica.","E":"mielodisplasia."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-35619","number":"35619","sourceNumber":"35619","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Homem de 21 anos é internado com queixa de fraqueza nos últimos 6 meses.\nFamiliares relatam que nesse período adquiriu o\nhábito de comer gelo todos os dias. O único\nachado de exame físico é o descoramento de mucosas. O hemograma mostra hemoglobina de 7,9\ng/dl, 8.500 leucócitos/mm³ sendo 40% neutrófilos, 40% linfócitos e 20% eosinófilos. Dentre os\nabaixo, o volume corpuscular médio (em fl) mais provável e o tratamento mais adequado são,\nrespectivamente:","options":{"A":"115, transfusão de concentrado de hemácias e folato.","B":"75, transfusão de concentrado de hemácias e ferro.","C":"75, albendazol e corticoide.","D":"75, albendazol e ferro.","E":"115, corticoide e vitamina B12."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-34032","number":"34032","sourceNumber":"34032","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual a causa mais comum de priapismo em crianças?","options":{"A":"Medicamentosa.","B":"Anemia falciforme.","C":"Leucemia.","D":"Trauma."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-34004","number":"34004","sourceNumber":"34004","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente com 70 anos de idade, com quadro de mal-estar, descoramento\ncutaneomucoso e fraqueza. Exames mostram Hb:\n9,7 g/dl, Leucócitos: 2800/ul, Neutrófilos:\n1.900/ul, Plaquetas: 100.000/ul; Mielograma: medula óssea hipercelular, com diseritropoiese\nmoderada em série vermelha, série granulocítica com disgranulopoiese moderada com 4% de\nmieloblastos e ausência de bastonetes de Auer, série megacariocítica sem alterações. Segundo a\nOrganização Mundial de Saúde (WHO ? OMS), trata-se de um caso de:","options":{"A":"Citopenia refratária com displasia de múltiplas linhagens.","B":"Anemia refratária com excesso de blastos em transformação.","C":"Anemia refratária com excesso de blastos tipo I.","D":"Anemia refratária com excesso de blastos tipo II."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-35651","number":"35651","sourceNumber":"35651","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia falciforme é frequente em nosso meio e caracterizada por doença hemolítica\ncrônica e grave, resultante da destruição prematura dos eritrócitos. Relativamente a esta doença,\nindique a assertiva correta:","options":{"A":"A crise dolorosa deve ser tratada com a transfusão sanguínea.","B":"Quando ocorre osteomielite, a salmonella é um agente etiológico importante a ser considerado.","C":"A dactilite ocorre por isquemia de partes moles de mãos e pés em geral em crianças menores de\ndois anos.","D":"A vacina contra pneumococo deve ser feita em crianças maiores de dois anos e confere ampla\nproteção contra esse agente.","E":"A crise de sequestro é mais comum após cinco anos de idade."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-34039","number":"34039","sourceNumber":"34039","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em pacientes com anemia falciforme, a:","options":{"A":"asplenia funcional ocorre desde o nascimento, devendo a penicilina benzatina ser utilizada\njuntamente com as vacinas BCG e hepatite B, a cada três semanas, até os cinco anos de idade.","B":"hemoglobina S é resultado da troca de um par de bases (tiamina por adenina) na posição 6 do\ncódon do gene da ß-globina, o que codifica a\ntroca do ácido glutâmico por valina na posição 6 da\ncadeia ßs.","C":"capacidade de transporte de oxigênio está reduzida a 20% da apresentada por uma hemácia\nnormal, apesar das hemácias possuírem uma vida média de 120 dias.","D":"crise de sequestro esplênico é comum na faixa etária de 5 a 15 anos, coincidente com a maior\nincidência de infecção pelo Parvovírus B19, nessa faixa etária."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-22999","number":"22999","sourceNumber":"22999","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um paciente portador de anemia falciforme é internado com febre, taquipneia, dor\ntorácica intensa e radiografia de tórax com infiltrado heterogêneo. Evolui, 24 horas depois, com\npiora do quadro clínico e hipoxemia severa. Qual o provável diagnóstico e qual a conduta mais\nadequada, nesse caso?","options":{"A":"Síndrome torácica aguda: suporte ventilatório.","B":"Pneumonia: antibioticoterapia ambulatorial.","C":"Insuficiência cardíaca congestiva: diurético endovenoso.","D":"Tromboembolismo pulmonar: iniciar anticoagulação com varfarina."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-27201","number":"27201","sourceNumber":"27201","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Dentre as alternativas abaixo, qual representa fatores/grupos de risco para anemia\nferropriva:","options":{"A":"Recém-nascido prematuro e o recém-nascido grande para a idade gestacional.","B":"Baixo peso ao nascer e ingestão excessiva de leite de vaca.","C":"Refluxo gastroesofágico e fórmulas lácteas infantis.","D":"Leite de cabra e escolares.","E":"Icterícia fisiológica e doença hemorrágica do recém-nascido."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-8941","number":"8941","sourceNumber":"8941","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente do sexo feminino, 30 anos, apresenta dispneia aos grandes esforços, pressão\nsistólica de 90/60 mmHg, cianose de extremidade (+/4+), Hemoglobina de 8,5 g/dl e gasometria\ncom PaO2 de 60 mmHg, PaCO2 de 30 mmHg, pH de 7,35, saturação de oxigênio de 91% e\nbicarbonato normal. Conduta:","options":{"A":"Intubação mais O2","B":"Mascara de Venturi, pois ela oferece oxigênio de 60%","C":"Tratar anemia","D":"Cateter de O2 a 10 L/min"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-274008","number":"274008","sourceNumber":"274008","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia é um dos problemas mais comuns no atendimento pediátrico. Sobre as\ncausas de anemia, assinale a alternativa\nCORRETA:","options":{"A":"A esferocitose hereditária apresenta teste de fragilidade osmótica com curva hemolítica.","B":"A talassemia resulta de uma alteração enzimática hereditária que afeta a estabilidade da célula\neritróide.","C":"A reticulocitose, a persistência de hemoglobina fetal, a esferocitose hereditária e deficiência\nde\nfolato são causas de macrocitose.","D":"A hemoglobinúria paroxística noturna e as anemias microangiopáticas são exemplos de anemias\nhipoproliferativas."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-250260","number":"250260","sourceNumber":"250260","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mãe, em consulta médica, traz sua filha de 1 ano e 6 meses, queixando que a criança\ntem problema na absorção do ferro. A menina faz\nuso de sulfato ferroso há um ano, de forma\nregular, obedecendo o tempo de uma hora na administração antes das refeições e persiste com\nanemia. Aleitamento materno exclusivo até o sexto mês de vida. Antecedentes pessoais sem\nintercorrências. Alimentação atual carne vermelha 3 vezes por semana, frutas, carne branca, arroz.\nExame físico palidez +/4+. Exames leucócitos 5.500/mm³ (neutrófilos 45%, linfócitos 50%,\nmonócitos 4%, eosinófilos 1%), Hb 10,7g/dL, VCM 55, HCM 25, CHCM 30, RDW 13%, análise do\nesfregaço de sangue periférico: hipocromia, microcitose, pontiados basófilos, reticulócitos 3%.\n\nDevemos solicitar qual exame para confirmar a hipótese diagnóstica mais provável?","options":{"A":"Biópsia de duodeno.","B":"Curva de resistência globular osmótica.","C":"Biópsia de medula óssea.","D":"Eletroforese de hemoglobina."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-250276","number":"250276","sourceNumber":"250276","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A doença falciforme é um grupo de distúrbios genéticos com manifestações sistêmicas\ncaracterizadas por hemólise crônica e complicações agudas que podem levar a risco de morte e\ngraus variáveis de disfunções orgânicas. Com relação as complicações agudas da doença\nfalciforme, marque a opção INCORRETA:","options":{"A":"A crise vaso-oclusiva é a principal manifestação clínica da doença falciforme e pode ocorrer em\npacientes com idade inferior a seis meses. A dor resulta de isquemia e pode ser de extrema\nintensidade. A primeira manifestação da crise vaso-oclusiva pode ocorrer na forma de dactilite\nisquêmica (dor e edema de mãos e pés).","B":"A crise aplástica leva a aplasia permanente da série vermelha por conta da citotoxicidade do\nParvovírus aos precursores hematopoiéticos, nem sempre acompanhada do exantema\ncaracterístico.","C":"A associação entre síndrome torácica aguda e crise álgica é comum. Episódios graves e\nrecorrentes da síndrome torácica aguda podem\nevoluir para hipertensão pulmonar e cor pulmonale.","D":"O sequestro esplênico é diagnosticado mediante sinais de agudização da anemia e aumento\nabrupto do baço. O quadro pode evoluir para\nchoque hemorrágico e óbito."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-176186","number":"176186","sourceNumber":"176186","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre as anemias, é correto afirmar, EXCETO:","options":{"A":"Embora o estafilococo seja muito comum como etiologia de osteomielite em outros contextos, a\nprincipal etiologia na osteomielite relacionada à necrose óssea isquêmica do paciente com anemia\nfalciforme é a salmonela. Episódios vaso-oclusivos no paciente falcêmico estão necessariamente\nassociados à piora da hemólise e queda da hemoglobina.","B":"Cirurgias abdominais podem levar à anemia megaloblástica por deficiência de vitamina B12\natravés de vários procedimentos e\nmecanismos diferentes: gastrectomia, síndrome da alça cega\ncom supercrescimento bacteriano e ressecção do íleo. Valores elevados de ácido metilmalônico e\nde homocisteína ajudam na confirmação diagnóstica.","C":"A anemia ferropriva evolui em etapas específicas: primeiro ocorre a queda da ferritina, depois\nocorre a queda da hemoglobina e, por\núltimo, ocorre a queda do VCM. Entretanto, considerando\nque a ferritina pode aumentar em resposta à inflamação, uma ferritina normal ou mesmo elevada,\ndependendo do contexto clínico, não exclui o diagnóstico de ferropenia.","D":"Embora boa parte dos casos de anemia hemolítica autoimune seja idiopática, alguns estão\nassociados a lúpus eritematoso sistêmico,\nleucemia linfoide crônica ou linfomas. Casos refratários à\nprednisona podem ser tratados com esplenectomia ou até mesmo imunoglobulina.","E":"A anemia aplásica, embora tenha esse nome, pode se apresentar como pacitopenia. Parece\nhaver uma associação entre esta patologia e a\nhemoglobinúria paroxística noturna."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-155277","number":"155277","sourceNumber":"155277","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre anemia aplásica, é correto afirmar, EXCETO:","options":{"A":"Esplenomegalia e reticulocitopenia são achados comuns.","B":"Apesar de o nome remeter a uma única linhagem celular, geralmente o paciente se apresenta\ncom pancitopenia.","C":"A patogênese mais comum parece ser a supressão medular autoimune mediada por células T.","D":"O tratamento de escolha para pacientes adultos jovens com doador compatível é o transplante\nde medula óssea alogênico.","E":"Para pacientes acima de 40 anos, prefere-se o tratamento com globulina antitimócito e\nciclosporina."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-131879","number":"131879","sourceNumber":"131879","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"De acordo com o Protocolo Clínico e Diretrizes Terapêuticas (Portaria SAS/MS\n55/2010) para Doença Falciforme, serão\nincluídos nesse protocolo de tratamento os pacientes que\napresentarem pelo menos um dos seguintes critérios nos últimos 12 meses:","options":{"A":"Dois ou mais episódios de crises de dor, com necessidade de atendimento médico hospitalar.","B":"Idade superior a 5 anos.","C":"Concentração de hemoglobina <7g/dL (média de 3 valores fora do evento agudo).","D":"Hipoxemia crônica: saturação de oxigênio persistentemente menor que 92% medidas em duas\nvisitas clínicas consecutivas fora do evento agudo.","E":"Contagem de leucócitos maior ou igual a 30.000/mm³, na ausência de infecção."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-131885","number":"131885","sourceNumber":"131885","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Menino de 2 anos de idade é trazido pela mãe ao pronto atendimento com quadro de\nfebre, prostração e dor nas articulações de início há dois dias. Ao exame físico, a criança\napresenta-se com choro intenso, pálido, taquipneico, taquicárdico, edema de mãos e punhos. A\nmãe relata que seu filho sempre teve anemia e já recebeu duas transfusões de sangue. Assim,\npode afirmar-se que:","options":{"A":"A informação da mãe não ajuda a definir o diagnóstico, portanto, deve ser ignorada.","B":"Deve-se pensar em esferocitose hereditária como principal hipótese diagnóstica.","C":"A doença falciforme deve ser considerada como provável hipótese diagnóstica.","D":"O quadro clínico não permite pensar em uma hipótese diagnóstica.","E":"A principal hipótese é a doença de Kawasaki."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-80923","number":"80923","sourceNumber":"80923","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à anemia hemolítica, é CORRETO afirmar:","options":{"A":"O paciente apresenta hiperuricemia.","B":"Se a hemólise for intravascular, haverá hemoglobinúria e hemossiderinúria.","C":"A contagem de reticulócitos está normal.","D":"Os níveis de haptoglobina aumentam na tentativa de se ligar a toda hemoglobina liberada das\nhemácias.","E":"Desidrogenase láctica está aumentada somente quando a hemólise é induzida por exercício\nfísico."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-80875","number":"80875","sourceNumber":"80875","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher, 66 anos, com queixa de cansaço progressivo. Exames mostram Hb: 8,7 g/dl;\nHtc: 26%; VCM: 123 fl; HCM: 30,4 pg; RDW 25%;\nplaquetas: 170.000/mm³; reticulócitos: 0,5%;\nbilirrubinas totais: 1,0 mg/dl; Ferro sérico: 86 mcg/dl; ferritina: 200 ng/ml; PCR: 3,0 mg/dl;\nvitamina\nB12: 240 pg/ml (Referência: 239-931 pg/ml); ácido metilmalônico: 350 nanomol/L (Referência:\n\n70-270 nanomol/L); homocisteína: 50 micromol/L (Referência:1-15 micromol/L). A principal causa\nda anemia da paciente é:","options":{"A":"Anemia ferropriva.","B":"Anemia de doença crônica.","C":"Anemia hemolítica.","D":"Talassemia.","E":"Deficiência de vitamina B12."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-80908","number":"80908","sourceNumber":"80908","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A asplenia funcional é um fenômeno que ocorre progressivamente na criança com\nanemia falciforme. São medidas corretas para diminuir a probabilidade de infecções graves,\npropostas pelo Ministério da Saúde, EXCETO:","options":{"A":"Profilaxia com penicilina benzatina ou V oral até os 10 anos de idade.","B":"Vacina polissacáride contra pneumococo: 1 dose após 2 anos de idade, reforço após 5 anos.","C":"Vacina antivaricela: dose única após 1 ano de idade.","D":"Vacina anti-hepatite A: uma dose após 1 ano de idade, reforço após 6 meses.","E":"Profilaxia com eritromicina em caso de alergia à penicilina."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-62561","number":"62561","sourceNumber":"62561","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O ferro da dieta existe sob duas formas químicas: o ferro heme, que é encontrado na\nhemoglobina, mioglobina e nas enzimas (ferro em alimentos de origem animal) e o ferro não heme,\nque é encontrado, principalmente, em alimentos de origem vegetal. A absorção intestinal do ferro\nheme e não heme acontece por meio de processos diferentes no enterócito. A absorção de ferro é\ninfluenciada por diversos fatores, EXCETO:","options":{"A":"Pelas reações de oxidação e redução que são elementos altamente reativos que podem interagir\ncom o oxigênio e formar produtos\nintermediários os quais podem agir como radicais livres,\ndiminuindo a absorção.","B":"Pela dieta no caso do ferro não heme.","C":"Por um hormônio produzido no fígado chamado hepcidina, que atua inibindo a absorção de\nferro.","D":"Pela saturação de transferrina ou porcentagem de ferro ligado à transferrina que, se estiver\nbaixa, estimula a saída de ferro do enterócito para circulação pela membrana basolateral.","E":"Pela presença de fatores dietéticos estimuladores (ex.: Vitamina C) ou inibidores (ex.: Taninos)\nde sua absorção."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-47443","number":"47443","sourceNumber":"47443","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A manutenção de baço acessório ou implantes de fragmentos de tecidos esplênicos\nsão procedimentos cirúrgicos que devem ser considerados\nna remoção completa do baço.\n\nEntretanto, esses procedimentos podem contribuir para o insucesso terapêutico de qual das\ndoenças abaixo?","options":{"A":"Esferocitose hereditária.","B":"Talassemia maior.","C":"Anemia falciforme.","D":"Hipertensão porta.","E":"Deficiência de fator V."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-47466","number":"47466","sourceNumber":"47466","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um lactente saudável de 6 meses de idade chega ao consultório pediátrico para uma\nconsulta de rotina. Apresenta-se com o exame físico normal e crescimento e desenvolvimento\nadequados para a idade. Na investigação da história alimentar, o pediatra descobre que o lactente\nalimenta-se apenas com leite de cabra. Qual problema hematológico deve ser investigado?","options":{"A":"Anemia megaloblástica.","B":"Anemia ferropriva.","C":"Anemia hemolítica.","D":"Anemia falciforme.","E":"Anemia autoimune."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-35749","number":"35749","sourceNumber":"35749","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Na síndrome torácica aguda no paciente com anemia falciforme, deve-se avaliar a\nhipótese por Mycoplasma pneumoniae. Em caso de osteomielite no falcêmico, o agente etiológico\nque predomina, é:","options":{"A":"Staphylococcos áureos.","B":"Mycoplasma.","C":"Streptococcus viridams.","D":"Salmonella.","E":"Clamydia trachomatis."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-35781","number":"35781","sourceNumber":"35781","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Escolar pálido com cefaleia persistente, dor torácica, dores ósseas generalizadas,\nereção peniana persistente e dolorosa ocorre em:","options":{"A":"Anemia carencial.","B":"Anemia hemolítica.","C":"Anemia aplástica.","D":"Anemia autoimune.","E":"Anemia megaloblástica."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-28268","number":"28268","sourceNumber":"28268","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em qual das situações abaixo podemos encontrar aumento dos níveis séricos de\nvitamina B12?","options":{"A":"Policitemia vera","B":"Insuficiência pancreática;","C":"Síndrome de Zollinger-Ellison;","D":"Diphyllobothrium latum (infestação maciça)","E":"Metformina (uso prolongado)"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-11507","number":"11507","sourceNumber":"11507","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 24 anos, gestante de 20 semanas, em uso de sulfato ferroso, foi\nencaminhada ao hematologista para\ninvestigação de anemia microcítica e hipocrômica, com RDW\n(índice de variabilidade dos glóbulos vermelhos) normal, mas que apresenta diminuição gradativa\nde hemoglobina e do hematócrito apesar da reposição de ferro. Apresenta ferritina normal, mas não\ntrouxe dosagem do ferro sérico. Qual o diagnóstico possível e conduta adequada?","options":{"A":"Anemia de cooley, devendo-se solicitar eletroflorese de hemoglobina, onde haverá nível de\nhemoglobina fetal > 20%.","B":"Anemia ferropriva com complemento de ferro insuficiente; prescrever noripurum EV.","C":"Talassemia Minor, devendo-se solicitar eletroflorese de hemoglobina, onde haverá predomínio\nde hemoglobina A2.","D":"Anemia de Doença-Crônica; internar a paciente para investigação diagnóstica.","E":"Nenhuma das respostas acima."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-11510","number":"11510","sourceNumber":"11510","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à anemia hemolítica autoimune mediada por IgM, assinale a opção\nincorreta:","options":{"A":"A tipagem ABO das hemácias do paciente apresenta resultados duvidosos.","B":"O soro do paciente reage com hemácias A, B, AB e O.","C":"As provas pré-transfusionais devem ser realizadas a 37°C.","D":"As hemácias do paciente devem ser lavadas com salina aquecida antes dos testes\npré-transfusionais.","E":"Anemias hemolíticas autoimunes mediadas por IgM são denominadas de autoanticorpos a\nquente."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-11512","number":"11512","sourceNumber":"11512","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a opção incorreta no que se refere à hemoglobinúria paroxística noturna\n(HPN):","options":{"A":"Afeta somente os eritrócitos.","B":"Os pacientes podem desenvolver anemia por carência de ferro.","C":"Está associada à hemólise intravascular.","D":"Afeta leucócitos, eritrócitos e plaquetas.","E":"Fator Acelerador de Degradação (CD 55) e o inibidor da Lise de Membrana (CD 59), são\nproteínas deficientes na HPN."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hemato-hem-1-11432","number":"11432","sourceNumber":"11432","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 18 anos, admitida no serviço de emergência com hematócrito de 18%,\nVCM 114 fl, reticulócitos 18%, leucócitos 9.800/mm³ e plaquetas 220.000/mm³. No sangue\nperiférico, existem microesferócitos. O diagnóstico mais provável e o teste confirmatório são:","options":{"A":"Anemia megaloblástica e dosagem de vitamina B12.","B":"Anemia hemolítica autoimune e teste de Coombs direto.","C":"Hiperesplenismo e ultrassonografia do abdome.","D":"Anemia hemolítica e teste de Coombs indireto.","E":"Anemia megaloblástica e dosagem de homocisteína e ácido metilmalônico."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-11500","number":"11500","sourceNumber":"11500","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Crianças de 03 anos atendida no SPA com síndrome mão-pé, febre, dor abdominal,\npalidez e discreta icterícia. Dentre as doenças hematológicas qual seria sua primeira hipótese:","options":{"A":"Leucemia.","B":"Anemia megaloblástica.","C":"Anemia Falciforme.","D":"Hemofilia.","E":"Anemia Ferropriva."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-311493","number":"311493","sourceNumber":"311493","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente submetido a By-pass gástrico há 10 anos para tratamento de obesidade\nmórbida vem ao consultório com queixas de dor,\nparestesias, fraqueza e glossite. A glicemia de\njejum é de 115 mg/dl, com Hb glicada de 5,6%. A provável causa da neuropatia periférica em\nquestão é:","options":{"A":"Diabetes Mellitus tipo 2.","B":"Deficiência de retinol.","C":"Deficiência de vitamina C.","D":"Síndrome de Wernicke.","E":"Deficiência de cobalamina."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-308634","number":"308634","sourceNumber":"308634","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre a Anemia Falciforme, é INCORRETO afirmar:","options":{"A":"É uma anemia hemolítica crônica.","B":"Eritrócitos em forma de foice causam oclusão dos vasos.","C":"Pode haver envolvimento do pulmão, com síndrome torácica aguda.","D":"Na hemoglobina S. a valina substitui o ácido glutâmico no sexto aminoácido da cadeia beta.","E":"do ponto de vista epidemiológico ocorre quase exclusivamente em asiáticos."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-302119","number":"302119","sourceNumber":"302119","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactente de dois anos, com anemia falciforme, chegou ao pronto-socorro com história\nde dor em membros inferiores, febre de 38,5ºC\ne tosse há três dias. Ao exame físico está\nhipocorado ++/4+, eupneico, sem hepatoesplenomegalia, sem edema ou sinais flogísticos em\nmembros inferiores. Raio-X de tórax normal. A conduta adequada para o caso é:","options":{"A":"analgesia - internar com antibioticoterapia via parenteral","B":"analgesia - liberar com antibioticoterapia via oral","C":"analgesia - encaminhar para reavaliação ambulatorial","D":"anti-inflamatório - liberar com antibioticoterapia via oral","E":"analgesia - hidratação oral"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-263700","number":"263700","sourceNumber":"263700","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Senhora Ilda, 65 anos de idade, viúva há 2 anos, costureira aposentada, fumante\ninveterada, procurou a UBS (Unidade Básica de\nSaúde) de sua comunidade com queixas de\ncansaço e sensação de queimação em seus pés nos últimos seis meses. Um hemograma mostrou\nanemia com VCM (Volume Corpuscular Médio) aumentado. Qual das seguintes alternativas é a\ncausa mais provável de sua anemia?","options":{"A":"Talassemia.","B":"Deficiência de ferro.","C":"Perda sanguínea gastrointestinal crônica.","D":"Falta de fator intrínseco.","E":"Doenças da tireoide."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-263719","number":"263719","sourceNumber":"263719","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Quais as alterações são comumente encontradas em um paciente com anemia\nferropriva?","options":{"A":"VCM baixo e RDW alto.","B":"VCM baixo e RDW baixo.","C":"VCM baixo e RDW normal.","D":"VCM alto e RDW alto.","E":"VCM alto e RDW baixo."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-263755","number":"263755","sourceNumber":"263755","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Segundo a OMS, a cada ano nascem, no Brasil, cerca de 2.500 crianças portadoras de\ndoença falciforme (DF). Em funções relacionadas\nà hemoglobinopatia, 20% delas não vão atingir 5\nanos de idade.","options":{"A":"Pacientes com resultado HbFA na eletroforese de hemoglobina na triagem neonatal deverão ser\nencaminhados, imediatamente, para atendimento de pessoa com doença falciforme.","B":"A doença falciforme é uma anemia hemolítica hereditária autossômica dominante, caracterizada\npor um tipo de hemoglobina mutante.","C":"A dificuldade de opsonização em pacientes com doença falciforme não os torna mais\nsusceptíveis às infecções por germes encapsulados (dentre outros).","D":"Pacientes com Doença Falciforme que apresentam sintomas neurológicos agudos devem ser\nsempre encaminhados para ambulatório de neurologia pediátrica.","E":"O diagnóstico laboratorial da doença falciforme é realizado pela detecção da Hemoglobina S\n(HbS) e da sua associação com outras frações."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-278967","number":"278967","sourceNumber":"278967","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"O curso clínico da forma HbSS da doença falciforme geralmente é:","options":{"A":"Benigno.","B":"Grave.","C":"Leve.","D":"Moderado.","E":"Indeterminado."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-252399","number":"252399","sourceNumber":"252399","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Qual dos seguintes testes é o que apresenta melhor relação custo-benefício na\nsuspeição de deficiência de cobalamina?","options":{"A":"Folato sérico","B":"Níveis séricos de homocisteína","C":"Vitamina B12 sérica","D":"Pepsinogênio sérico","E":"Níveis séricos de metilmalonato"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-203600","number":"203600","sourceNumber":"203600","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"São manifestações clínicas da Anemia falciforme, EXCETO:","options":{"A":"Priapismo.","B":"Crescimento e desenvolvimento puberal precoce.","C":"Retinopatias proliferativas.","D":"Vasculopatia cutânea.","E":"Síndrome mão-pé."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-175017","number":"175017","sourceNumber":"175017","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia microcítica caracterizada por ferro sérico diminuído, TIBC diminuído, ferritina\nnormal ou aumentada e RDW normal é:","options":{"A":"Anemia ferropriva.","B":"Talassemia.","C":"Anemia de doença crônica.","D":"Anemia sideroblástica.","E":"Anemia falciforme."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-175076","number":"175076","sourceNumber":"175076","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma lactente de dois anos, com anemia falciforme, chegou ao pronto- socorro com\nhistória de dor em membros inferiores, febre de 38,5 °C e tosse há três dias. Ao exame fisíco está\nhipocorado ++/4+, eupneico, sem hepatoesplenomegalia, sem edema, ou sinais flogisticos em\nmembros inferiores. Raio X de tórax normal. A conduta adequada, somente para esse caso, é:","options":{"A":"analgesia - liberar com antibioticoterapia via oral.","B":"analgesia - internar com antibioticoterapia via parenteral.","C":"analgesia - encaminhar para reavaliação ambulatorial.","D":"anti-inflamatório - liberar com antibioticoterapia via oral.","E":"anti-inflamatório - liberar com analgésicos via oral."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-177531","number":"177531","sourceNumber":"177531","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Maria Clara tem 7 anos, portadora de anemia falciforme, deu entrada no pronto\natendimento com quadro de febre, dor na\nregião da perna direita. Ao exame físico, a criança\nencontrava-se febril, hipocorada++/4+, com edema, dor à manipulação e hiperemia na região da\nperna direita. Mãe relata que a criança sofreu uma queda há 9 dias na perna direita. Selecione a\nopção que corresponde ao diagnóstico e os dois principais microrganismos envolvidos.","options":{"A":"Osteomieliete; Staphylococcus aureus e Streptococcus pyogenes","B":"Osteomielite; Salmonella e Staphylococcus aureus","C":"Osteomielite; Salmonella e Streptococcus pyogenes","D":"Celulite; Staphylococcus aureus e Streptococcus pyogenes","E":"Celulite; Salmonella e Streptococcus pyogenes"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-154427","number":"154427","sourceNumber":"154427","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 54 anos, sexo masculino, negro, casado, lavrador, natural e procedente de\nCodó - MA. Desconhece comorbidades.\nProcurou o posto de saúde referindo cansaço aos esforços\nhabituais, dificultando suas atividades laborativas há algumas semanas. Mais recentemente, notou\nperda de apetite, palpitações, sonolência excessiva e dores de cabeça recorrentes. Era\npreviamente hígido e disposto. Realizou exames laboratoriais que evidenciaram: Hemoglobina =\n7,2 VCM 68 RDW 15,3% Cr 1,1 Ur 42. Sinais vitais: PA = 140 x 90; FC 106; FR 17; Temperatura\n36,5ºC. Qual a sua principal hipótese diagnóstica e recomendação?","options":{"A":"Anemia da doença crônica. Investigar neoplasias malignas.","B":"Anemia ferropriva por déficit nutricional. Iniciar reposição parenteral de ferro imediata e\norientar\nhábitos alimentares.","C":"Anemia falciforme. Eletroforese de hemoglobina e tranfusão sanguínea.","D":"Hemólise por crise hipertensiva. Realização de MAPA e início de tratamento anti-hipertensivo.","E":"Anemia ferropriva por perda crônica. Realização de Endoscopia digestiva alta e colonoscopia."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-160439","number":"160439","sourceNumber":"160439","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A Doença Falciforme (DF) é uma das doenças hereditárias mais comuns no mundo. A\nmutação teve origem no continente africano e pode ser encontrada em populações de diversas\npartes do planeta, com altas incidências na África, Arábia Saudita e Índia. No Brasil devido à\ngrande presença de afrodescendentes, que são uma das bases da população do país, a DF\nconstitui um grupo de doenças e agravos relevantes. É CORRETO afirmar que:","options":{"A":"Os pacientes são mais predispostos a infecções causadas por bactérias não capsuladas, por\ndeficiência de opsonização.","B":"A esplenomegalia é comum em qualquer faixa etária nos portadores de hemoglobina SS.","C":"O homem com traço falciforme, também conhecido por traço de Hb S ou heterozigoto para Hb S,\ntambém costuma ser anêmico e necessitar de tratamento.","D":"A vacinação deve ser completa, inclusive para pneumococo, meningococo e gripe (duas doses\ncom intervalo de um mês, na primovacinação).","E":"Por ser uma anemia hemolítica, observa-se hiperbilirrubinemia direta e o número de reticulócitos\né aumentado."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-160389","number":"160389","sourceNumber":"160389","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança de 4 anos portadora de malformação congênita é encaminhada ao ambulatório\nde pediatria. Peso: 16kg. Hemograma: Ht: 28%, Hb:\n9,0g/dL e VCM: 66mm³. Diante da suspeita de\nanemia ferropriva, o pediatra instituiu tratamento com xarope de sulfato ferroso (250mg/10mL), 2,5\nmL uma vez ao dia. Na consulta de puericultura, um mês depois, os índices hemáticos\npraticamente não se alteraram. A melhor conduta nesse caso será:","options":{"A":"Manter a dose de sulfato ferroso e aguardar mais um mês.","B":"Iniciar investigação para outras causas de anemia.","C":"Orientar a nutrição e liberar a correção cirúrgica.","D":"Administrar transfusão de concentrado de hemácias.","E":"Corrigir a dose de ferro necessária para o tratamento."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-108058","number":"108058","sourceNumber":"108058","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Sobre a investigação das anemias, é INCORRETO:","options":{"A":"Dacriócitos podem ser visualizados no sangue periférico de pacientes com mielofibrose.","B":"Se o volume corpuscular médio estiver superior a 100 fl, o diagnóstico é de anemia\nmegaloblástica.","C":"Na anemia ferropriva, a capacidade total de ligação de ferro estará elevada.","D":"Os níveis de haptoglobina se reduzem na anemia hemolítica.","E":"A síndrome mielodisplásica promove anemia hipoproliferativa."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-87507","number":"87507","sourceNumber":"87507","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Avaliando a hematoscopia de sangue periférico e o EAS de um paciente, internado com\nanemia e icterícia a esclarecer, observou-se a presença de esquizócitos na circulação periférica,\nalém de hemoglobinúria. Qual das etiologias abaixo é mais condizente com a associação destes\ndois achados?","options":{"A":"Síndrome hemolítico-urêmica;","B":"Anemia falciforme;","C":"Hiperesplenismo;","D":"Hemoglobinúria paroxística noturna;","E":"Deficiência de G6PD."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-89552","number":"89552","sourceNumber":"89552","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em um atendimento de uma criança de 9 anos com anemia falciforme, com queixa de\nfebre (39°C), prostração e taquicardia, o hemograma revelou leucocitose de 20.000 células/mm³ e\nhemoglobina de 8 g/dl. rx de tórax com infiltrado pulmonar difuso bilateral. A mãe traz consigo\nhemograma realizado na última consulta de rotina com hemoglobina de 8,5 g/dl e leucócitos de\n\n18.000 células/mm³. Todas as alternativas são importantes para justificar internação, exceto:","options":{"A":"Rx de tórax alterado","B":"Febre > 38°C","C":"Alterações do hemograma","D":"Prostração e taquicardia","E":"N.d.a."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-52490","number":"52490","sourceNumber":"52490","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à anemia e gestação todas as respostas estão corretas, exceto uma:","options":{"A":"a expansão da massa eritrocitária materna constitui a principal demanda de ferro na gestação.","B":"a Organização Mundial da Saúde (OMS) estabelece o limite de 11 g/dl para a concentração de\nhemoglobina, abaixo do qual se define anemia na gestação para qualquer período gestacional.","C":"o RDW, que avalia a variação do tamanho das hemáceas, pode ser útil para a definição da\nanemia ferropriva, quando superior a 16%.","D":"o receptor de transferrina geralmente não é afetado pela gestação.","E":"as gestantes devem fazer suplementação de ferro elementar, associados a outros\nmicronutrientes,\n\ncomo ácido fólico, vitamina C ou vitamina A, independente dos níveis de hemoglobina."},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-52450","number":"52450","sourceNumber":"52450","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à anemia ferropriva assinale a alternativa INCORRETA:","options":{"A":"A ingestão de grandes volumes de leite de vaca cru está relacionada a sangramento intestinal\ncrônico e anemia ferropriva.","B":"No tratamento dietético da anemia ferropriva deve-se evitar a clara de ovo pois esta diminui a\nbiodisponibilidade de ferro.","C":"Em lactentes de cor parda e desnutrido, um dado sugestivo de anemia ferropriva nos exames\nlaboratoriais é o desvio para direita dos neutrófilos e a presença de neutrófilos\nplurissegmentados.","D":"A ferritina sérica é um dado que fornece uma estimativa das reservas corporais de ferro.","E":"O tratamento ideal de uma criança com anemia ferropriva é a reposição oral de ferro em doses\nafastadas das refeições."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-52187","number":"52187","sourceNumber":"52187","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Em relação à anemia por deficiência de ferro, assinale a alternativa INCORRETA:","options":{"A":"A anemia por deficiência de ferro (ADF) constiui-se em carência nutricional relevante por suas\nrepercussões para o desenvolvimento infantil e magnitude de sua prevalência na atualidade.","B":"A maior vulnerabilidade das crianças menores de dois anos deve-se à necessidade de ferro para\no crescimento e à insuficiente ingestão desse\nnutriente, em quantidade e biodisponibilidade, na\ndieta habitual nessa faixa etária.","C":"Organizações internacionais apontam três estratégias para prevenção da anemia por deficiência\nde ferro: educação nutricional, fortificação de\nalimentos e suplementação com ferro.","D":"No Brasil, estima-se que não há anemia por deficiência de ferro nas crianças com idade entre\nseis e 24 meses de idade.","E":"O Brasil tornou obrigatória a fortificação das farinhas de trigo e milho com ferro e ácido\nfólico a\npartir de 2004 e implantou a suplementação preventiva com sulfato ferroso (SF) para grupos\nvulneráveis a partir de 2005."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-348477","number":"348477","sourceNumber":"348477","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mulher, 25 anos, com queixa de dor epigástrica, fadiga, dificuldade em concentração e\ndormência em mãos e pés. Foi realizado um hemograma que mostrou Hb de 9,8g/dL, Ht de 33%,\nVCM de 105fL, RDW de 16%. Quais exames complementares são necessários para o diagnóstico\ndefinitivo e qual o tratamento indicado para essa paciente?","options":{"A":"Dosagem de ferro sérico, ferritina e capacidade total de ligação ao ferro; suplementação oral de\nferro.","B":"Dosagem de vitamina B12 sérica e endoscopia digestiva alta; injeção mensal de vitamina B12.","C":"Dosagem de vitamina B12 e ultrassonografia abdominal; suplementação oral de vitamina B12.","D":"Dosagem de reticulócitos, bilirrubinas, LDH, coombs direto e indireto; suplementação oral de\nferro."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-348443","number":"348443","sourceNumber":"348443","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente, 13 anos, sexo masculino, dá entrada em UPA 24 horas, queixando-se de\ndor de forte intensidade (08 em 10 segundos a escala visual analógica de dor) em membro inferior\nesquerdo com início há 4 horas. A mãe deu em casa um comprimido de dipirona 500mg e\naumentou a oferta de líquidos, porém não houve melhora da dor. Informa que o paciente vem\napresentando rinorreia, tosse produtiva e febre baixa (38,5 °C) há 3 dias. HPP: Possui diagnóstico\nde anemia falciforme desde os primeiros meses de vida e normalmente apresenta hemoglobina\nbasal em torno de 8,0g/dL. Vacinação adequada para a idade. Ao exame físico inicial, paciente\napresenta-se em REG, fáscie de dor, hipocorado 3+/4+, acianótico, anictérico, desidratado 2+/4+ e\nafebril. FC: 110bpm, FR: 24irpm e SpO2: 95% em ar ambiente. Oroscopia e Otoscopia sem\nalterações. Ausência de sinais meníngeos. ACV: RCR em 2T, BNF e SS. Pulsos amplos e boa\nperfusão periférica. AR: MVF em ápices e bases, roncos discretos em ambos hemitóraces.\n\nAbdominal: Atípico, RHA presentes, indolor e ausência de massas ou visceromegalias. Exame\ngenital sem alterações. Membros inferiores\nsimétricos, ausência de sinais inflamatórios e limitação\ndos movimentos à esquerda. Diante do quadro clínico apresentado, quais são as condutas\nterapêuticas e propedêuticas iniciais?","options":{"A":"Após a avaliação inicial, o paciente pode ser liberado para uso de analgésicos comuns em casa.\n\nA princípio como se trata apenas de quadro álgico não há necessidade de realização de exames\nlaboratoriais ou da radiografia de tórax. Os familiares devem ser orientados em relação a sinais de\npiora clínica para retorno à unidade de pronto atendimento.","B":"Manter o paciente em observação, fornecer hidratação endovenosa, otimizar a analgesia, e\nrealizar a transfusão de concentrado de\nhemácias com urgência devido sinais de gravidade iniciais.\nSolicitar exames laboratoriais e radiografia de tórax para exclusão de complicações bacterianas.","C":"Manter o paciente em observação, iniciar hidratação endovenosa, associar analgésicos comuns,\nantiinflamatórios não esteroidais e opioides de horário para dor. Solicitar exames laboratoriais e\nradiografia de tórax para exclusão de complicações bacterianas e avaliar a necessidade de\ntransfusão sanguínea.","D":"Após a avaliação inicial, o paciente pode ser liberado para uso das medicações analgésicas\norais em casa. Exames laboratoriais para\nexclusão de complicações bacterianas e radiografia de\ntórax devem ser mostrados em reavaliação que deve ocorrer no máximo em 48 horas."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-330894","number":"330894","sourceNumber":"330894","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Lactente, cujos pais são portadores de traço falciforme, vem para primeira consulta de\npuericultura com resultado do teste do pezinho na pesquisa de hemoglobinopatias apresentando\npadrão HbAF. Ao constatar esse padrão de hemoglobina, o que se conclui?","options":{"A":"Filho de pais com traço falciforme apresentando traço falciforme.","B":"Filho de pais com traço falciforme apresentando anemia falciforme.","C":"Filho de pais com traço falciforme apresentando padrão normal.","D":"Não deve ser filho do casal com esse resultado."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-313389","number":"313389","sourceNumber":"313389","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Adolescente, 16 anos, sexo feminino, vem para consulta referindo realizar dieta vegana\nrestrita. Qual nutriente poderá entrar em deficiência e deverá ser reposto por seu pediatra que é\nfundamental na conversão da homocisteína em metionina e na conversão do metiltetra-hidrofolato\nem tetrahidrofolato influenciando toda a síntese de DNA celular?","options":{"A":"Piridoxina.","B":"Ácido fólico.","C":"Colecalciferol.","D":"Cianocobalamina."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-288140","number":"288140","sourceNumber":"288140","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"A anemia pode ser a causa de uma astenia, porém pode ser consequência de outras\npatologias. Em relação à anemia, assinale a afirmativa CORRETA:","options":{"A":"A anemia ferropriva grave apresenta eritrócitos com macrocitose.","B":"A anemia hemolítica, embora marcante, está entre as formas mais comuns de anemia.","C":"Os eritrócitos na uremia podem adquirir numerosas projeções espinhosas regularmente\nespaçadas.","D":"A macrocitose é caracterizada pela presença de eritrócitos microcíticos e hipocrômicos."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-267334","number":"267334","sourceNumber":"267334","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente A.C.O., 5 meses de vida, vai a sua primeira consulta de puericultura no Centro\nde Saúde Escola. A mãe queixa-se de que a\nfilha é muito pálida e dorme muito. Está em\naleitamento materno exclusivo. Na história familiar, a mãe relata que foi diagnosticada com câncer\ngástrico e na ocasião realizou cirurgia no estômago, mas não sabe dar maiores detalhes sobre o\nprocedimento e não faz reposição de micronutrientes. Ao exame físico, o médico nota baixo peso,\npalidez cutâneo-mucosa 3+/4+, taquicardia, fígado palpável no rebordo costal direito e baço\npalpável a 1 cm do rebordo costal esquerdo. Pela hipótese de síndrome anêmica, o médico solicita\nexames para elucidação diagnóstica, incluindo hemograma com urgência. O resultado do\neritrograma é: Hemoglobina 7,0 g/dl, Hematócrito 21%, VCM 105 fl, HCM 28 pg, RDW 20%. Com\nbase nessa situação clínica, assinale a principal hipótese diagnóstica e o tratamento proposto:","options":{"A":"Anemia megaloblástica; iniciar reposição de vitamina B12 e ácido fólico.","B":"Anemia ferropriva; iniciar reposição de ferro.","C":"Anemia falciforme; iniciar profilaxia com penicilina benzatina ou fenoximetilpenicilina\npotássica e\nácido fólico.","D":"Anemia autoimune; iniciar prednisona."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-255320","number":"255320","sourceNumber":"255320","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a alternativa que apresenta a alteração encontrada na deficiência de G6PD:","options":{"A":"Alteração enzimática.","B":"Alteração da membrana do eritrócito.","C":"Alteração numérica quantitativa da cadeia de hemoglobina.","D":"Alteração qualitativa de cadeia de hemoglobina."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-254173","number":"254173","sourceNumber":"254173","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a alternativa que indica uma causa de anemia microcítica.","options":{"A":"Insuficiência renal crônica","B":"Deficiência de Vitamina B12","C":"Talassemia","D":"Hemorragia aguda"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-247700","number":"247700","sourceNumber":"247700","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente portador de anemia falciforme, atualmente com 4 anos de vida, é atendido no\npronto atendimento com taquidispneia, palidez cutâneo-mucosa, dor torácica, FC 166 bpm, SO?\n\n88% em ar ambiente, obnubilado, PA 88/33 mmHg, pulsos finos, com tempo de reperfusão de 4-5\nsegundos, tax 39ºC, com murmúrio vesicular reduzido em base direita, associado a estertores\nsubcrepitantes homolaterais. Em relação ao paciente em questão, assinale a afirmativa que melhor\nsintetiza o atendimento de emergência:","options":{"A":"Oferta de oxigênio por dispositivo de alto fluxo, acesso venoso calibroso, coleta de culturas,\ninfusão de cristaloide e antibioticoterapia de largo espectro e glicemia capilar.","B":"Intubação orotraqueal em sequência rápida, acesso venoso calibroso, infusão de cristaloide,\ndobutamina e antibiótico de largo espectro.","C":"Oferta de oxigênio por cateter nasal, acesso venoso calibroso, glicemia capilar, coleta de\nexames laboratoriais, infusão de cristaloide e\ndopamina e antibiótico de largo espectro para\ntratamento de broncopneumonia.","D":"Oferta de oxigênio por cateter nasal, acesso venoso calibroso, coleta de exames, infusão de\ncristaloide, infusão de concentrado de hemácias e antibiótico de largo espectro."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-221365","number":"221365","sourceNumber":"221365","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Marque a afirmativa CORRETA levando-se em consideração o diagnóstico de\nSíndrome torácica aguda.","options":{"A":"A mortalidade é extremamente baixa.","B":"A oxigenoterapia está indicada apenas em hipoxemia severa.","C":"Caracteristicamente não há dor torácica.","D":"Podem ocorrem infartos pulmonares."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-221046","number":"221046","sourceNumber":"221046","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Criança de 2 anos é levada ao pronto atendimento com quadro de dor nas pernas, na\nregião lombar e nas mãos que se encontram edemaciadas. Febre baixa não aferida. Ao exame\nfísico apresenta-se chorosa, não permitindo a mobilização dos membros e das mãos. Palidez 3+/4,\nescleras ictéricas. Frequência cardíaca = 154 bpm; baço palpável a 4 cm do RCE; edema no dorso\ndas mãos e dedos, com discreta hiperemia. Exames laboratoriais iniciais: Hb = 6,5 g/dl; Htc = 19%;\nVCM = 78; reticulócitos = 6%; leucócitos totais = 18.640/mm³; neutrófilos = 48%; linfócitos = 56%;\neosinófilos = 1%; plaquetas = 180.000/mm³; bilirrubinas totais = 9,0 mg/dl; bilirrubina direta = 2,8\nmg/dl; bilirrubina indireta = 6,2 mg/dl; TGO = 40 UI/L; TGP = 51 UI/L. Em relação ao quadro acima,\no diagnóstico mais provável é:","options":{"A":"Anemia falciforme em crise de falcização.","B":"Hepatite viral com reação articular.","C":"Anemia ferropriva em paciente com artrite idiopática juvenil.","D":"Leucemia linfoide aguda."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-213962","number":"213962","sourceNumber":"213962","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mãe agenda consulta para o filho de 10 meses na UBS para solicitar um hemograma,\npois acha que o menino está com anemia.\nDurante a inspeção o médico verifica mucosas\nhipocoradas e sopro cardíaco discreto. Mãe refere que o filho nasceu a termo com 2,8 kg e que\nteste de pezinho veio sem alterações. Não está fazendo puericultura pois \"morava no sítio e achava\nmuito difícil ir até a unidade básica rural apenas para passar com a enfermeira\". Sobre o caso\nacima marque a alternativa CORRETA.","options":{"A":"Inicialmente o médico deve solicitar o hemograma para confirmar a suspeita de anemia.","B":"Anemia carencial por ferro é a causa mais comum de anemias, principalmente na infância.\nsendo alta sua suspeição no caso acima.","C":"No caso acima o tratamento via oral já pode ser iniciado com reposição por 2 meses na dose de\n1-2 mg por kg ao dia de ferro elementar.","D":"O melhor é prescrever um polivitamínico, pois pode haver a carência de outros minerais e\nvitaminas."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-208587","number":"208587","sourceNumber":"208587","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Uma mulher de 38 anos, portadora de mioma uterina, tem apresentado perda menstrual\naumentada nos últimos 6 meses. Está com taxa de hemoglobina = 8,5g/dL. Espera-se encontrar,\ntambém, exames laboratoriais com:","options":{"A":"ferro sérico baixo, capacidade total de ligação do ferro elevada e VCM = 70fL","B":"eritropoetina baixa, capacidade total de ligação do ferro baixa e VCM = 68fL","C":"ferro sérico baixo, eritropoetina baixa e VCM = 72fL","D":"ferro sérico baixo, saturação baixa, ferritina normal e VCM = 87FI","E":"nenhuma das alternativas anteriores"},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-208565","number":"208565","sourceNumber":"208565","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"De acordo com Protocolo Clínico e Diretrizes Terapêuticas - Portaria SAS/MS,\n1.247/2014, constitui-se em exame não obrigatório para o diagnóstico de anemia ferropriva:","options":{"A":"hemograma com avaliação do esfregaço periférico","B":"ferritina","C":"ferro sérico","D":"contagem de plaquetas","E":"avaliação dos índices hematimétricos"},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-185261","number":"185261","sourceNumber":"185261","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a alternativa que indica alterações do eritrograma sugestivas de talassemia:","options":{"A":"Hb:8 VCM:90","B":"Hb:10 VCM:110","C":"Hb:12 VCM:70","D":"Hb:6 VCM:80","E":"Hb:9,6 VCM:64"},"answer":"E","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-177326","number":"177326","sourceNumber":"177326","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um lactente de 1 ano e 2 meses é trazido para consulta de puericultura. Trata-se de\numa criança sem doença de base, nascida a\ntermo, sem intercorrências. Apresenta boas condições\nde moradia e higiene e nunca recebeu vitaminas, ferro ou vermífugos. Recebeu leite materno\nexclusivo até os 6 meses, quando foram introduzidos leite de vaca integral e alimentação\ncomplementar. Seu hemograma coletado há 15 dias mostrava Hb = 9,2g/dl, Ht = 28% e hemácias =\n3.000.000/mm³. E mais: leucócitos normais, sem eosinofilia, hipocromia moderada e microcitose. A\npossível causa para essas alterações hematológicas é:","options":{"A":"introdução tardia da alimentação complementar","B":"ausência de suplementação de ferro após os 6 meses","C":"ausência de vermifugação precoce","D":"consumo precoce de leite de vaca","E":"nenhuma das alternativas anteriores"},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-181557","number":"181557","sourceNumber":"181557","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente sexo masculino, 72 anos, hipertenso controlado, antecedente de cirurgia de\nvesícula há um ano, relata fraqueza progressiva há 4 meses, especialmente aos esforços. Nega\noutros sintomas associados. Apetite preservado. Ao exame, apresenta-se pálido (2+/4+), FC\n98bpm, FR 18irm, PA 140×90 mmHg. Sem outras anormalidades no exame físico. Traz\nhemograma colhido na UBS há 1 semana: Hb 7,2; Ht 19; VCM 68; HCM 20; RDW 19. Leucograma\ne contagem plaquetária normais. Qual a abordagem inicial para o referido caso?","options":{"A":"Reposição de ferro via preferencialmente oral e solicitar novo hemograma e reticulócitos de\ncontrole em 2 semanas.","B":"Reposição de vitamina B12 intra-muscular semanal associada a ácido fólico oral, com controle\nlaboratorial em 2 semanas.","C":"Solicitar exames endoscópicos do trato gastrointestinal para excluir fonte de perda sanguínea\ncrônica e iniciar reposição de ferro oral.","D":"Solicitar cinética do ferro e, caso confirme ferropenia, iniciar reposição de ferro via\npreferencialmente oral."},"answer":"C","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-181102","number":"181102","sourceNumber":"181102","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Mãe chega ao posto de saúde com filho de 4 meses. Refere que como \"não tem leite\"\nprefere alimentar a criança exclusivamente com leite de cabra. Com essa informação devemos\nprescrever a suplementação de:","options":{"A":"Vitamina D;","B":"Complexo B;","C":"Vitamina C;","D":"Ácido Fólico."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-181578","number":"181578","sourceNumber":"181578","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Um lactente de 20 dias é trazido a uma Unidade Básica de Saúde por sua mãe. Ela\nestá ansiosa com o resultado do teste do pezinho. O menino nasceu de 38 semanas pesando\n\n3.050 gramas. O resultado foi entregue por uma atendente e não foi explicado se havia\nanormalidades. Os resultados são os\nseguintes: Diante do exposto, qual é a conduta adequada\npara o caso?","options":{"A":"Explicar que se trata de um caso de doença falciforme e deverá iniciar, em momento adequado,\npenicilina e\n\nácido fólico.","B":"Explicar que a criança tem o traço falciforme e orientar o acompanhamento de crescimento e\ndesenvolvimento.","C":"Explicar que o teste está normal e orientar o acompanhamento de crescimento e\ndesenvolvimento.","D":"Explicar que a criança tem o traço falciforme e deverá iniciar, em momento adequado, penicilina\ne ácido fólico."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":["question_bank/media/medcurso/medcurso-hemato-hem-1/181578.png"],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-167806","number":"167806","sourceNumber":"167806","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Paciente de 20 anos, com anemia crônica e hepato-esplenomegalia discreta, negando\nhemotransfusão prévia. Das doenças hematológicas, qual o diagnóstico provável?","options":{"A":"Talassemia major (FF)","B":"Anemia falciforme (SS)","C":"Púrpura trombocitopênica idiopática","D":"Associação de hemoglobinopatias (SF,SC)"},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-156439","number":"156439","sourceNumber":"156439","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Durante a investigação de uma anemia ferropriva em uma criança de 9 anos de idade,\nqual dos seguintes resultados EXCLUI de vez a deficiência de ferro?","options":{"A":"Aspirado de medula óssea com reserva de ferro normal.","B":"Volume globular médio normal.","C":"Aumento do TIBC.","D":"Ferritina sérica normal."},"answer":"A","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-158122","number":"158122","sourceNumber":"158122","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"Assinale a alternativa que apresenta a associação INCORRETA entre doença e\nprovável agente etiológico:","options":{"A":"Síndrome mielodisplásica - benzeno.","B":"Tuberculose - silicose.","C":"Mesotelioma de pleura - asbestose.","D":"Anemia aplástica - amianto."},"answer":"D","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hemato-hem-1-158194","number":"158194","sourceNumber":"158194","collectionBlock":"medcurso:medcurso-hemato-hem-1","collectionLabel":"Medcurso · HEM 1","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"HEM 1","subtopic":"","stem":"H.B.C., 3 anos e 6 meses, menina, vem à consulta anual de pediatria, sem queixas. A\ncriança é filha única e fica na creche em período integral. De antecedentes fisiológicos, a mãe\nrefere que a criança nasceu prematura de 35 semanas, sem outras intercorrências. Na história\nalimentar, a mãe refere amamentação em seio materno exclusivamente até os três meses de idade,\nquando passou a dar fórmula infantil industrializada de primeiro semestre. Introduziu alimentos\ncomplementares aos 4 meses e leite de vaca integral a partir do 6º mês. Atualmente almoça e janta\na comida da família. Come arroz, macarrão, feijão, tomate, batata e carne de boi ou frango. Não\ncome muita carne e não gosta de outros legumes nem de verdura. Toma suco, come bolachas\nrecheadas e salgadinhos industrializados. Nunca tomou sulfato ferroso. De antecedentes\npatológicos, refere que a criança tem muitos resfriados e já teve vários episódios de diarreia desde\no nascimento. Ao exame físico, peso: 16,8 kg; comprimento: 96 cm; frequência cardíaca: 96 bpm;\nfrequência respiratória: 24 irpm; temperatura: 36,6 ºC. Está em bom estado geral, hidratada,\nanictérica e hipocorada (+1/+4). Ao exame físico segmentar, não foi encontrada qualquer\nanormalidade. Em relação a essa criança, são fatores de risco para o desenvolvimento de anemia\nferropriva:","options":{"A":"A interrupção precoce do aleitamento materno exclusivo, introdução precoce de fórmula infantil e\nnão introdução de profilaxia com ferro.","B":"Prematuridade, interrupção prepoce do aleitamento materno exclusivo, introdução precoce do\nleite de vaca e não introdução de profilaxia com ferro.","C":"Prematuridade, introdução precoce de fórmula infantil e não ingestão dos alimentos ricos em\nferro.","D":"Interrupção precoce do aleitamento materno exclusivo, infecções de vias respiratórias\nsuperiores, infecções intestinais de repetição e não\ningestão dos alimentos ricos em ferro."},"answer":"B","source":"Hemato/HEM 1/HEM 1.txt","sourceLabel":"Medcurso · HEM 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hematologia","HEM 1","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
